  let minrad=999; for(let i=0;i<N;i++){const A=ps[(i-4+N)%N],B=ps[i],D=ps[(i+4)%N]; const ab=A.distanceTo(B),bd=B.distanceTo(D),ad=A.distanceTo(D); const area=Math.abs((B.x-A.x)*(D.z-A.z)-(B.z-A.z)*(D.x-A.x))/2; minrad=Math.min(minrad, ab*bd*ad/(4*area||1));}
