:root {
  --lime: #d8ff5d;
  --lime-2: #a8f039;
  --lime-deep: #6fbf1e;
  --aqua: #7af3d5;
  --aqua-deep: #16a58e;
  --sun: #ffd356;
  --coral: #ff7a48;
  --cream: #f8f5e6;
  --ink: #072824;
  --ink-2: #0a3832;
  --glass: rgba(7, 38, 34, 0.62);
  --glass-strong: rgba(6, 31, 28, 0.86);
  --line: rgba(255, 255, 255, 0.15);
  --line-soft: rgba(255, 255, 255, 0.08);
  --shadow: 0 30px 80px rgba(0, 8, 6, 0.45);
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
}

* {
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #06211e;
  color: var(--cream);
  font-family: 'Outfit', 'Trebuchet MS', system-ui, sans-serif;
  overscroll-behavior: none;
  user-select: none;
  -webkit-user-select: none;
}

button {
  font: inherit;
  color: inherit;
  border: 0;
  background: none;
  cursor: pointer;
  touch-action: manipulation;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  isolation: isolate;
}

#game-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  outline: none;
}

.scene-grade {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(180deg, rgba(3, 25, 22, 0.18) 0%, transparent 22%, transparent 68%, rgba(3, 28, 24, 0.3) 100%),
    radial-gradient(ellipse at 52% 46%, transparent 38%, rgba(4, 27, 24, 0.2) 100%);
  z-index: 1;
}

.vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 2;
  box-shadow: inset 0 0 180px rgba(0, 20, 16, 0.38);
}

.hidden { display: none !important; }

/* ============ LOADING ============ */
.loading {
  position: absolute;
  inset: 0;
  z-index: 100;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 22px;
  background:
    radial-gradient(circle at 50% 40%, #14574c 0%, #082d29 45%, #041b18 100%);
}
.loading::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: radial-gradient(rgba(255,255,255,.06) 1px, transparent 1px);
  background-size: 24px 24px;
  opacity: .5;
}
.loading-mark { position: relative; text-align: center; }
.loading-logo {
  position: relative;
  font-family: 'Bungee', sans-serif;
  font-size: clamp(44px, 9vw, 80px);
  line-height: .9;
  letter-spacing: -.02em;
  color: var(--cream);
  text-shadow: 0 14px 40px rgba(0,0,0,.4);
}
.loading-logo span {
  display: block;
  color: var(--lime);
  font-size: 1.12em;
}
.loading-wave {
  position: absolute;
  width: 180px;
  height: 180px;
  left: 50%;
  top: 50%;
  translate: -50% -50%;
  border: 1px solid rgba(216,255,93,.3);
  border-radius: 50%;
  animation: pulse-ring 2s ease-out infinite;
}
@keyframes pulse-ring {
  0% { transform: scale(.65); opacity: .9; }
  100% { transform: scale(1.7); opacity: 0; }
}
.loading-bar {
  width: min(220px, 60vw);
  height: 4px;
  border-radius: 4px;
  background: rgba(255,255,255,.13);
  overflow: hidden;
}
.loading-bar i {
  display: block;
  height: 100%;
  width: 0;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--aqua), var(--lime));
  box-shadow: 0 0 18px rgba(216,255,93,.7);
  transition: width .35s ease;
}
.loading-tip {
  margin: 0;
  font-size: 11px;
  letter-spacing: .22em;
  text-transform: uppercase;
  color: rgba(255,255,255,.5);
}

/* ============ MENU ============ */
.screen {
  position: absolute;
  inset: 0;
  z-index: 10;
  padding: calc(20px + var(--safe-top)) calc(clamp(20px, 4.5vw, 68px) + var(--safe-right)) calc(16px + var(--safe-bottom)) calc(clamp(20px, 4.5vw, 68px) + var(--safe-left));
  display: flex;
  flex-direction: column;
  pointer-events: none;
}

.menu { animation: menu-in .7s cubic-bezier(.2,.8,.2,1) both; }
@keyframes menu-in { from { opacity: 0; } to { opacity: 1; } }

.menu::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(90deg, rgba(4, 27, 23, .8) 0%, rgba(4, 27, 23, .5) 30%, rgba(4, 27, 23, .04) 62%, transparent 100%),
    linear-gradient(0deg, rgba(4, 26, 22, .58) 0%, transparent 35%);
  z-index: -1;
}

.menu-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  pointer-events: auto;
  flex: 0 0 auto;
}
.mini-brand { display: flex; align-items: center; gap: 11px; }
.mini-brand-mark {
  width: 39px; height: 39px;
  display: grid; place-items: center;
  border-radius: 12px;
  font-family: 'Bungee', sans-serif;
  font-size: 16px;
  color: var(--ink);
  background: linear-gradient(145deg, var(--lime), var(--aqua));
  box-shadow: 0 7px 22px rgba(153, 240, 80, .26), inset 0 1px 0 rgba(255,255,255,.5);
  transform: rotate(-3deg);
}
.mini-brand-text { display: flex; flex-direction: column; line-height: 1.05; }
.mini-brand-text b { font-weight: 800; font-size: 15px; letter-spacing: .01em; }
.mini-brand-text span { font-size: 9px; text-transform: uppercase; letter-spacing: .17em; color: rgba(255,255,255,.5); margin-top: 3px; }
.menu-top-actions { display: flex; align-items: center; gap: 9px; }

.pill-btn {
  display: flex; align-items: center; gap: 8px;
  min-height: 42px;
  padding: 0 15px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: rgba(6, 34, 30, .5);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  font-weight: 800;
  font-size: 14px;
  position: relative;
  transition: .2s ease;
}
.pill-btn:hover { background: rgba(15, 57, 50, .7); transform: translateY(-1px); }
.coin-glyph {
  width: 20px; height: 20px;
  display: inline-grid; place-items: center;
  border-radius: 50%;
  font-size: 12px;
  line-height: 1;
  color: #7d5a05;
  background: radial-gradient(circle at 36% 30%, #fff4ad, #ffd351 55%, #dd9e18 100%);
  border: 1px solid rgba(255,255,255,.55);
  box-shadow: inset 0 -2px 4px rgba(150,90,0,.25), 0 2px 5px rgba(0,0,0,.25);
}
.coin-glyph.small { width: 16px; height: 16px; font-size: 10px; }
.daily-dot {
  position: absolute;
  top: 7px; right: 8px;
  width: 7px; height: 7px;
  border-radius: 50%;
  background: var(--coral);
  box-shadow: 0 0 0 2px rgba(6,30,27,.9), 0 0 12px var(--coral);
}
.icon-btn {
  width: 42px; height: 42px;
  display: grid; place-items: center;
  border-radius: 50%;
  border: 1px solid var(--line);
  background: rgba(6, 34, 30, .48);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  color: var(--cream);
  transition: .2s ease;
}
.icon-btn:hover { background: rgba(20, 65, 57, .7); transform: rotate(10deg); }

.menu-stage {
  flex: 1;
  display: flex;
  align-items: center;
  min-height: 0;
  pointer-events: none;
}
.hero {
  width: min(480px, 46vw);
  pointer-events: auto;
  animation: hero-in .8s .08s cubic-bezier(.2,.8,.2,1) both;
}
@keyframes hero-in {
  from { opacity: 0; transform: translateY(18px); }
  to { opacity: 1; transform: none; }
}
.eyebrow {
  display: flex; align-items: center; gap: 9px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .24em;
  color: var(--aqua);
  text-shadow: 0 2px 10px rgba(0,0,0,.4);
}
.eyebrow i {
  width: 22px; height: 1px;
  background: var(--aqua);
  box-shadow: 0 0 8px var(--aqua);
}
.logo {
  margin: 10px 0 12px;
  font-family: 'Bungee', sans-serif;
  font-weight: 400;
  font-size: clamp(58px, 8.2vw, 118px);
  line-height: .79;
  letter-spacing: -.025em;
  display: flex;
  flex-direction: column;
  filter: drop-shadow(0 18px 38px rgba(0, 12, 9, .38));
}
.logo span {
  color: #f9f7e8;
  transform: scaleX(1.02);
  transform-origin: left;
}
.logo strong {
  display: block;
  font-weight: 400;
  font-size: 1.05em;
  letter-spacing: -.035em;
  background: linear-gradient(180deg, #f4ffc0 2%, #d8ff5d 38%, #8de42e 75%, #5cb316 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  -webkit-text-stroke: 1px rgba(255,255,255,.08);
  filter: drop-shadow(0 4px 0 rgba(23, 75, 11, .38));
  transform: scaleX(1.03);
  transform-origin: left;
}
.tagline {
  margin: 0 0 24px;
  font-size: clamp(15px, 1.5vw, 18px);
  line-height: 1.35;
  font-weight: 500;
  color: rgba(248,245,230,.72);
  letter-spacing: .01em;
}
.tagline em { font-style: normal; color: rgba(255,255,255,.95); }

.race-facts {
  display: flex;
  gap: 26px;
  margin-bottom: 25px;
  padding-bottom: 21px;
  border-bottom: 1px solid var(--line-soft);
}
.race-facts div { display: flex; align-items: baseline; gap: 6px; }
.race-facts b {
  font-family: 'Bungee', sans-serif;
  font-size: 22px;
  font-weight: 400;
  color: var(--cream);
  line-height: 1;
}
.race-facts span {
  font-size: 9px;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: rgba(255,255,255,.45);
  font-weight: 700;
}
.cta-kicker {
  display: flex; align-items: center; gap: 7px;
  font-size: 9px;
  letter-spacing: .18em;
  font-weight: 800;
  color: rgba(255,255,255,.56);
  margin-bottom: 8px;
}
.live-dot {
  width: 5px; height: 5px;
  border-radius: 50%;
  background: var(--lime);
  box-shadow: 0 0 9px var(--lime);
  animation: blink 1.5s infinite;
}
@keyframes blink { 50% { opacity: .3; } }
.btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  min-height: 54px;
  padding: 0 24px;
  border-radius: 17px;
  font-weight: 800;
  font-size: 14px;
  letter-spacing: .06em;
  transition: transform .16s ease, box-shadow .16s ease, background .16s ease;
  overflow: hidden;
}
.btn:active { transform: scale(.975); }
.btn-primary {
  color: #132708;
  background: linear-gradient(180deg, #e9ff9c 0%, var(--lime) 45%, #aeee3b 100%);
  border: 1px solid rgba(255,255,255,.55);
  box-shadow: 0 12px 30px rgba(163, 234, 54, .22), inset 0 -3px 0 rgba(92, 153, 15, .24), inset 0 2px 0 rgba(255,255,255,.5);
}
.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 18px 42px rgba(163, 234, 54, .32), inset 0 -3px 0 rgba(92,153,15,.24), inset 0 2px 0 rgba(255,255,255,.5);
}
#quickRaceBtn {
  width: 100%;
  height: 66px;
  justify-content: space-between;
  padding: 0 24px 0 30px;
  font-family: 'Bungee', sans-serif;
  font-weight: 400;
  font-size: 24px;
  letter-spacing: .01em;
  border-radius: 19px;
}
#quickRaceBtn svg { width: 26px; height: 26px; }
.btn-glass {
  background: rgba(10, 48, 43, .62);
  border: 1px solid var(--line);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  color: var(--cream);
}
.btn-glass:hover { background: rgba(22, 74, 65, .8); transform: translateY(-1px); }
.btn-quiet {
  background: transparent;
  border: 1px solid transparent;
  color: rgba(255,255,255,.5);
  min-height: 44px;
  font-size: 12px;
}
.btn-quiet:hover { color: var(--cream); }

.mode-strip {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 7px;
  margin-top: 14px;
}
.mode-card {
  min-height: 58px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 12px;
  border-radius: 14px;
  border: 1px solid var(--line-soft);
  background: rgba(8, 40, 35, .44);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  text-align: left;
  transition: .18s ease;
  position: relative;
}
.mode-card:hover { background: rgba(21, 67, 58, .58); border-color: var(--line); transform: translateY(-1px); }
.mode-icon {
  flex: 0 0 auto;
  width: 33px; height: 33px;
  display: grid; place-items: center;
  border-radius: 9px;
  background: rgba(255,255,255,.07);
  color: var(--aqua);
}
.mode-text { display: flex; flex-direction: column; min-width: 0; line-height: 1.1; }
.mode-text b { font-size: 11px; letter-spacing: .08em; font-weight: 800; }
.mode-text small { font-size: 9px; color: rgba(255,255,255,.42); margin-top: 3px; letter-spacing: .01em; }
.mode-badge {
  margin-left: auto;
  align-self: flex-start;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .06em;
  padding: 3px 6px;
  border-radius: 6px;
  color: var(--lime);
  background: rgba(216,255,93,.1);
  border: 1px solid rgba(216,255,93,.18);
}
.mode-badge.alert { background: var(--coral); border-color: var(--coral); color: #fff; }

.menu-foot {
  display: flex; align-items: center; justify-content: space-between;
  gap: 20px;
  padding-top: 12px;
  border-top: 1px solid var(--line-soft);
  pointer-events: none;
}
.foot-tip { font-size: 9px; letter-spacing: .12em; text-transform: uppercase; color: rgba(255,255,255,.33); font-weight: 700; }
.foot-tip kbd {
  display: inline-block;
  min-width: 19px;
  padding: 2px 5px;
  margin: 0 2px;
  border-radius: 5px;
  border: 1px solid rgba(255,255,255,.16);
  background: rgba(255,255,255,.04);
  font-family: inherit;
  font-size: 9px;
  text-align: center;
  color: rgba(255,255,255,.55);
}
.foot-tip span { opacity: .4; margin: 0 3px; }
.foot-brand { font-size: 8px; letter-spacing: .2em; color: rgba(255,255,255,.22); font-weight: 800; }

/* ============ HUD ============ */
.hud {
  position: absolute;
  inset: 0;
  z-index: 20;
  pointer-events: none;
  padding: calc(12px + var(--safe-top)) calc(clamp(12px, 2vw, 24px) + var(--safe-right)) calc(14px + var(--safe-bottom)) calc(clamp(12px, 2vw, 24px) + var(--safe-left));
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}
.hud::before {
  content: "";
  position: absolute; inset: 0;
  pointer-events: none;
  background:
    linear-gradient(180deg, rgba(3,22,19,.34) 0%, transparent 20%, transparent 72%, rgba(3,22,19,.35) 100%);
}
.hud-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  position: relative;
  z-index: 2;
}
.minimap-shell {
  position: relative;
  width: 118px;
  height: 118px;
  flex: 0 0 auto;
}
#minimap {
  width: 118px;
  height: 118px;
  display: block;
  border-radius: 50%;
  background: rgba(4, 28, 24, .46);
  border: 1px solid rgba(255,255,255,.18);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  box-shadow: 0 8px 26px rgba(0,0,0,.25), inset 0 0 30px rgba(0,0,0,.18);
}
.minimap-ring {
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  border: 1px solid rgba(216,255,93,.16);
  pointer-events: none;
}
.mode-chip {
  position: absolute;
  bottom: -8px;
  left: 50%;
  transform: translateX(-50%);
  white-space: nowrap;
  padding: 3px 9px;
  border-radius: 999px;
  background: rgba(5, 30, 26, .9);
  border: 1px solid rgba(255,255,255,.14);
  font-size: 7px;
  font-weight: 800;
  letter-spacing: .12em;
  color: var(--aqua);
}
.race-stats {
  display: flex;
  align-items: stretch;
  gap: 4px;
  padding: 8px 8px 8px 6px;
  border-radius: 18px;
  background: rgba(4, 30, 26, .55);
  border: 1px solid rgba(255,255,255,.13);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  box-shadow: 0 10px 30px rgba(0,0,0,.2);
}
.stat-block {
  min-width: 57px;
  padding: 2px 12px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border-right: 1px solid rgba(255,255,255,.1);
}
.stat-block > span { font-size: 7px; font-weight: 800; letter-spacing: .18em; color: rgba(255,255,255,.45); }
.stat-block strong {
  display: flex; align-items: baseline; gap: 1px;
  font-family: 'Bungee', sans-serif;
  font-weight: 400;
  font-size: 26px;
  line-height: 1.05;
  color: var(--cream);
}
.stat-block strong b { font-weight: 400; }
.stat-block strong i { font-style: normal; font-size: 11px; color: rgba(255,255,255,.38); font-family: 'Outfit', sans-serif; font-weight: 700; }
.pos-block strong b { color: var(--lime); text-shadow: 0 0 24px rgba(216,255,93,.3); }
.race-clock {
  padding: 3px 12px 2px 10px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: center;
  min-width: 92px;
}
.race-clock span { font-family: 'Bungee', sans-serif; font-size: 15px; letter-spacing: .02em; }
.race-clock em { font-style: normal; font-size: 8px; font-weight: 700; letter-spacing: .08em; color: rgba(255,255,255,.4); margin-top: 2px; }
.pause-btn { pointer-events: auto; }

.status-row {
  position: absolute;
  top: calc(138px + var(--safe-top));
  left: calc(clamp(12px, 2vw, 24px) + var(--safe-left));
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 6px;
  z-index: 3;
}
.status-tag {
  display: flex; align-items: center; gap: 6px;
  padding: 5px 9px;
  border-radius: 8px;
  background: rgba(4, 30, 26, .7);
  border: 1px solid rgba(255,255,255,.14);
  backdrop-filter: blur(10px);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .1em;
}
.status-tag.shield { color: var(--sun); border-color: rgba(255,211,86,.35); box-shadow: 0 0 18px rgba(255,211,86,.12); }
.status-tag.coin { color: #ffe9a1; }
.status-tag b { font-size: 9px; }

.race-message {
  position: absolute;
  left: 50%; top: 27%;
  translate: -50% -50%;
  font-family: 'Bungee', sans-serif;
  font-size: clamp(30px, 6vw, 64px);
  letter-spacing: .01em;
  color: var(--cream);
  text-align: center;
  text-shadow: 0 5px 0 rgba(4,25,21,.3), 0 20px 50px rgba(0,0,0,.35);
  opacity: 0;
  transform: scale(.8);
  transition: opacity .2s, transform .25s cubic-bezier(.2,.9,.3,1.2);
  pointer-events: none;
  z-index: 4;
  white-space: nowrap;
}
.race-message.show { opacity: 1; transform: scale(1); }
.race-message small { display: block; font-family: 'Outfit', sans-serif; font-size: 10px; font-weight: 800; letter-spacing: .3em; color: var(--aqua); margin-top: 6px; }
.race-message.big { color: var(--lime); }

.checkpoint-toast {
  position: absolute;
  top: 17%;
  left: 50%;
  translate: -50% 0;
  padding: 8px 16px;
  border-radius: 999px;
  background: rgba(4, 30, 26, .78);
  border: 1px solid rgba(216,255,93,.35);
  color: var(--lime);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .17em;
  opacity: 0;
  transform: translateY(8px);
  transition: .25s ease;
  z-index: 3;
}
.checkpoint-toast.show { opacity: 1; transform: none; }

.hud-bottom {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: end;
  gap: 12px;
  position: relative;
  z-index: 2;
  width: 100%;
}
.joystick-zone {
  pointer-events: auto;
  justify-self: start;
  width: 132px;
  height: 148px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  gap: 4px;
  touch-action: none;
}
.joystick-base {
  width: 122px; height: 122px;
  border-radius: 50%;
  position: relative;
  background:
    radial-gradient(circle at 50% 50%, rgba(216,255,93,.06) 0 28%, transparent 29%),
    radial-gradient(circle at 50% 55%, rgba(255,255,255,.1), rgba(4, 28, 24, .34) 70%);
  border: 1px solid rgba(255,255,255,.21);
  box-shadow: inset 0 0 32px rgba(0,0,0,.22), 0 10px 34px rgba(0,0,0,.22);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}
.joystick-ticks {
  position: absolute; inset: 9px;
  border-radius: 50%;
  border: 1px dashed rgba(255,255,255,.12);
}
.joystick-ticks::before, .joystick-ticks::after {
  content: ""; position: absolute;
  background: rgba(255,255,255,.16);
}
.joystick-ticks::before { left: 50%; top: -1px; width: 1px; height: 100%; }
.joystick-ticks::after { top: 50%; left: -1px; height: 1px; width: 100%; }
.joystick-knob {
  position: absolute;
  left: 50%; top: 50%;
  width: 56px; height: 56px;
  translate: -50% -50%;
  border-radius: 50%;
  display: grid; place-items: center;
  color: rgba(7,40,36,.75);
  background: linear-gradient(160deg, rgba(248,255,234,.95), rgba(190,232,212,.88));
  border: 1px solid rgba(255,255,255,.75);
  box-shadow: 0 8px 18px rgba(0,0,0,.3), inset 0 -4px 8px rgba(30,90,70,.18);
  transition: transform .06s linear;
  will-change: transform;
}
.control-label { font-size: 7px; font-weight: 800; letter-spacing: .22em; color: rgba(255,255,255,.45); }

.center-cluster {
  justify-self: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding-bottom: 3px;
}
.nitro-wrap { width: 214px; max-width: 52vw; }
.nitro-head {
  display: flex; justify-content: space-between; align-items: center;
  font-size: 8px; font-weight: 800; letter-spacing: .18em;
  color: rgba(255,255,255,.55);
  margin-bottom: 4px;
  padding: 0 2px;
}
.nitro-head b { font-size: 9px; color: var(--aqua); letter-spacing: .05em; }
.nitro-track {
  position: relative;
  height: 9px;
  border-radius: 99px;
  background: rgba(3, 25, 21, .58);
  border: 1px solid rgba(255,255,255,.15);
  box-shadow: inset 0 2px 5px rgba(0,0,0,.35);
  overflow: hidden;
  backdrop-filter: blur(6px);
}
.nitro-track i {
  display: block; height: 100%; width: 0%;
  border-radius: inherit;
  background: linear-gradient(90deg, #31cfc0, #7cf1e1 55%, #d8ff5d);
  box-shadow: 0 0 12px rgba(109,241,220,.55);
  transition: width .1s linear;
}
.nitro-sheen {
  position: absolute; inset: 0;
  background: linear-gradient(180deg, rgba(255,255,255,.35), transparent 45%);
  border-radius: inherit;
  pointer-events: none;
}
.nitro-wrap.full .nitro-track { border-color: rgba(216,255,93,.75); box-shadow: 0 0 22px rgba(216,255,93,.35), inset 0 2px 5px rgba(0,0,0,.35); }
.nitro-wrap.full .nitro-head b { color: var(--lime); }
.nitro-wrap.full .nitro-track i { animation: nitro-pulse .8s ease-in-out infinite; }
@keyframes nitro-pulse { 50% { filter: brightness(1.35); } }

.speedo {
  position: relative;
  width: 116px; height: 116px;
  display: grid; place-items: center;
  border-radius: 50%;
  background: radial-gradient(circle at 50% 55%, rgba(9,45,39,.72), rgba(3,23,20,.5));
  border: 1px solid rgba(255,255,255,.16);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  box-shadow: 0 12px 32px rgba(0,0,0,.24), inset 0 0 26px rgba(0,0,0,.2);
}
.speedo-arc { position: absolute; inset: 5px; width: calc(100% - 10px); height: calc(100% - 10px); transform: rotate(0deg); }
.speedo-arc circle { fill: none; stroke-width: 3.4; }
.arc-bg { stroke: rgba(255,255,255,.12); stroke-dasharray: 240 321; }
.arc-fill {
  stroke: var(--lime);
  stroke-linecap: round;
  stroke-dasharray: 0 321;
  filter: drop-shadow(0 0 5px rgba(216,255,93,.55));
  transition: stroke-dasharray .08s linear;
}
.speedo-read { display: flex; flex-direction: column; align-items: center; line-height: 1; margin-top: -5px; }
.speedo-read b { font-family: 'Bungee', sans-serif; font-weight: 400; font-size: 31px; letter-spacing: -.03em; color: var(--cream); }
.speedo-read span { font-size: 6.5px; font-weight: 800; letter-spacing: .2em; color: rgba(255,255,255,.42); margin-top: 4px; }
.drift-tag {
  position: absolute;
  white-space: nowrap;
  bottom: -18px;
  padding: 3px 8px;
  border-radius: 6px;
  font-size: 7px;
  font-weight: 800;
  letter-spacing: .1em;
  color: #ffe4a8;
  background: rgba(255,122,72,.16);
  border: 1px solid rgba(255,150,80,.35);
  text-shadow: 0 0 10px rgba(255,150,80,.5);
}
.drift-tag b { color: var(--sun); }

.action-cluster {
  justify-self: end;
  display: flex;
  align-items: flex-end;
  gap: 9px;
  pointer-events: auto;
}
.round-btn {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,.2);
  background: rgba(6, 34, 30, .52);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  box-shadow: 0 12px 30px rgba(0,0,0,.25), inset 0 1px 0 rgba(255,255,255,.15);
  touch-action: none;
  transition: transform .08s ease, background .08s ease;
}
.round-btn span { font-size: 7px; font-weight: 800; letter-spacing: .13em; }
.round-btn:active, .round-btn.held { transform: scale(.94); }
.round-btn.brake {
  width: 66px; height: 66px;
  color: rgba(255,255,255,.72);
  font-size: 7px;
}
.round-btn.brake:active { background: rgba(255,122,72,.24); }
.round-btn.nitro {
  width: 94px; height: 94px;
  color: #eaffc3;
  background: radial-gradient(circle at 50% 40%, rgba(80,220,200,.3), rgba(6,38,34,.65) 68%);
  border-color: rgba(122,243,213,.48);
  box-shadow: 0 12px 34px rgba(0,0,0,.28), 0 0 24px rgba(66,220,195,.12), inset 0 1px 0 rgba(255,255,255,.2);
}
.round-btn.nitro .nitro-flame { color: var(--aqua); filter: drop-shadow(0 0 8px rgba(122,243,213,.55)); }
.round-btn.nitro:active, .round-btn.nitro.held {
  background: radial-gradient(circle at 50% 40%, rgba(120,255,225,.45), rgba(6,63,55,.75) 68%);
  box-shadow: 0 0 38px rgba(77,240,210,.4);
}
.round-btn.nitro.ready {
  border-color: var(--lime);
  color: var(--lime);
  animation: ready-pulse 1s infinite;
}
.round-btn.nitro.ready .nitro-flame { color: var(--lime); }
@keyframes ready-pulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(216,255,93,.25), 0 12px 34px rgba(0,0,0,.28); }
  50% { box-shadow: 0 0 0 9px rgba(216,255,93,.06), 0 0 34px rgba(216,255,93,.25); }
}
.full-ring {
  position: absolute;
  inset: -5px;
  border-radius: 50%;
  border: 1px solid transparent;
  pointer-events: none;
}
.round-btn.nitro.ready .full-ring { border-color: rgba(216,255,93,.24); }

.swipe-hint {
  position: absolute;
  bottom: calc(158px + var(--safe-bottom));
  left: 50%;
  translate: -50%;
  display: flex; align-items: center; gap: 6px;
  padding: 5px 11px;
  border-radius: 999px;
  background: rgba(4,30,26,.5);
  border: 1px solid rgba(255,255,255,.1);
  color: rgba(255,255,255,.44);
  font-size: 7px;
  font-weight: 800;
  letter-spacing: .14em;
  transition: opacity .5s;
  backdrop-filter: blur(8px);
  pointer-events: none;
}
.swipe-hint.hide { opacity: 0; }

/* Tilt mode */
.hud.tilt-mode .joystick-zone { opacity: .22; pointer-events: none; }
.hud.tilt-mode .joystick-knob { translate: -50% -50%; }
.hud.tilt-mode .joystick-zone::after {
  content: "TILT TO STEER";
  position: absolute;
  bottom: 50%; left: 50%;
  translate: -50% 50%;
  white-space: nowrap;
  font-size: 7px;
  font-weight: 800;
  letter-spacing: .14em;
  color: var(--aqua);
}
.tilt-mode .control-label { display: none; }

/* ============ COUNTDOWN ============ */
.countdown {
  position: absolute;
  inset: 0;
  z-index: 25;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  pointer-events: none;
  background: radial-gradient(circle at 50% 52%, rgba(3,24,20,.10), rgba(3,24,20,.42) 80%);
}
.countdown-kicker {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .42em;
  color: var(--aqua);
  margin-bottom: 4px;
  text-shadow: 0 2px 10px rgba(0,0,0,.5);
}
.countdown-value {
  font-family: 'Bungee', sans-serif;
  font-size: clamp(100px, 19vw, 190px);
  line-height: .9;
  color: var(--cream);
  text-shadow: 0 8px 0 rgba(5,30,25,.25), 0 30px 70px rgba(0,0,0,.35), 0 0 80px rgba(216,255,93,.15);
  animation: count-pop .35s cubic-bezier(.2,1.3,.4,1);
}
.countdown-value.go { color: var(--lime); font-size: clamp(76px, 15vw, 150px); }
@keyframes count-pop { from { transform: scale(1.35); opacity: .2; } to { transform: scale(1); opacity: 1; } }
.countdown-sub {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .32em;
  color: rgba(255,255,255,.5);
  margin-top: 9px;
  text-shadow: 0 2px 8px rgba(0,0,0,.4);
}
.start-lights { display: flex; gap: 8px; margin-top: 24px; }
.start-lights i {
  width: 8px; height: 8px;
  border-radius: 50%;
  background: rgba(255,255,255,.16);
  border: 1px solid rgba(255,255,255,.25);
}
.start-lights i.on { background: var(--lime); box-shadow: 0 0 14px var(--lime); border-color: var(--lime); }

/* ============ MODALS ============ */
.modal-layer {
  position: absolute;
  inset: 0;
  z-index: 40;
  display: grid;
  place-items: center;
  padding: calc(20px + var(--safe-top)) calc(18px + var(--safe-right)) calc(20px + var(--safe-bottom)) calc(18px + var(--safe-left));
  background: radial-gradient(circle at 50% 45%, rgba(5,35,30,.35), rgba(2,16,14,.76));
  backdrop-filter: blur(10px) saturate(.9);
  -webkit-backdrop-filter: blur(10px) saturate(.9);
  animation: fade-in .25s ease both;
}
@keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
.modal-card {
  position: relative;
  width: min(460px, 94vw);
  max-height: min(86vh, 880px);
  overflow: auto;
  padding: 28px;
  border-radius: 26px;
  border: 1px solid rgba(255,255,255,.17);
  background:
    linear-gradient(155deg, rgba(19, 68, 59, .92), rgba(5, 31, 27, .96) 55%),
    #062b26;
  box-shadow: var(--shadow), inset 0 1px 0 rgba(255,255,255,.12);
  animation: card-in .35s cubic-bezier(.2,.85,.3,1) both;
  scrollbar-width: thin;
  scrollbar-color: rgba(255,255,255,.2) transparent;
}
@keyframes card-in { from { transform: translateY(18px) scale(.98); opacity: 0; } to { transform: none; opacity: 1; } }
.modal-card::-webkit-scrollbar { width: 5px; }
.modal-card::-webkit-scrollbar-thumb { background: rgba(255,255,255,.14); border-radius: 99px; }
.panel-kicker { font-size: 8px; font-weight: 800; letter-spacing: .25em; color: var(--aqua); margin-bottom: 6px; }
.modal-card h2 {
  margin: 0 0 6px;
  font-family: 'Bungee', sans-serif;
  font-weight: 400;
  font-size: clamp(30px, 6vw, 44px);
  line-height: 1;
  letter-spacing: -.02em;
}
.modal-card p { margin: 0; }
.pause-sub { font-size: 13px; color: rgba(255,255,255,.5); margin-bottom: 22px !important; }
.stack { display: flex; flex-direction: column; gap: 8px; }
.pause-card .btn { width: 100%; }

/* results */
.results-layer { z-index: 45; background: radial-gradient(circle at 50% 40%, rgba(8,50,43,.2), rgba(2,14,12,.78)); }
.results-card {
  position: relative;
  width: min(480px, 94vw);
  max-height: 94vh;
  overflow: auto;
  padding: 26px 28px 24px;
  border-radius: 28px;
  border: 1px solid rgba(216,255,93,.28);
  background: linear-gradient(160deg, rgba(23, 75, 64, .93), rgba(5, 30, 27, .97) 60%);
  box-shadow: 0 40px 110px rgba(0,10,7,.6), inset 0 1px 0 rgba(255,255,255,.14);
  text-align: center;
  animation: result-in .55s cubic-bezier(.18,.9,.25,1) both;
  scrollbar-width: thin;
}
@keyframes result-in { from { transform: translateY(30px) scale(.96); opacity: 0; } to { transform: none; opacity: 1; } }
.results-burst {
  position: absolute;
  inset: -60% -30% auto;
  height: 130%;
  background:
    conic-gradient(from 0deg at 50% 50%, transparent 0 9deg, rgba(216,255,93,.10) 9deg 11deg, transparent 11deg 20deg);
  pointer-events: none;
  animation: burst-spin 18s linear infinite;
  opacity: .8;
}
@keyframes burst-spin { to { transform: rotate(360deg); } }
.results-card > * { position: relative; }
.result-place { display: flex; align-items: baseline; justify-content: center; gap: 8px; margin: 2px 0 4px; }
.result-place span {
  font-family: 'Bungee', sans-serif;
  font-size: clamp(72px, 15vw, 108px);
  line-height: 1;
  color: var(--lime);
  text-shadow: 0 0 60px rgba(216,255,93,.26), 0 6px 0 rgba(0,0,0,.15);
}
.result-place small { font-size: 9px; font-weight: 800; letter-spacing: .25em; color: rgba(255,255,255,.42); }
.results-card h2 { font-size: clamp(24px, 5.4vw, 34px); margin-bottom: 4px; }
.result-sub { font-size: 12px; color: rgba(255,255,255,.52); }
.result-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  margin: 18px 0 16px;
  border-radius: 14px;
  overflow: hidden;
  border: 1px solid rgba(255,255,255,.1);
  background: rgba(255,255,255,.1);
}
.result-stats div { background: rgba(4,31,27,.82); padding: 11px 8px; display: flex; flex-direction: column; gap: 3px; }
.result-stats span { font-size: 7px; font-weight: 800; letter-spacing: .15em; color: rgba(255,255,255,.4); }
.result-stats b { font-family: 'Bungee', sans-serif; font-weight: 400; font-size: 17px; color: var(--cream); }
.reward-box {
  border-radius: 14px;
  background: rgba(2,25,21,.45);
  border: 1px solid rgba(255,255,255,.1);
  padding: 11px 13px;
  margin-bottom: 14px;
}
.reward-line { display: flex; justify-content: space-between; align-items: center; font-size: 11px; color: rgba(255,255,255,.55); padding: 4px 0; }
.reward-line b { color: rgba(255,255,255,.9); font-weight: 700; }
.reward-total { display: flex; justify-content: space-between; align-items: center; margin-top: 6px; padding-top: 8px; border-top: 1px solid rgba(255,255,255,.1); }
.reward-total > span { font-size: 8px; font-weight: 800; letter-spacing: .18em; color: rgba(255,255,255,.42); }
.reward-total b { display: flex; align-items: center; gap: 6px; font-family: 'Bungee', sans-serif; font-weight: 400; font-size: 22px; color: var(--lime); }
.result-new { display: inline-block; padding: 5px 12px; border-radius: 999px; background: rgba(255,211,86,.13); border: 1px solid rgba(255,211,86,.4); color: var(--sun); font-size: 8px; font-weight: 800; letter-spacing: .16em; margin-bottom: 12px; }
.results-actions { display: grid; grid-template-columns: 1.4fr 1fr; gap: 8px; }
.results-actions .btn { width: 100%; }

/* ============ PANELS ============ */
.panel-layer { align-items: center; }
.panel-card { width: min(880px, 94vw); padding: 0; max-height: min(90vh, 900px); }
.panel-head {
  position: sticky; top: 0; z-index: 3;
  display: flex; align-items: center; justify-content: space-between; gap: 14px;
  padding: 22px 26px 16px;
  background: linear-gradient(180deg, rgba(10,49,43,.98), rgba(10,49,43,.92) 80%, transparent);
  border-bottom: 1px solid rgba(255,255,255,.06);
}
.panel-head-left { display: flex; flex-direction: column; }
.panel-head h2 { margin: 0; font-size: clamp(26px, 4vw, 38px); }
.panel-head-right { display: flex; align-items: center; gap: 9px; }
.panel-close { width: 38px; height: 38px; border-radius: 50%; display: grid; place-items: center; background: rgba(255,255,255,.07); border: 1px solid rgba(255,255,255,.12); color: rgba(255,255,255,.7); font-size: 20px; transition: .2s; }
.panel-close:hover { background: rgba(255,255,255,.14); color: #fff; }
.panel-body { padding: 20px 26px 26px; }
.panel-copy { font-size: 12px; line-height: 1.55; color: rgba(255,255,255,.55); max-width: 560px; margin-bottom: 18px !important; }
.section-label { font-size: 8px; font-weight: 800; letter-spacing: .2em; color: rgba(255,255,255,.4); margin: 0 0 9px; text-transform: uppercase; }

/* career */
.career-list { display: flex; flex-direction: column; gap: 8px; }
.career-row {
  display: grid;
  grid-template-columns: 86px 1fr auto;
  gap: 15px;
  align-items: center;
  padding: 10px;
  border-radius: 16px;
  border: 1px solid rgba(255,255,255,.1);
  background: rgba(255,255,255,.035);
  transition: .18s;
}
.career-row:hover { background: rgba(255,255,255,.065); }
.career-row.locked { opacity: .48; }
.career-thumb {
  position: relative;
  height: 70px;
  border-radius: 11px;
  overflow: hidden;
  background: var(--thumb, linear-gradient(150deg, #2d8f74, #0c493f));
}
.career-thumb::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 60% 28% at 50% 78%, rgba(190,255,230,.55), transparent 70%),
    linear-gradient(180deg, transparent 40%, rgba(4,30,25,.5));
}
.career-thumb::after {
  content: "";
  position: absolute;
  left: -20%; bottom: 16px; width: 140%; height: 18px;
  border-radius: 50%;
  border-top: 2px solid rgba(255,255,255,.4);
  transform: rotate(-7deg);
}
.career-thumb b {
  position: absolute; top: 7px; left: 8px;
  font-family: 'Bungee', sans-serif; font-weight: 400; font-size: 18px; color: rgba(255,255,255,.9);
  text-shadow: 0 2px 8px rgba(0,0,0,.35);
}
.career-info { min-width: 0; }
.career-info h3 { margin: 0 0 3px; font-size: 14px; font-weight: 800; letter-spacing: .01em; }
.career-info p { font-size: 10px; color: rgba(255,255,255,.45); margin: 0 0 6px; }
.career-tags { display: flex; gap: 4px; flex-wrap: wrap; }
.career-tags span { font-size: 7px; font-weight: 800; letter-spacing: .08em; padding: 3px 6px; border-radius: 5px; background: rgba(255,255,255,.07); color: rgba(255,255,255,.6); }
.career-tags span.gold { background: rgba(255,211,86,.12); color: var(--sun); }
.career-action { display: flex; flex-direction: column; align-items: flex-end; gap: 5px; }
.career-action .btn { min-height: 38px; padding: 0 16px; font-size: 10px; border-radius: 10px; }
.career-action small { font-size: 8px; color: rgba(255,255,255,.35); letter-spacing: .04em; }
.career-lock { font-size: 9px; font-weight: 800; letter-spacing: .08em; color: rgba(255,255,255,.45); display: flex; align-items: center; gap: 5px; }

/* garage */
.garage-layout { display: grid; grid-template-columns: 285px 1fr; gap: 18px; }
.ski-list { display: flex; flex-direction: column; gap: 6px; }
.ski-item {
  display: flex; align-items: center; gap: 10px;
  padding: 8px 10px;
  border-radius: 12px;
  border: 1px solid rgba(255,255,255,.085);
  background: rgba(255,255,255,.03);
  text-align: left;
  transition: .16s;
}
.ski-item:hover { background: rgba(255,255,255,.065); }
.ski-item.active { border-color: rgba(216,255,93,.5); background: rgba(216,255,93,.07); }
.ski-swatch { width: 36px; height: 36px; border-radius: 10px; flex: 0 0 auto; position: relative; overflow: hidden; background: linear-gradient(145deg, var(--c1), var(--c2)); }
.ski-swatch::after { content: ""; position: absolute; width: 26px; height: 7px; border-radius: 50%; background: rgba(255,255,255,.55); left: 5px; bottom: 6px; transform: rotate(-9deg); }
.ski-item-text { display: flex; flex-direction: column; min-width: 0; }
.ski-item-text b { font-size: 11px; font-weight: 800; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ski-item-text span { font-size: 8px; color: rgba(255,255,255,.4); margin-top: 2px; }
.ski-item .equipped { margin-left: auto; font-size: 7px; font-weight: 800; color: var(--lime); letter-spacing: .08em; }
.ski-item .lock-price { margin-left: auto; font-size: 8px; font-weight: 800; color: var(--sun); white-space: nowrap; }
.garage-detail { min-width: 0; }
.ski-preview {
  position: relative;
  height: 150px;
  border-radius: 18px;
  overflow: hidden;
  background:
    radial-gradient(ellipse at 50% 70%, rgba(216,255,93,.13), transparent 52%),
    linear-gradient(150deg, var(--c1), var(--c2) 60%, #062d28);
  border: 1px solid rgba(255,255,255,.12);
  margin-bottom: 13px;
}
.ski-preview::before {
  content: "";
  position: absolute; inset: 0;
  background: repeating-linear-gradient(115deg, transparent 0 22px, rgba(255,255,255,.03) 22px 23px);
}
.ski-svg { position: absolute; inset: 0; width: 100%; height: 100%; filter: drop-shadow(0 15px 20px rgba(0,0,0,.35)); }
.ski-preview .preview-name { position: absolute; left: 15px; bottom: 10px; font-family: 'Bungee', sans-serif; font-weight: 400; font-size: 17px; color: #fff; text-shadow: 0 2px 12px rgba(0,0,0,.5); }
.preview-badge { position: absolute; top: 10px; right: 10px; padding: 4px 8px; border-radius: 6px; background: rgba(3,30,26,.55); border: 1px solid rgba(255,255,255,.18); font-size: 7px; font-weight: 800; letter-spacing: .1em; color: var(--aqua); backdrop-filter: blur(5px); }
.stat-grid { display: flex; flex-direction: column; gap: 7px; margin-bottom: 15px; }
.stat-line { display: grid; grid-template-columns: 58px 1fr 28px; align-items: center; gap: 9px; }
.stat-line span { font-size: 9px; font-weight: 800; letter-spacing: .09em; color: rgba(255,255,255,.55); }
.stat-line b { font-size: 9px; color: rgba(255,255,255,.75); text-align: right; }
.stat-track { height: 6px; border-radius: 99px; background: rgba(255,255,255,.1); overflow: hidden; }
.stat-track i { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, var(--aqua-deep), var(--lime)); box-shadow: 0 0 10px rgba(165,239,57,.35); }
.upgrade-row { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 7px 0; border-top: 1px solid rgba(255,255,255,.07); }
.upgrade-info { display: flex; flex-direction: column; }
.upgrade-info b { font-size: 10px; font-weight: 800; }
.upgrade-info small { font-size: 8px; color: rgba(255,255,255,.38); margin-top: 2px; }
.upgrade-pips { display: flex; gap: 3px; margin-top: 4px; }
.upgrade-pips i { width: 16px; height: 4px; border-radius: 2px; background: rgba(255,255,255,.12); }
.upgrade-pips i.on { background: var(--lime); box-shadow: 0 0 5px rgba(216,255,93,.4); }
.upgrade-btn { min-height: 32px; padding: 0 12px; border-radius: 9px; font-size: 9px; font-weight: 800; display: flex; align-items: center; gap: 5px; background: rgba(216,255,93,.1); border: 1px solid rgba(216,255,93,.25); color: var(--lime); white-space: nowrap; }
.upgrade-btn:hover { background: rgba(216,255,93,.18); }
.upgrade-btn:disabled { opacity: .4; }
.upgrade-btn.maxed { color: var(--sun); border-color: rgba(255,211,86,.25); background: rgba(255,211,86,.08); }
.buy-row { display: flex; gap: 8px; margin-top: 12px; }
.buy-row .btn { flex: 1; min-height: 44px; font-size: 11px; }
.garage-note { font-size: 9px; color: rgba(255,255,255,.35); margin-top: 10px !important; line-height: 1.5; }

/* daily */
.daily-rewards { display: grid; grid-template-columns: repeat(7, 1fr); gap: 6px; margin-bottom: 20px; }
.day-card {
  position: relative;
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 5px;
  min-height: 75px;
  padding: 7px 3px;
  border-radius: 11px;
  border: 1px solid rgba(255,255,255,.09);
  background: rgba(255,255,255,.035);
}
.day-card span { font-size: 7px; font-weight: 800; letter-spacing: .1em; color: rgba(255,255,255,.4); }
.day-card b { font-size: 11px; font-weight: 800; color: rgba(255,255,255,.85); }
.day-card .coin-glyph { width: 22px; height: 22px; }
.day-card.today { border-color: rgba(216,255,93,.5); background: rgba(216,255,93,.08); box-shadow: 0 0 18px rgba(216,255,93,.08); }
.day-card.claimed { opacity: .45; }
.day-card.claimed::after { content: "✓"; position: absolute; top: 3px; right: 6px; font-size: 9px; color: var(--lime); font-weight: 800; }
.daily-cta { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 13px; border-radius: 13px; background: rgba(255,255,255,.04); border: 1px solid rgba(255,255,255,.09); margin-bottom: 20px; }
.daily-cta-info b { display: block; font-size: 12px; font-weight: 800; margin-bottom: 2px; }
.daily-cta-info span { font-size: 9px; color: rgba(255,255,255,.45); }
.mission-list { display: flex; flex-direction: column; gap: 7px; }
.mission-item { display: grid; grid-template-columns: 34px 1fr auto; gap: 10px; align-items: center; padding: 9px 11px; border-radius: 12px; border: 1px solid rgba(255,255,255,.08); background: rgba(255,255,255,.03); }
.mission-icon { width: 34px; height: 34px; border-radius: 9px; display: grid; place-items: center; background: rgba(122,243,213,.09); color: var(--aqua); font-size: 14px; }
.mission-text b { display: block; font-size: 10px; font-weight: 800; margin-bottom: 4px; }
.mission-progress { height: 4px; border-radius: 99px; background: rgba(255,255,255,.1); overflow: hidden; margin-bottom: 3px; }
.mission-progress i { display: block; height: 100%; border-radius: inherit; background: var(--aqua); }
.mission-text small { font-size: 8px; color: rgba(255,255,255,.38); }
.mission-reward { display: flex; flex-direction: column; align-items: flex-end; gap: 4px; }
.mission-reward span { font-size: 9px; font-weight: 800; color: var(--sun); }
.mission-reward button { font-size: 8px; font-weight: 800; padding: 4px 8px; border-radius: 6px; border: 1px solid rgba(216,255,93,.3); color: var(--lime); background: rgba(216,255,93,.08); }
.mission-reward button:disabled { opacity: .4; border-color: rgba(255,255,255,.1); color: rgba(255,255,255,.3); background: transparent; }

/* settings */
.settings-grid { display: flex; flex-direction: column; gap: 2px; }
.setting-row { display: flex; align-items: center; justify-content: space-between; gap: 15px; padding: 13px 0; border-bottom: 1px solid rgba(255,255,255,.07); }
.setting-label b { display: block; font-size: 12px; font-weight: 800; margin-bottom: 2px; }
.setting-label span { font-size: 9px; color: rgba(255,255,255,.4); }
.segmented { display: flex; gap: 3px; padding: 3px; border-radius: 9px; background: rgba(0,0,0,.22); border: 1px solid rgba(255,255,255,.08); }
.segmented button { padding: 6px 11px; border-radius: 6px; font-size: 8px; font-weight: 800; letter-spacing: .06em; color: rgba(255,255,255,.45); }
.segmented button.active { background: rgba(216,255,93,.15); color: var(--lime); box-shadow: inset 0 0 0 1px rgba(216,255,93,.2); }
.toggle { width: 42px; height: 24px; border-radius: 99px; background: rgba(255,255,255,.13); position: relative; transition: .2s; flex: 0 0 auto; }
.toggle::after { content: ""; position: absolute; left: 3px; top: 3px; width: 18px; height: 18px; border-radius: 50%; background: rgba(255,255,255,.8); transition: .2s ease; }
.toggle.on { background: rgba(216,255,93,.3); }
.toggle.on::after { transform: translateX(18px); background: var(--lime); }
.settings-note { font-size: 9px; line-height: 1.5; color: rgba(255,255,255,.35); margin: 14px 0 !important; }
.danger-link { color: rgba(255,120,90,.7); font-size: 9px; font-weight: 800; letter-spacing: .06em; margin-top: 16px; text-decoration: underline; text-underline-offset: 3px; }

/* toast */
.toast {
  position: absolute;
  z-index: 60;
  left: 50%;
  bottom: calc(190px + var(--safe-bottom));
  translate: -50%;
  padding: 12px 18px;
  border-radius: 12px;
  background: rgba(3, 28, 24, .92);
  border: 1px solid rgba(216,255,93,.35);
  box-shadow: 0 16px 40px rgba(0,0,0,.4);
  color: var(--cream);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .02em;
  text-align: center;
  animation: toast-in .3s cubic-bezier(.2,.9,.3,1) both;
  pointer-events: none;
  max-width: 84vw;
}
@keyframes toast-in { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }

/* boost overlays */
.boost-overlay {
  position: absolute; inset: 0; z-index: 4;
  opacity: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 50% 52%, transparent 32%, rgba(68,221,204,.16) 76%, rgba(15,95,88,.3) 100%),
    repeating-conic-gradient(from 0deg at 50% 50%, transparent 0deg 5deg, rgba(196,255,244,.12) 5deg 5.6deg, transparent 5.6deg 11deg);
  mask-image: radial-gradient(ellipse at 50% 50%, transparent 30%, black 100%);
  transition: opacity .25s;
  mix-blend-mode: screen;
}
.boost-overlay.active { opacity: .55; animation: boost-throb .6s linear infinite; }
@keyframes boost-throb { 50% { opacity: .33; } }
.slowmo-overlay {
  position: absolute; inset: 0; z-index: 4; pointer-events: none; opacity: 0;
  background: radial-gradient(ellipse at 50% 50%, transparent 35%, rgba(255,244,201,.14) 100%);
  transition: opacity .2s;
}
.slowmo-overlay.active { opacity: 1; }

/* ============ RESPONSIVE ============ */
@media (max-width: 900px) {
  .hero { width: min(440px, 54vw); }
  .logo { font-size: clamp(54px, 9vw, 88px); }
  .race-facts { gap: 18px; }
  .foot-tip { display: none; }
  .menu-foot { justify-content: flex-end; }
}

@media (max-aspect-ratio: 5/4), (max-width: 700px) {
  .screen {
    padding: calc(14px + var(--safe-top)) calc(16px + var(--safe-right)) calc(12px + var(--safe-bottom)) calc(16px + var(--safe-left));
  }
  .menu::before {
    background:
      linear-gradient(0deg, rgba(4, 27, 23, .93) 0%, rgba(4, 27, 23, .78) 32%, rgba(4, 27, 23, .12) 68%, rgba(4,27,23,.3) 100%);
  }
  .mini-brand-text span { display: none; }
  .menu-stage { align-items: flex-end; }
  .hero {
    width: 100%;
    padding-bottom: 4px;
  }
  .eyebrow { font-size: 8px; letter-spacing: .2em; }
  .logo {
    font-size: clamp(54px, 15.5vw, 82px);
    margin: 6px 0 8px;
    flex-direction: row;
    align-items: baseline;
    gap: 10px;
    line-height: .9;
  }
  .logo strong { font-size: 1em; }
  .tagline { font-size: 12px; margin-bottom: 14px; }
  .race-facts { display: none; }
  #quickRaceBtn { height: 58px; font-size: 21px; }
  .cta-kicker { margin-bottom: 6px; }
  .mode-strip { grid-template-columns: repeat(2, 1fr); gap: 5px; margin-top: 9px; }
  .mode-card { min-height: 51px; padding: 7px 9px; border-radius: 11px; }
  .mode-icon { width: 29px; height: 29px; border-radius: 8px; }
  .mode-icon svg { width: 17px; height: 17px; }
  .mode-text b { font-size: 9.5px; }
  .mode-text small { font-size: 8px; }
  .mode-badge { font-size: 7px; padding: 2px 5px; }
  .menu-foot { padding-top: 8px; margin-top: 2px; }
  .foot-brand { font-size: 7px; }
  .mini-brand-text b { font-size: 13px; }
  .pill-btn, .icon-btn { min-height: 38px; height: 38px; }
  .pill-btn { padding: 0 12px; }

  .hud { padding: calc(10px + var(--safe-top)) calc(10px + var(--safe-right)) calc(10px + var(--safe-bottom)) calc(10px + var(--safe-left)); }
  .minimap-shell { width: 88px; height: 88px; }
  #minimap { width: 88px; height: 88px; }
  .race-stats { padding: 5px 5px 5px 3px; gap: 0; border-radius: 14px; }
  .stat-block { min-width: 43px; padding: 1px 8px; }
  .stat-block strong { font-size: 21px; }
  .stat-block > span { font-size: 6px; }
  .race-clock { min-width: 74px; padding: 2px 7px 1px 5px; }
  .race-clock span { font-size: 12px; }
  .race-clock em { font-size: 6.5px; }
  .pause-btn { width: 36px; height: 36px; }
  .status-row { top: calc(102px + var(--safe-top)); }
  .hud-bottom { grid-template-columns: 104px 1fr 88px; gap: 4px; }
  .joystick-zone { width: 104px; height: 120px; }
  .joystick-base { width: 96px; height: 96px; }
  .joystick-knob { width: 46px; height: 46px; }
  .joystick-knob svg { width: 18px; height: 18px; }
  .control-label { font-size: 6px; }
  .nitro-wrap { width: 152px; }
  .nitro-head { font-size: 7px; }
  .speedo { width: 94px; height: 94px; }
  .speedo-read b { font-size: 25px; }
  .speedo-arc { inset: 4px; width: calc(100% - 8px); height: calc(100% - 8px); }
  .speedo-read span { font-size: 5.5px; }
  .center-cluster { gap: 5px; }
  .action-cluster { gap: 5px; }
  .round-btn.brake { width: 52px; height: 52px; }
  .round-btn.brake svg { width: 17px; height: 17px; }
  .round-btn.nitro { width: 74px; height: 74px; }
  .round-btn.nitro svg { width: 22px; height: 22px; }
  .round-btn span { font-size: 6px; }
  .swipe-hint { bottom: calc(126px + var(--safe-bottom)); font-size: 6px; padding: 4px 8px; }
  .race-message { top: 24%; font-size: clamp(28px, 9vw, 48px); }
  .checkpoint-toast { top: 14%; font-size: 7px; }
  .drift-tag { bottom: -16px; font-size: 6px; }
  .tilt-mode .joystick-zone::after { font-size: 6px; }

  .modal-card { padding: 22px 18px; border-radius: 22px; }
  .results-card { padding: 22px 18px 18px; border-radius: 23px; }
  .result-stats b { font-size: 14px; }
  .career-row { grid-template-columns: 70px 1fr; gap: 10px; padding: 8px; }
  .career-thumb { height: 60px; grid-row: span 2; }
  .career-action { grid-column: 2; flex-direction: row; justify-content: space-between; align-items: center; }
  .career-action .btn { min-height: 34px; }
  .panel-head { padding: 18px 18px 13px; }
  .panel-body { padding: 16px 18px 20px; }
  .garage-layout { grid-template-columns: 1fr; }
  .ski-list { flex-direction: row; overflow-x: auto; gap: 5px; padding-bottom: 4px; }
  .ski-item { min-width: 152px; }
  .ski-preview { height: 120px; }
  .daily-rewards { grid-template-columns: repeat(4, 1fr); }
  .day-card:nth-child(n+5) { min-height: 62px; }
