}

@media (max-height: 560px) and (orientation: landscape) {
  .screen { padding-top: calc(10px + var(--safe-top)); padding-bottom: calc(8px + var(--safe-bottom)); }
  .menu::before { background: linear-gradient(90deg, rgba(4,27,23,.84) 0%, rgba(4,27,23,.54) 38%, transparent 68%); }
  .menu-stage { align-items: center; }
  .hero { width: min(420px, 48vw); }
  .eyebrow { display: none; }
  .logo { font-size: clamp(44px, 7vw, 64px); margin: 0 0 6px; }
  .tagline { display: none; }
  .race-facts { display: none; }
  .cta-kicker { margin-bottom: 4px; }
  #quickRaceBtn { height: 52px; font-size: 19px; }
  .mode-strip { grid-template-columns: repeat(4, 1fr); margin-top: 7px; }
  .mode-card { min-height: 46px; padding: 6px; gap: 6px; }
