const todayKey = () => {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
};

const yesterdayKey = () => {
  const d = new Date();
  d.setDate(d.getDate() - 1);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
};

export class Progress {
  constructor() {
    this.save = this.load();
    this.ensureMissions();
  }

  load() {
    const base = defaultSave();
    try {
      const raw = localStorage.getItem('riverRush.save.v1');
      if (!raw) return base;
      const parsed = JSON.parse(raw);
      const merged = {
        ...base,
        ...parsed,
        settings: { ...base.settings, ...(parsed.settings || {}) },
        daily: { ...base.daily, ...(parsed.daily || {}) },
        stats: { ...base.stats, ...(parsed.stats || {}) },
        upgrades: { ...base.upgrades, ...(parsed.upgrades || {}) },
      };
      if (!Array.isArray(merged.owned) || !merged.owned.length) merged.owned = ['reef'];
      if (!merged.owned.includes('reef')) merged.owned.unshift('reef');
      if (!merged.owned.includes(merged.selected)) merged.selected = merged.owned[0];
      return merged;
    } catch {
      return base;
    }
  }

  persist() {
    try {
      localStorage.setItem('riverRush.save.v1', JSON.stringify(this.save));
    } catch {
      /* private mode */
    }
  }

  get settings() { return this.save.settings; }
  get coins() { return this.save.coins; }

  updateSettings(patch) {
    this.save.settings = { ...this.save.settings, ...patch };
    this.persist();
  }

  addCoins(amount) {
    this.save.coins = Math.max(0, Math.round(this.save.coins + amount));
    this.persist();
  }

  jetSki(id) {
    return JETSKIS.find((j) => j.id === id) || JETSKIS[0];
  }

  selectedJetSki() {
    return this.jetSki(this.save.selected);
  }

  isOwned(id) { return this.save.owned.includes(id); }

  buyJetSki(id) {
    const ski = this.jetSki(id);
    if (!ski || this.isOwned(id) || this.save.coins < ski.price) return false;
    this.save.coins -= ski.price;
    this.save.owned.push(id);
    this.save.selected = id;
    if (!this.save.upgrades[id]) this.save.upgrades[id] = { speed: 0, handling: 0, boost: 0 };
    this.persist();
    return true;
  }

  selectJetSki(id) {
    if (!this.isOwned(id)) return false;
    this.save.selected = id;
    this.persist();
    return true;
  }

  upgradesFor(id = this.save.selected) {
    return this.save.upgrades[id] || { speed: 0, handling: 0, boost: 0 };
  }

  upgradeCost(id, key) {
    const level = this.upgradesFor(id)[key] || 0;
    if (level >= 5) return null;
    return UPGRADE_COSTS[level];
  }

  upgrade(id, key) {
    if (!this.isOwned(id)) return false;
    const ups = this.upgradesFor(id);
    const level = ups[key] || 0;
    if (level >= 5) return false;
    const cost = UPGRADE_COSTS[level];
    if (this.save.coins < cost) return false;
    this.save.coins -= cost;
    this.save.upgrades[id] = { ...ups, [key]: level + 1 };
    this.persist();
    return true;
  }

  /** Effective stat values (0–100) including owned upgrades. */
  effectiveStats(id = this.save.selected) {
    const ski = this.jetSki(id);
    const ups = this.upgradesFor(id);
    return {
      speed: clamp(ski.speed + ups.speed * 2.3, 0, 100),
      handling: clamp(ski.handling + ups.handling * 2.3, 0, 100),
      boost: clamp(ski.boost + ups.boost * 2.3, 0, 100),
    };
  }

  /** Multipliers used by the physics. */
  performance(id = this.save.selected) {
    const stats = this.effectiveStats(id);
    return {
      speed: 0.94 + (stats.speed - 60) * 0.0042,
      handling: 0.90 + (stats.handling - 60) * 0.0052,
      boost: 0.90 + (stats.boost - 60) * 0.0050,
    };
  }

  // ---------- Career ----------
  isCareerUnlocked(event) {
    if (!event.unlockAfter) return true;
    const prev = this.save.career[event.unlockAfter];
    return Boolean(prev && prev.place <= 3);
  }

  careerUnlockedCount() {
    return CAREER_EVENTS.filter((e) => this.isCareerUnlocked(e)).length;
  }

  recordCareer(eventId, result) {
    const prev = this.save.career[eventId] || {};
    const bestPlace = prev.place ? Math.min(prev.place, result.place) : result.place;
    const bestTime = prev.time ? Math.min(prev.time, result.time) : result.time;
    this.save.career[eventId] = {
      place: bestPlace,
      time: bestTime,
      bestLap: prev.bestLap ? Math.min(prev.bestLap, result.bestLap) : result.bestLap,
      races: (prev.races || 0) + 1,
    };
    this.persist();
  }

  // ---------- Daily ----------
  dailyAvailable() {
    return this.save.daily.lastClaim !== todayKey();
  }

  dailyDayIndex() {
    if (this.dailyAvailable()) {
      return (this.save.daily.lastClaim === yesterdayKey()) ? clamp((this.save.daily.streak || 0) + 1, 1, 7) : 1;
    }
    return clamp(this.save.daily.streak || 1, 1, 7);
  }

  claimDaily() {
    if (!this.dailyAvailable()) return null;
    const yesterday = this.save.daily.lastClaim === yesterdayKey();
    const nextStreak = yesterday ? Math.min(7, (this.save.daily.streak || 0) + 1) : 1;
    const amount = DAILY_REWARDS[nextStreak - 1];
    this.save.daily.lastClaim = todayKey();
    this.save.daily.streak = nextStreak;
    this.addCoins(amount);
    return { amount, day: nextStreak };
  }

  // ---------- Missions ----------
  ensureMissions() {
    const today = todayKey();
    if (!this.save.missions || this.save.missions.date !== today) {
      const seed = Number(today.replace(/-/g, '')) % 997;
      const picked = [];
      const pool = [...MISSION_POOL];
      for (let i = 0; i < 3; i++) {
        const idx = (seed * (i + 3) + i * 7) % pool.length;
        picked.push(pool.splice(idx, 1)[0]);
      }
      this.save.missions = {
        date: today,
        list: picked.map((m, i) => ({ ...m, id: `${today}-${i}`, claimed: false, progress: 0 })),
      };
      this.persist();
    }
    return this.save.missions.list;
  }

  get missions() { return this.ensureMissions(); }

  missionReady() {
    const m = this.missions.find((x) => !x.claimed && x.progress >= x.target);
    return Boolean(m) || this.dailyAvailable();
  }

  claimMission(id) {
    const m = this.missions.find((x) => x.id === id);
    if (!m || m.claimed || m.progress < m.target) return null;
    m.claimed = true;
    this.addCoins(m.reward);
    return m.reward;
  }

  recordRace({ place, time, bestLap, topSpeed, coinsCollected, drift, boosts, jumps, checkpoints, mode, eventId }) {
    this.save.stats.races = (this.save.stats.races || 0) + 1;
    if (place === 1) this.save.stats.wins = (this.save.stats.wins || 0) + 1;
    if (bestLap && (!this.save.stats.bestLap || bestLap < this.save.stats.bestLap)) {
      this.save.stats.bestLap = bestLap;
    }
    if (mode === 'career' && eventId) {
      this.recordCareer(eventId, { place, time, bestLap });
    } else if (mode === 'time') {
      const prev = this.save.bestTimes.timeTrial;
      if (!prev || time < prev) this.save.bestTimes.timeTrial = time;
    }
    if (mode === 'quick') {
      const prev = this.save.bestTimes.quick;
      if (!prev || time < prev) this.save.bestTimes.quick = time;
    }

    const list = this.ensureMissions();
    for (const m of list) {
      if (m.claimed) continue;
      if (m.type === 'coins') m.progress += coinsCollected;
      else if (m.type === 'drift') m.progress += Math.round(drift);
      else if (m.type === 'boost') m.progress += boosts;
      else if (m.type === 'jump') m.progress += jumps;
      else if (m.type === 'races') m.progress += 1;
      else if (m.type === 'top3') m.progress += place <= 3 ? 1 : 0;
      else if (m.type === 'checkpoint') m.progress += checkpoints;
      m.progress = Math.min(m.progress, m.target);
    }
    this.persist();
  }

  reset() {
    this.save = defaultSave();
    this.persist();
  }
}

import * as THREE from 'three';
import { clamp, lerp, smoothstep, wrap01, wrapDelta } from '../core/utils.js';

const CONTROL_POINTS = [
  [200, -16], [217, 56], [179, 126], [100, 158], [19, 160], [-56, 158],
  [-139, 143], [-207, 94], [-219, 18], [-186, -48], [-146, -102],
  [-99, -157], [-23, -196], [66, -185], [129, -133], [165, -75],
];

const WAVE = {
  ax: 0.32, az: 0.44, axz: 0.58,
  t1: 1.25, t2: 0.95, t3: 1.8,
  a1: 0.10, a2: 0.07, a3: 0.045,
};

/** Shared CPU/GPU wave height. Keep in sync with Water.js. */
export function waveHeight(x, z, time) {
  return (
    Math.sin(x * WAVE.ax + time * WAVE.t1) * WAVE.a1 +
    Math.sin(z * WAVE.az - time * WAVE.t2) * WAVE.a2 +
    Math.sin((x + z) * WAVE.axz + time * WAVE.t3) * WAVE.a3
  );
}

export class Track {
  constructor() {
    const points = CONTROL_POINTS.map(([x, z]) => new THREE.Vector3(x, 0, z));
    this.curve = new THREE.CatmullRomCurve3(points, true, 'centripetal', 0.5);
    this.length = this.curve.getLength();
    this.sampleCount = 1200;
    this.pts = [];
    this.tangents = [];
    this.lefts = [];
    this.widths = [];
    for (let i = 0; i < this.sampleCount; i++) {
      const t = i / this.sampleCount;
      const p = this.curve.getPointAt(t);
      const tan = this.curve.getTangentAt(t).setY(0).normalize();
      const left = new THREE.Vector3(-tan.z, 0, tan.x).normalize();
      this.pts.push(p);
      this.tangents.push(tan);
      this.lefts.push(left);
      this.widths.push(this.getWidth(t));
    }
    this.gateCount = 8;
    this.gateFractions = Array.from({ length: this.gateCount }, (_, i) => (i + 1) / this.gateCount);
    this.gateDistances = this.gateFractions.map((f) => f * this.length);
    this.rampTs = [0.20, 0.70];
    this.startFrame = this.getFrameAt(0);
  }

  getWidth(t) {
    t = wrap01(t);
    let base = 30 + Math.sin(t * Math.PI * 4 + 0.8) * 2.3 + Math.cos(t * Math.PI * 6 + 1.9) * 1.3;
    const narrow = smoothstep(0.14, 0.20, t) * (1 - smoothstep(0.27, 0.34, t));
    base -= narrow * 5.2;
    const wide = smoothstep(0.62, 0.69, t) * (1 - smoothstep(0.79, 0.87, t));
    base += wide * 4.2;
    return clamp(base, 23.5, 36);
  }

  getFrameAt(t) {
    t = wrap01(t);
    const f = t * this.sampleCount;
    const i0 = Math.floor(f) % this.sampleCount;
    const i1 = (i0 + 1) % this.sampleCount;
    const a = f - Math.floor(f);
    const pos = this.pts[i0].clone().lerp(this.pts[i1], a);
    const tangent = this.tangents[i0].clone().lerp(this.tangents[i1], a).normalize();
    const left = this.lefts[i0].clone().lerp(this.lefts[i1], a).normalize();
    const width = lerp(this.widths[i0], this.widths[i1], a);
    return { t, pos, tangent, left, width, index: i0 };
  }

  offset(t, lateral, y = 0, target = new THREE.Vector3()) {
    const f = this.getFrameAt(t);
    return target.copy(f.pos).addScaledVector(f.left, lateral).setY(y);
  }

  /** Returns nearest point on the centreline, searching near a hint to stay cheap. */
  nearest(position, hint = null, window = 70) {
    let bestIndex = 0;
    let bestDist = Infinity;
    if (hint == null) {
      for (let i = 0; i < this.sampleCount; i += 2) {
        const p = this.pts[i];
        const dx = p.x - position.x;
        const dz = p.z - position.z;
        const d = dx * dx + dz * dz;
        if (d < bestDist) { bestDist = d; bestIndex = i; }
      }
    } else {
      for (let k = -window; k <= window; k++) {
        const i = ((hint + k) % this.sampleCount + this.sampleCount) % this.sampleCount;
        const p = this.pts[i];
        const dx = p.x - position.x;
        const dz = p.z - position.z;
        const d = dx * dx + dz * dz;
        if (d < bestDist) { bestDist = d; bestIndex = i; }
      }
    }
    // Refine around the closest coarse point.
    for (let k = -3; k <= 3; k++) {
      const i = ((bestIndex + k) % this.sampleCount + this.sampleCount) % this.sampleCount;
      const p = this.pts[i];
      const dx = p.x - position.x;
      const dz = p.z - position.z;
      const d = dx * dx + dz * dz;
      if (d < bestDist) { bestDist = d; bestIndex = i; }
    }
    const frame = this.getFrameAt(bestIndex / this.sampleCount);
    const dx = position.x - frame.pos.x;
    const dz = position.z - frame.pos.z;
    const lateral = dx * frame.left.x + dz * frame.left.z;
    return {
      t: bestIndex / this.sampleCount,
      index: bestIndex,
      lateral,
      distance: Math.sqrt(bestDist),
      frame,
    };
  }

  /** Signed shortest delta in t, accounting for the closed loop. */
  deltaT(fromT, toT) {
    return wrapDelta(toT - fromT);
  }

  /** Height of the terrain at a lateral offset, used to place vegetation and props. */
  bankHeight(t, absLateral) {
    const half = this.getWidth(t) / 2;
    if (absLateral <= half - 1) return -0.5;
    if (absLateral < half + 5) return 0.16 + Math.sin(absLateral * 0.5) * 0.04;
    if (absLateral < half + 15) return 0.42;
    if (absLateral < half + 34) {
      return 0.9 + smoothstep(half + 15, half + 34, absLateral) * 2.1 + Math.sin(absLateral * 0.4 + t * 50) * 0.18;
    }
    return 3.2 + (absLateral - half - 34) * 0.105 + Math.sin(absLateral * 0.21 + t * 37) * 0.7;
  }

  waterHeight(position, time) {
    return waveHeight(position.x, position.z, time);
  }

  /** Place a racer safely on the course. */
  gridPosition(row, column) {
    const t = 0.985 - row * 0.0065;
    const lateral = (column - 1) * 7.4 + (row === 1 ? 3.7 : 0);
    const f = this.getFrameAt(t);
    return {
      t,
      position: f.pos.clone().addScaledVector(f.left, lateral),
      tangent: f.tangent.clone(),
      left: f.left.clone(),
      lateral,
      row,
      column,
    };
  }
}

export { WAVE };

import * as THREE from 'three';
import { WAVE } from './Track.js';

const vertexShader = /* glsl */`
  uniform float uTime;
  varying vec2 vUv;
  varying vec3 vWorld;
  varying float vWave;
  varying float vViewDist;

  float getWave(vec2 p) {
    return sin(p.x * ${WAVE.ax.toFixed(3)} + uTime * ${WAVE.t1.toFixed(3)}) * ${WAVE.a1.toFixed(3)}
         + sin(p.y * ${WAVE.az.toFixed(3)} - uTime * ${WAVE.t2.toFixed(3)}) * ${WAVE.a2.toFixed(3)}
         + sin((p.x + p.y) * ${WAVE.axz.toFixed(3)} + uTime * ${WAVE.t3.toFixed(3)}) * ${WAVE.a3.toFixed(3)};
  }

  void main() {
    vec3 p = position;
    vUv = uv;
    float h = getWave(p.xz);
    p.y += h;
    vWave = h;
    vec4 world = modelMatrix * vec4(p, 1.0);
    vWorld = world.xyz;
    vec4 mv = viewMatrix * world;
    vViewDist = -mv.z;
    gl_Position = projectionMatrix * mv;
  }
`;

const fragmentShader = /* glsl */`
  precision highp float;

  uniform float uTime;
  uniform vec3 uDeep;
  uniform vec3 uShallow;
  uniform vec3 uFoam;
  uniform vec3 uSky;
  uniform vec3 uSand;
  uniform vec3 uSunDir;
  uniform vec3 uSunColor;
  uniform vec3 uFog;
  uniform vec3 uTint;

  varying vec2 vUv;
  varying vec3 vWorld;
  varying float vWave;
  varying float vViewDist;

  float hash(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
  }

  float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash(i);
    float b = hash(i + vec2(1.0, 0.0));
    float c = hash(i + vec2(0.0, 1.0));
    float d = hash(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
  }

  float fbm(vec2 p) {
    float v = 0.0;
    v += noise(p) * 0.55;
    v += noise(p * 2.03 + 4.7) * 0.28;
    v += noise(p * 4.01 - 8.2) * 0.17;
    return v;
  }

  float waveDerivX(vec2 p) {
    return cos(p.x * ${WAVE.ax.toFixed(3)} + uTime * ${WAVE.t1.toFixed(3)}) * ${(WAVE.a1 * WAVE.ax).toFixed(4)}
         + cos((p.x + p.y) * ${WAVE.axz.toFixed(3)} + uTime * ${WAVE.t3.toFixed(3)}) * ${(WAVE.a3 * WAVE.axz).toFixed(4)};
  }

  float waveDerivZ(vec2 p) {
    return cos(p.y * ${WAVE.az.toFixed(3)} - uTime * ${WAVE.t2.toFixed(3)}) * ${(WAVE.a2 * WAVE.az).toFixed(4)}
         + cos((p.x + p.y) * ${WAVE.axz.toFixed(3)} + uTime * ${WAVE.t3.toFixed(3)}) * ${(WAVE.a3 * WAVE.axz).toFixed(4)};
  }

  void main() {
    vec2 flowUv = vec2(vUv.x, vUv.y);
    float edge = abs(flowUv.x - 0.5) * 2.0;
    float longFlow = vUv.y * 34.0;
    float t = uTime;

    float n1 = fbm(vec2(flowUv.x * 9.0, longFlow - t * 0.55));
    float n2 = fbm(vec2(flowUv.x * 22.0 + 3.0, longFlow * 2.3 - t * 0.95));
    float n3 = fbm(vec2(flowUv.x * 44.0 - 12.0, longFlow * 4.2 - t * 1.55));

    // Analytic surface normal so the water reads smooth even with low-poly geometry.
    vec3 normal = normalize(vec3(
      -waveDerivX(vWorld.xz) - (n2 - 0.5) * 0.10,
      1.0,
      -waveDerivZ(vWorld.xz) - (n1 - 0.5) * 0.10
    ));

    vec3 viewDir = normalize(cameraPosition - vWorld);

    // Depth / distance from bank colour ramp, with brown-green tropical water.
    float shallow = smoothstep(0.35, 1.0, edge + (n1 - 0.5) * 0.28);
    vec3 base = mix(uDeep, uShallow, shallow * 0.72);
    base = mix(base, uSand, smoothstep(0.88, 1.0, edge + (n2 - 0.5) * 0.12) * 0.42);
    base *= 0.93 + n3 * 0.16;

    // Moving current streaks and surface chop.
    float streak = smoothstep(0.58, 0.82, fbm(vec2(flowUv.x * 17.0, longFlow * 1.7 - t * 1.2)));
    base += uShallow * streak * 0.10;

    // Sky reflection.
    float fresnel = pow(1.0 - clamp(dot(normal, viewDir), 0.0, 1.0), 3.2);
    vec3 col = mix(base, uSky, fresnel * 0.52);
    col = mix(col, uTint, 0.08);

    // Shoreline foam: a soft band plus lacy foam pulled along by the current.
    float edgeBand = smoothstep(0.80, 0.995, edge + (n1 - 0.5) * 0.09);
    float lace = smoothstep(0.48, 0.79, fbm(vec2(flowUv.x * 14.0, longFlow * 2.6 - t * 1.9)));
    float bankFoam = edgeBand * (0.35 + lace * 0.65);
    float crest = smoothstep(0.085, 0.12, abs(vWave)) * smoothstep(0.55, 0.9, n2) * 0.28;
    float foam = clamp(bankFoam + crest, 0.0, 1.0);
    vec3 foamColor = uFoam * (0.88 + n3 * 0.16);
    col = mix(col, foamColor, foam * 0.92);

    // Sun specular + sparkle.
    vec3 halfV = normalize(uSunDir + viewDir);
    float spec = pow(max(dot(normal, halfV), 0.0), 140.0);
    col += uSunColor * spec * 1.35;
    float sparkle = step(0.985, hash(floor(vUv * vec2(150.0, 900.0)) + floor(t * 2.0))) * pow(max(dot(normal, halfV), 0.0), 8.0);
    col += vec3(sparkle) * 0.6;

    // Distance haze keeps the horizon soft on mobile.
    float fogF = smoothstep(120.0, 520.0, vViewDist);
    col = mix(col, uFog, fogF);

    gl_FragColor = vec4(col, 1.0);
  }
`;

export class Water {
  constructor(track) {
    this.track = track;
    this.group = new THREE.Group();
    this.material = new THREE.ShaderMaterial({
      vertexShader,
      fragmentShader,
      side: THREE.DoubleSide,
      uniforms: {
        uTime: { value: 0 },
        uDeep: { value: new THREE.Color('#1e4d41') },
        uShallow: { value: new THREE.Color('#748a4f') },
        uFoam: { value: new THREE.Color('#e9f7de') },
        uSky: { value: new THREE.Color('#c4e7d4') },
        uSand: { value: new THREE.Color('#a99c62') },
        uSunDir: { value: new THREE.Vector3(-0.28, 0.52, 0.78).normalize() },
        uSunColor: { value: new THREE.Color('#fff1c4') },
        uFog: { value: new THREE.Color('#b9dfc6') },
        uTint: { value: new THREE.Color('#6f9b64') },
      },
    });
    this.mesh = new THREE.Mesh(this.buildGeometry(), this.material);
    this.mesh.renderOrder = 1;
    this.mesh.frustumCulled = false;
    this.group.add(this.mesh);
  }

  buildGeometry() {
    const cols = 18;
    const rows = 420;
    const positions = new Float32Array((rows + 1) * (cols + 1) * 3);
    const uvs = new Float32Array((rows + 1) * (cols + 1) * 2);
    const indices = [];
    const t = this.track;
    for (let j = 0; j <= rows; j++) {
      const tt = j / rows;
      const f = t.getFrameAt(tt);
      const half = f.width / 2 + 0.15;
      for (let i = 0; i <= cols; i++) {
        const u = i / cols;
        const lateral = (u - 0.5) * 2 * half;
        const x = f.pos.x + f.left.x * lateral;
        const z = f.pos.z + f.left.z * lateral;
        const idx = (j * (cols + 1) + i) * 3;
        positions[idx] = x;
        positions[idx + 1] = 0;
        positions[idx + 2] = z;
        const uvIdx = (j * (cols + 1) + i) * 2;
        uvs[uvIdx] = u;
        uvs[uvIdx + 1] = tt * 19;
      }
    }
    for (let j = 0; j < rows; j++) {
      for (let i = 0; i < cols; i++) {
        const a = j * (cols + 1) + i;
        const b = a + 1;
        const c = a + cols + 1;
        const d = c + 1;
        indices.push(a, c, b, b, c, d);
      }
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geo.setAttribute('uv', new THREE.BufferAttribute(uvs, 2));
    geo.setIndex(indices);
    geo.computeBoundingSphere();
    return geo;
  }

  update(time) {
    this.material.uniforms.uTime.value = time;
  }

  applyPalette(p) {
    const u = this.material.uniforms;
    u.uDeep.value.set(p.waterDeep);
    u.uShallow.value.set(p.waterShallow);
    u.uFoam.value.set(p.waterFoam);
    u.uSky.value.set(p.waterSky);
    u.uFog.value.set(p.fog);
    u.uSunColor.value.set(p.sun);
    u.uSunDir.value.set(...p.sunPos).normalize();
    u.uSand.value.set('#a99c62');
    u.uTint.value.set(p.waterShallow);
  }
}

import * as THREE from 'three';
import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';
import { makeGlowTexture } from '../core/utils.js';

const glowTex = typeof document !== 'undefined' ? makeGlowTexture(96) : null;

function hullGeometry() {
  const stations = [
    { z: -1.42, w: 0.46, deck: 0.24, mid: -0.02, bottom: -0.24, keel: -0.34 },
    { z: -1.1, w: 0.58, deck: 0.27, mid: -0.03, bottom: -0.27, keel: -0.37 },
    { z: -0.55, w: 0.64, deck: 0.3, mid: -0.03, bottom: -0.3, keel: -0.4 },
    { z: 0.1, w: 0.63, deck: 0.31, mid: -0.02, bottom: -0.29, keel: -0.39 },
    { z: 0.65, w: 0.51, deck: 0.28, mid: 0.0, bottom: -0.23, keel: -0.31 },
    { z: 1.08, w: 0.3, deck: 0.25, mid: 0.04, bottom: -0.12, keel: -0.16 },
    { z: 1.3, w: 0.08, deck: 0.28, mid: 0.15, bottom: 0.05, keel: 0.02 },
  ];
  const ringSize = 8;
  const positions = [];
  const indices = [];
  for (let s = 0; s < stations.length; s++) {
    const st = stations[s];
    const ring = [
      [0, st.deck + 0.055],
      [-st.w, st.deck],
      [-st.w, st.mid],
      [-st.w * 0.72, st.bottom],
      [0, st.keel],
      [st.w * 0.72, st.bottom],
      [st.w, st.mid],
      [st.w, st.deck],
    ];
    for (const [x, y] of ring) positions.push(x, y, st.z);
  }
  for (let s = 0; s < stations.length - 1; s++) {
    for (let i = 0; i < ringSize; i++) {
      const a = s * ringSize + i;
      const b = s * ringSize + ((i + 1) % ringSize);
      const c = (s + 1) * ringSize + i;
      const d = (s + 1) * ringSize + ((i + 1) % ringSize);
      indices.push(a, c, b, b, c, d);
    }
  }
  // close the stern
  for (let i = 1; i < ringSize - 1; i++) {
    indices.push(0, i + 1, i);
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geo.setIndex(indices);
  geo.computeVertexNormals();
  return geo;
}

const hullGeo = hullGeometry();
const seatGeo = new RoundedBoxGeometry(0.78, 0.3, 1.25, 3, 0.12);
const consoleGeo = new RoundedBoxGeometry(0.62, 0.32, 0.65, 3, 0.1);
const barColumnGeo = new THREE.CylinderGeometry(0.055, 0.075, 0.5, 7);
const barGeo = new THREE.CylinderGeometry(0.038, 0.038, 0.9, 6);
const gripGeo = new THREE.CylinderGeometry(0.05, 0.05, 0.18, 6);
const windshieldGeo = new THREE.PlaneGeometry(0.72, 0.42);
const nozzleGeo = new THREE.CylinderGeometry(0.11, 0.16, 0.28, 8);
const sphereGeo = new THREE.SphereGeometry(1, 12, 8);
const capsuleGeo = new THREE.CapsuleGeometry(0.12, 0.34, 3, 7);
const limbGeo = new THREE.CylinderGeometry(0.07, 0.082, 1, 6);

function cylBetween(a, b, radius, material) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  const mesh = new THREE.Mesh(radius > 0.07 ? limbGeo : capsuleGeo, material);
  if (radius > 0.07) {
    mesh.scale.set(1, len, 1);
  } else {
    mesh.scale.set(radius / 0.12, len / 0.58, radius / 0.12);
  }
  mesh.position.copy(a).addScaledVector(dir, 0.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  return mesh;
}

export class JetSki {
  constructor({
    c1 = '#7af3d5', c2 = '#0e7269', accent = '#d8ff5d', trim = '#f4fff9',
    rider = true, riderColor = '#ff8a3d', helmet = '#f8f5e6',
  } = {}) {
    this.group = new THREE.Group();
    this.body = new THREE.Group();
    this.group.add(this.body);
    this.phase = Math.random() * Math.PI * 2;
    this.speed = 0;
    this.steer = 0;
    this.drift = 0;
    this.boost = 0;
    this.airborne = false;
    this.shieldOn = false;

    const hullMat = new THREE.MeshStandardMaterial({
      color: trim, roughness: 0.48, metalness: 0.08, flatShading: true,
    });
    const accentMat = new THREE.MeshStandardMaterial({
      color: c1, roughness: 0.4, metalness: 0.1, flatShading: true,
    });
    const darkMat = new THREE.MeshStandardMaterial({ color: '#172a27', roughness: 0.82, metalness: 0.02 });
    const trimMat = new THREE.MeshStandardMaterial({ color: c2, roughness: 0.62, metalness: 0.02, flatShading: true });
    const metalMat = new THREE.MeshStandardMaterial({ color: '#9fb6b2', roughness: 0.3, metalness: 0.7 });
    const glassMat = new THREE.MeshStandardMaterial({
      color: '#bfe9e0', roughness: 0.1, metalness: 0.2, transparent: true, opacity: 0.34, side: THREE.DoubleSide,
    });
    const gloveMat = new THREE.MeshStandardMaterial({ color: '#202b29', roughness: 0.8 });
    const skinMat = new THREE.MeshStandardMaterial({ color: '#c88154', roughness: 0.72 });
    const vestMat = new THREE.MeshStandardMaterial({ color: riderColor, roughness: 0.65 });
    const helmetMat = new THREE.MeshStandardMaterial({ color: helmet, roughness: 0.32, metalness: 0.08 });
    const visorMat = new THREE.MeshStandardMaterial({ color: '#142523', roughness: 0.1, metalness: 0.5 });
    this.materials = { hullMat, accentMat, darkMat, trimMat };

    const hull = new THREE.Mesh(hullGeo, hullMat);
    this.body.add(hull);

    // Lower hull accent shell.
    const lower = new THREE.Mesh(hullGeo, trimMat);
    lower.scale.set(1.008, 0.72, 1.002);
    lower.position.y = -0.17;
    this.body.add(lower);

    for (const side of [-1, 1]) {
      const stripe = new THREE.Mesh(new THREE.BoxGeometry(0.035, 0.12, 2.05), accentMat);
      stripe.position.set(side * 0.615, 0.06, 0.05);
      stripe.rotation.z = side * 0.12;
      this.body.add(stripe);
      const rail = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.06, 1.6), darkMat);
      rail.position.set(side * 0.52, 0.315, -0.25);
      this.body.add(rail);
    }

    const seat = new THREE.Mesh(seatGeo, darkMat);
    seat.position.set(0, 0.43, -0.3);
    this.body.add(seat);
    const seatAccent = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.04, 0.12), accentMat);
    seatAccent.position.set(0, 0.59, -0.28);
    this.body.add(seatAccent);

    const consoleMesh = new THREE.Mesh(consoleGeo, trimMat);
    consoleMesh.position.set(0, 0.44, 0.38);
    consoleMesh.rotation.x = -0.13;
    this.body.add(consoleMesh);
    const consoleTop = new THREE.Mesh(new RoundedBoxGeometry(0.46, 0.08, 0.34, 2, 0.05), darkMat);
    consoleTop.position.set(0, 0.58, 0.35);
    consoleTop.rotation.x = -0.13;
    this.body.add(consoleTop);

    const column = new THREE.Mesh(barColumnGeo, metalMat);
    column.position.set(0, 0.72, 0.55);
    column.rotation.x = 0.28;
    this.body.add(column);
    const bar = new THREE.Mesh(barGeo, metalMat);
    bar.rotation.z = Math.PI / 2;
    bar.position.set(0, 0.92, 0.49);
    this.body.add(bar);
    for (const side of [-1, 1]) {
      const grip = new THREE.Mesh(gripGeo, gloveMat);
      grip.rotation.z = Math.PI / 2;
      grip.position.set(side * 0.4, 0.92, 0.49);
      this.body.add(grip);
    }

    const windshield = new THREE.Mesh(windshieldGeo, glassMat);
    windshield.position.set(0, 0.69, 0.62);
    windshield.rotation.x = -0.54;
    this.body.add(windshield);
    const cowl = new THREE.Mesh(new RoundedBoxGeometry(0.68, 0.2, 0.4, 2, 0.08), trimMat);
    cowl.position.set(0, 0.45, 0.81);
    cowl.rotation.x = -0.1;
    this.body.add(cowl);
    const accentNose = new THREE.Mesh(new THREE.BoxGeometry(0.28, 0.08, 0.55), accentMat);
    accentNose.position.set(0, 0.51, 0.92);
    accentNose.rotation.x = -0.1;
    this.body.add(accentNose);

    const headlight = new THREE.Mesh(new THREE.BoxGeometry(0.24, 0.06, 0.04), new THREE.MeshBasicMaterial({ color: '#eaffb0' }));
    headlight.position.set(0, 0.38, 1.13);
    this.body.add(headlight);

    const nozzle = new THREE.Mesh(nozzleGeo, metalMat);
    nozzle.rotation.x = Math.PI / 2;
    nozzle.position.set(0, 0.02, -1.48);
    this.body.add(nozzle);
    const tail = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.06, 0.05), new THREE.MeshBasicMaterial({ color: '#ff4a3d' }));
    tail.position.set(0, 0.22, -1.42);
    this.body.add(tail);

    // Rear boarding step.
    const step = new THREE.Mesh(new RoundedBoxGeometry(0.7, 0.055, 0.28, 2, 0.03), darkMat);
    step.position.set(0, 0.21, -1.28);
    this.body.add(step);

    if (rider) {
      this.rider = new THREE.Group();
      const hipY = 0.6;
      const hips = new THREE.Mesh(new THREE.SphereGeometry(0.23, 8, 6), vestMat);
      hips.scale.set(1.2, 0.85, 1);
      hips.position.set(0, hipY, -0.36);
      this.rider.add(hips);

      const torso = new THREE.Mesh(capsuleGeo, vestMat);
      torso.scale.set(1.6, 1.35, 1.2);
      torso.position.set(0, hipY + 0.3, -0.24);
      torso.rotation.x = -0.26;
      this.rider.add(torso);
      const vestStripe = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.08, 0.28), new THREE.MeshStandardMaterial({ color: '#f8f5e6', roughness: 0.6 }));
      vestStripe.position.set(0, hipY + 0.35, -0.12);
      vestStripe.rotation.x = -0.26;
      this.rider.add(vestStripe);

      const neck = new THREE.Mesh(cylBetween(
        new THREE.Vector3(0, hipY + 0.48, -0.16),
        new THREE.Vector3(0, hipY + 0.61, -0.17),
        0.06, skinMat,
      ));
      this.rider.add(...[neck]);
      const head = new THREE.Mesh(sphereGeo, helmetMat);
      head.scale.set(0.21, 0.24, 0.22);
      head.position.set(0, hipY + 0.82, -0.18);
      this.rider.add(head);
      const visor = new THREE.Mesh(new THREE.BoxGeometry(0.27, 0.1, 0.08), visorMat);
      visor.position.set(0, hipY + 0.82, -0.02);
      visor.rotation.x = -0.15;
      this.rider.add(visor);

      const shoulderL = new THREE.Vector3(-0.24, hipY + 0.46, -0.15);
      const shoulderR = new THREE.Vector3(0.24, hipY + 0.46, -0.15);
      const gripL = new THREE.Vector3(-0.38, 0.96, 0.47);
      const gripR = new THREE.Vector3(0.38, 0.96, 0.47);
      const elbowL = new THREE.Vector3(-0.36, hipY + 0.3, 0.18);
      const elbowR = new THREE.Vector3(0.36, hipY + 0.3, 0.18);
      this.rider.add(cylBetween(shoulderL, elbowL, 0.065, vestMat), cylBetween(elbowL, gripL, 0.058, skinMat));
      this.rider.add(cylBetween(shoulderR, elbowR, 0.065, vestMat), cylBetween(elbowR, gripR, 0.058, skinMat));
      const kneeL = new THREE.Vector3(-0.32, hipY + 0.04, 0.12);
      const kneeR = new THREE.Vector3(0.32, hipY + 0.04, 0.12);
      const footL = new THREE.Vector3(-0.3, 0.3, -0.35);
      const footR = new THREE.Vector3(0.3, 0.3, -0.35);
      this.rider.add(cylBetween(new THREE.Vector3(-0.17, hipY - 0.06, -0.32), kneeL, 0.09, darkMat));
      this.rider.add(cylBetween(new THREE.Vector3(0.17, hipY - 0.06, -0.32), kneeR, 0.09, darkMat));
      this.rider.add(cylBetween(kneeL, footL, 0.075, darkMat));
      this.rider.add(cylBetween(kneeR, footR, 0.075, darkMat));
      const bootL = new THREE.Mesh(new RoundedBoxGeometry(0.19, 0.14, 0.34, 2, 0.05), darkMat);
      bootL.position.set(-0.3, 0.26, -0.43);
      this.rider.add(bootL);
      const bootR = bootL.clone();
      bootR.position.x = 0.3;
      this.rider.add(bootR);
      this.body.add(this.rider);
    }

    // Shield bubble.
    this.shield = new THREE.Mesh(
      new THREE.IcosahedronGeometry(1.85, 2),
      new THREE.MeshBasicMaterial({
        color: '#ffd356', transparent: true, opacity: 0.11,
        blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide,
      }),
    );
    this.shield.position.y = 0.55;
    this.shield.scale.set(1, 0.72, 1.25);
    this.shield.visible = false;
    this.group.add(this.shield);

    // Boost / nitro glow.
    this.glow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTex, color: new THREE.Color('#65fff0'), transparent: true,
      blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0,
    }));
    this.glow.position.set(0, 0.15, -1.6);
    this.glow.scale.setScalar(1.9);
    this.group.add(this.glow);

    // Fake baked shadow, separate so it doesn't tilt on waves.
    this.shadow = new THREE.Mesh(
      new THREE.PlaneGeometry(2.4, 3.6),
      new THREE.MeshBasicMaterial({
        map: glowTex, color: '#06221d', transparent: true, opacity: 0.32,
        depthWrite: false,
      }),
    );
    this.shadow.rotation.x = -Math.PI / 2;
    this.shadow.renderOrder = 2;
    this.shadow.visible = false;
  }

  addTo(parent) {
    parent.add(this.group);
    parent.add(this.shadow);
  }

  setTransform(position, yaw, waterY, time, opts = {}) {
    const { speed = 0, steer = 0, drift = 0, boost = 0, airborne = false, shield = false, stun = 0, idle = false } = opts;
    this.speed = speed;
    this.steer = steer;
    this.drift = drift;
    this.boost = boost;

    const bob = Math.sin(time * 5.1 + this.phase) * 0.045 + Math.sin(time * 2.3 + this.phase * 1.7) * 0.028;
    this.group.position.set(position.x, waterY + (airborne ? 0 : 0.02) + bob, position.z);
    this.group.rotation.y = yaw;
    this.group.rotation.x = airborne ? -0.12 : Math.sin(time * 3.4 + this.phase) * 0.018 + (speed / 45) * -0.015;
    this.group.rotation.z = -steer * 0.24 - drift * 0.12;

    if (this.rider) {
      this.rider.rotation.z = -steer * 0.2;
      this.rider.rotation.x = Math.sin(time * 4.2 + this.phase) * 0.012;
    }
    this.shield.visible = shield;
    if (shield) {
      const pulse = 1 + Math.sin(time * 6) * 0.025;
      this.shield.scale.set(1 * pulse, 0.72 * pulse, 1.25 * pulse);
      this.shield.material.opacity = 0.1 + Math.sin(time * 5) * 0.03;
    }

    const boostAmt = Math.max(0, boost);
    this.glow.material.opacity = boostAmt > 0.02 ? 0.6 + Math.sin(time * 20) * 0.15 : 0;
    this.glow.scale.setScalar(1.5 + boostAmt * 1.1 + Math.sin(time * 16) * 0.16);
    this.glow.position.z = -1.6 - boostAmt * 0.25;

    this.shadow.visible = !airborne;
    this.shadow.position.set(position.x, waterY + 0.06, position.z);
    this.shadow.rotation.z = -yaw;
    const shScale = airborne ? 0.8 : 1;
    this.shadow.scale.setScalar(shScale);
    this.shadow.material.opacity = 0.3 - Math.min(0.14, speed * 0.002);

    if (stun > 0) {
      this.body.rotation.z = Math.sin(time * 32) * 0.09 * Math.min(1, stun * 2);
    } else {
      this.body.rotation.z = 0;
    }
    if (idle) {
      this.group.position.y += Math.sin(time * 2.1 + this.phase) * 0.02;
    }
  }

  dispose(scene) {
    scene.remove(this.group);
    scene.remove(this.shadow);
    this.group.traverse((o) => {
      if (o.geometry && ![hullGeo, seatGeo, consoleGeo, barColumnGeo, barGeo, gripGeo, windshieldGeo, nozzleGeo, sphereGeo, capsuleGeo, limbGeo].includes(o.geometry)) {
        o.geometry.dispose?.();
      }
    });
  }
}

import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import { makeGlowTexture, makeBannerTexture, makeNoise2D, seededRandom, lerp, clamp, PALETTES } from '../core/utils.js';

const skyVert = /* glsl */`
  varying vec3 vDir;
  void main() {
    vDir = normalize(position);
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    gl_Position = projectionMatrix * mv;
  }
`;

const skyFrag = /* glsl */`
  uniform vec3 uTop;
  uniform vec3 uMid;
  uniform vec3 uHorizon;
  uniform vec3 uSun;
  uniform vec3 uSunDir;
  varying vec3 vDir;

  void main() {
    vec3 d = normalize(vDir);
    float h = clamp(d.y, 0.0, 1.0);
    vec3 col = mix(uHorizon, uMid, smoothstep(0.0, 0.28, h));
    col = mix(col, uTop, smoothstep(0.16, 0.9, h));
    float sunDot = max(dot(d, normalize(uSunDir)), 0.0);
    col += uSun * pow(sunDot, 1200.0) * 3.4;
    col += uSun * pow(sunDot, 38.0) * 0.22;
    col += uSun * pow(sunDot, 6.0) * 0.05;
    // soft warm haze near the horizon
    col = mix(col, uHorizon, smoothstep(0.12, -0.08, d.y) * 0.45);
    gl_FragColor = vec4(col, 1.0);
  }
`;

const fallVert = /* glsl */`
  varying vec2 vUv;
  void main() {
    vUv = uv;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;

const fallFrag = /* glsl */`
  uniform float uTime;
  uniform vec3 uColor;
  varying vec2 vUv;
  float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
  float noise(vec2 p) {
    vec2 i = floor(p), f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash(i), hash(i + vec2(1,0)), f.x), mix(hash(i + vec2(0,1)), hash(i + vec2(1,1)), f.x), f.y);
  }
  void main() {
    vec2 uv = vUv;
    float n = noise(vec2(uv.x * 10.0, uv.y * 8.0 - uTime * 3.4));
    float n2 = noise(vec2(uv.x * 28.0 + 2.0, uv.y * 26.0 - uTime * 6.0));
    float streak = smoothstep(0.36, 0.72, n * 0.65 + n2 * 0.5);
    float edge = smoothstep(0.0, 0.16, uv.x) * smoothstep(1.0, 0.84, uv.x);
    float alpha = (0.2 + streak * 0.8) * edge;
    vec3 col = mix(vec3(0.66, 0.84, 0.8), uColor, streak);
    gl_FragColor = vec4(col, alpha * 0.9);
  }
`;

function leafGeometry() {
  const leaves = [];
  const count = 9;
  for (let i = 0; i < count; i++) {
    const g = new THREE.PlaneGeometry(1.15, 3.9, 1, 5);
    g.translate(0, 1.9, 0);
    const pos = g.attributes.position;
    for (let v = 0; v < pos.count; v++) {
      const y = pos.getY(v);
      const f = clamp(y / 3.9, 0, 1);
      pos.setX(v, pos.getX(v) * (1 - f * 0.78));
      pos.setZ(v, -f * f * 0.85);
    }
    g.rotateX(-Math.PI / 2 + 0.38);
    g.rotateY((i / count) * Math.PI * 2 + (i % 2) * 0.12);
    g.translate(0, 0.15 + (i % 3) * 0.1, 0);
    leaves.push(g);
  }
  const merged = mergeGeometries(leaves, false);
  leaves.forEach((g) => g.dispose());
  merged.computeVertexNormals();
  return merged;
}

function broadCanopyGeometry() {
  const parts = [];
  const puffs = [
    [0, 0, 0, 1.0],
    [0.8, 0.35, 0.2, 0.72],
    [-0.65, 0.45, -0.15, 0.68],
    [0.05, 0.7, -0.6, 0.6],
  ];
  for (const [x, y, z, s] of puffs) {
    const g = new THREE.IcosahedronGeometry(1.7, 0);
    g.scale(s, s * 0.75, s);
    g.translate(x, y, z);
    parts.push(g);
  }
  const merged = mergeGeometries(parts, false);
  parts.forEach((g) => g.dispose());
  return merged;
}

const palmLeaves = typeof document !== 'undefined' ? leafGeometry() : null;
const broadCanopy = typeof document !== 'undefined' ? broadCanopyGeometry() : null;
const trunkGeo = (() => {
  const g = new THREE.CylinderGeometry(0.13, 0.32, 1, 6, 2);
  g.translate(0, 0.5, 0);
  return g;
})();
const bushGeo = new THREE.IcosahedronGeometry(1, 0);
const rockGeo = new THREE.DodecahedronGeometry(1, 0);
const cloudGeo = new THREE.IcosahedronGeometry(1, 1);
const hutRoofGeo = new THREE.ConeGeometry(4.4, 2.7, 4);
const hutBaseGeo = new THREE.BoxGeometry(4.4, 2.3, 3.8);

export class Environment {
  constructor(scene, track) {
    this.scene = scene;
    this.track = track;
    this.group = new THREE.Group();
    this.scene.add(this.group);
    this.noise = makeNoise2D(8421);
    this.rand = seededRandom(777);
    this.time = 0;
    this.clouds = [];
    this.mist = [];
    this.birds = [];
    this.startLightMats = [];
    this.mountainMaterials = [];
    this.palette = PALETTES.morning;

    this.buildLights();
    this.buildSky();
    this.buildTerrain();
    this.buildMountains();
    this.buildClouds();
    this.buildJungle();
    this.buildBanks();
    this.buildStartArch();
    this.buildBridge();
    this.buildVillage();
    this.buildWaterfall();
    this.buildBirds();
    this.applyPalette('morning');
  }

  buildLights() {
    this.hemi = new THREE.HemisphereLight('#bde9e4', '#385b36', 1.15);
    this.scene.add(this.hemi);
    this.sun = new THREE.DirectionalLight('#fff0cf', 2.2);
    this.sun.position.set(-30, 55, 80);
    this.scene.add(this.sun);
    this.fill = new THREE.DirectionalLight('#9be5d1', 0.35);
    this.fill.position.set(40, 20, -60);
    this.scene.add(this.fill);
  }

  buildSky() {
    this.skyMat = new THREE.ShaderMaterial({
      vertexShader: skyVert,
      fragmentShader: skyFrag,
      side: THREE.BackSide,
      depthWrite: false,
      uniforms: {
        uTop: { value: new THREE.Color('#3f9fd0') },
        uMid: { value: new THREE.Color('#9adbd4') },
        uHorizon: { value: new THREE.Color('#f5e7b8') },
        uSun: { value: new THREE.Color('#fff1c4') },
        uSunDir: { value: new THREE.Vector3(-0.28, 0.52, 0.78).normalize() },
      },
    });
    this.sky = new THREE.Mesh(new THREE.SphereGeometry(1500, 32, 18), this.skyMat);
    this.sky.renderOrder = -10;
    this.sky.frustumCulled = false;
    this.group.add(this.sky);

    this.sunSprite = new THREE.Sprite(new THREE.SpriteMaterial({
      map: makeGlowTexture(256),
      color: '#fff2c4',
      transparent: true,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      depthTest: false,
      opacity: 0.85,
    }));
    this.sunSprite.scale.setScalar(210);
    this.sunSprite.renderOrder = -9;
    this.group.add(this.sunSprite);
  }

  buildTerrain() {
    const rows = 300;
    const sides = [-1, 1];
    const ringSpecs = [
      { add: 1.8, y: -0.7 },
      { add: 6, y: null },
      { add: 15, y: null },
      { add: 25, y: null },
      { add: 40, y: null },
      { add: 65, y: null },
      { add: 95, y: null },
    ];
    const colors = [new THREE.Color('#d8bd82'), new THREE.Color('#cab373'), new THREE.Color('#a3a463'), new THREE.Color('#69904b'), new THREE.Color('#427a3f'), new THREE.Color('#356d3b'), new THREE.Color('#2b5b35')];
    const pos = [];
    const col = [];
    const idx = [];
    for (const side of sides) {
      const base = pos.length / 3;
      for (let j = 0; j <= rows; j++) {
        const t = j / rows;
        const f = this.track.getFrameAt(t);
        const half = f.width / 2;
        for (let r = 0; r < ringSpecs.length; r++) {
          const spec = ringSpecs[r];
          const absLat = half + spec.add;
          const lateral = absLat * side;
          const y = spec.y ?? this.track.bankHeight(t, absLat);
          const wobble = this.noise(t * 35, r * 7.1) - 0.5;
          const x = f.pos.x + f.left.x * lateral;
          const z = f.pos.z + f.left.z * lateral;
          pos.push(x, y + (r > 1 ? wobble * (r - 1) * 0.42 : 0), z);
          const c = colors[r].clone();
          if (r >= 3) {
            const n = this.noise(x * 0.06, z * 0.06);
            c.offsetHSL((n - 0.5) * 0.025, (n - 0.5) * 0.08, (n - 0.5) * 0.1);
          }
          if (r === 1 && this.noise(t * 90, side) > 0.52) c.lerp(colors[2], 0.65);
          if (r === 0) c.set('#c8a96e');
          col.push(c.r, c.g, c.b);
        }
      }
      for (let j = 0; j < rows; j++) {
        for (let r = 0; r < ringSpecs.length - 1; r++) {
          const a = base + j * ringSpecs.length + r;
          const b = a + 1;
          const c = a + ringSpecs.length;
          const d = c + 1;
          if (side === 1) idx.push(a, c, b, b, c, d);
          else idx.push(a, b, c, b, d, c);
        }
      }
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    geo.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
    geo.setIndex(idx);
    geo.computeVertexNormals();
    this.terrainMat = new THREE.MeshLambertMaterial({ vertexColors: true, flatShading: true });
    this.terrain = new THREE.Mesh(geo, this.terrainMat);
    this.terrain.receiveShadow = false;
    this.group.add(this.terrain);

    // A dark distant floor keeps gaps from showing at the horizon.
    const floor = new THREE.Mesh(
      new THREE.CircleGeometry(1400, 32),
      new THREE.MeshLambertMaterial({ color: '#244f36' }),
    );
    floor.rotation.x = -Math.PI / 2;
    floor.position.y = -28;
    this.group.add(floor);
  }

  buildMountains() {
    const geo = new THREE.ConeGeometry(1, 1, 6, 1);
    geo.translate(0, 0.5, 0);
    const mat = new THREE.MeshLambertMaterial({ color: '#4b7c63', flatShading: true });
    this.mountainMaterials.push(mat);
    const count = 22;
    const mesh = new THREE.InstancedMesh(geo, mat, count);
    const m = new THREE.Matrix4();
    const q = new THREE.Quaternion();
    const s = new THREE.Vector3();
    const p = new THREE.Vector3();
    const rand = seededRandom(909);
    for (let i = 0; i < count; i++) {
      const a = (i / count) * Math.PI * 2 + rand() * 0.22;
      const radius = 560 + rand() * 280;
      const width = 90 + rand() * 150;
      const height = 70 + rand() * 170;
      p.set(Math.cos(a) * radius, -12, Math.sin(a) * radius);
      q.setFromAxisAngle(new THREE.Vector3(0, 1, 0), rand() * Math.PI * 2);
      s.set(width, height, width * (0.7 + rand() * 0.5));
      m.compose(p, q, s);
      mesh.setMatrixAt(i, m);
    }
    mesh.instanceMatrix.needsUpdate = true;
    this.group.add(mesh);
    this.mountains = mesh;
  }

  buildClouds() {
    const mat = new THREE.MeshBasicMaterial({
      color: '#fffaf0', transparent: true, opacity: 0.7, depthWrite: false, fog: true,
    });
    const count = 46;
    const mesh = new THREE.InstancedMesh(cloudGeo, mat, count);
    const rand = seededRandom(2341);
    const m = new THREE.Matrix4();
    const q = new THREE.Quaternion();
    for (let i = 0; i < count; i++) {
      const a = rand() * Math.PI * 2;
      const radius = 320 + rand() * 520;
      const p = new THREE.Vector3(Math.cos(a) * radius, 68 + rand() * 85, Math.sin(a) * radius);
      const s = new THREE.Vector3(16 + rand() * 28, 5 + rand() * 8, 12 + rand() * 20);
      q.setFromEuler(new THREE.Euler(rand() * 0.3, rand() * Math.PI, 0));
      m.compose(p, q, s);
      mesh.setMatrixAt(i, m);
      this.clouds.push({ p, s, q, speed: 0.5 + rand() * 0.7, phase: rand() * 10 });
    }
    mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    mesh.instanceMatrix.needsUpdate = true;
    mesh.frustumCulled = false;
    this.group.add(mesh);
    this.cloudMesh = mesh;
  }

  placeInstance(list, t, side, offset, extra = {}) {
    const f = this.track.getFrameAt(t);
    const lateral = side * offset;
    const y = this.track.bankHeight(t, offset);
    const pos = new THREE.Vector3(f.pos.x + f.left.x * lateral, y, f.pos.z + f.left.z * lateral);
    list.push({ t, pos, side, offset, ...extra });
  }

  buildJungle() {
    const rand = seededRandom(99123);
    const palms = [];
    const broad = [];
    const bushes = [];
    const rocks = [];
    const canes = [];

    const halfAt = (t) => this.track.getWidth(t) / 2;
    for (let i = 0; i < 270; i++) {
      const t = rand();
      const side = rand() < 0.5 ? -1 : 1;
      const off = halfAt(t) + 14 + rand() * 52;
      this.placeInstance(palms, t, side, off, {
        h: 5.5 + rand() * 7,
        lean: (rand() - 0.5) * 0.22,
        rot: rand() * Math.PI * 2,
        size: 0.82 + rand() * 0.5,
        shade: rand(),
      });
    }
    for (let i = 0; i < 185; i++) {
      const t = rand();
      const side = rand() < 0.5 ? -1 : 1;
      const off = halfAt(t) + 18 + rand() * 64;
      this.placeInstance(broad, t, side, off, {
        h: 4.5 + rand() * 6,
        rot: rand() * Math.PI * 2,
        size: 2.6 + rand() * 3.0,
        shade: rand(),
      });
    }
    for (let i = 0; i < 250; i++) {
      const t = rand();
      const side = rand() < 0.5 ? -1 : 1;
      const off = halfAt(t) + 8 + rand() * 60;
      this.placeInstance(bushes, t, side, off, {
        s: 0.6 + rand() * 1.75,
        rot: rand() * Math.PI * 2,
        shade: rand(),
      });
    }
    for (let i = 0; i < 120; i++) {
      const t = rand();
      const side = rand() < 0.5 ? -1 : 1;
      const off = halfAt(t) + 3 + rand() * 42;
      this.placeInstance(rocks, t, side, off, {
        s: 0.5 + rand() * 2.4,
        rot: rand() * Math.PI * 2,
        shade: rand(),
      });
    }
    // Bamboo thickets near the narrow jungle section.
    for (let i = 0; i < 100; i++) {
      const t = 0.16 + rand() * 0.17;
      const side = rand() < 0.5 ? -1 : 1;
      const off = halfAt(t) + 4 + rand() * 18;
      this.placeInstance(canes, t, side, off, {
        h: 4 + rand() * 7,
        rot: rand() * Math.PI * 2,
        lean: (rand() - 0.5) * 0.2,
      });
    }

    const trunkMat = new THREE.MeshLambertMaterial({ color: '#8c6a42', flatShading: true });
    const palmMat = new THREE.MeshLambertMaterial({ color: '#5a9c3f', flatShading: true, side: THREE.DoubleSide });
    const broadMat = new THREE.MeshLambertMaterial({ color: '#3d7b3b', flatShading: true });
    const bushMat = new THREE.MeshLambertMaterial({ color: '#3c7438', flatShading: true });
    const rockMat = new THREE.MeshLambertMaterial({ color: '#7f8b74', flatShading: true });
    const caneMat = new THREE.MeshLambertMaterial({ color: '#86a94d', flatShading: true });

    const m = new THREE.Matrix4();
    const q = new THREE.Quaternion();
    const v = new THREE.Vector3();
    const s = new THREE.Vector3();
    const up = new THREE.Vector3(0, 1, 0);
    const color = new THREE.Color();

    // Palm trunks + crowns.
    const palmTrunks = new THREE.InstancedMesh(trunkGeo, trunkMat, palms.length);
    const palmCrowns = new THREE.InstancedMesh(palmLeaves, palmMat, palms.length);
    palms.forEach((p, i) => {
      const leanQ = new THREE.Quaternion().setFromEuler(new THREE.Euler(p.lean, p.rot, p.lean * 0.5));
      q.copy(leanQ);
      v.copy(p.pos);
      s.set(1.1 * p.size, p.h, 1.1 * p.size);
      m.compose(v, q, s);
      palmTrunks.setMatrixAt(i, m);
      const top = new THREE.Vector3(0, p.h, 0).applyQuaternion(q).add(p.pos);
      q.setFromAxisAngle(up, p.rot);
      s.setScalar(0.65 * p.size + p.shade * 0.24);
      m.compose(top, q, s);
      palmCrowns.setMatrixAt(i, m);
      color.setHSL(0.24 + p.shade * 0.045, 0.42 + p.shade * 0.12, 0.3 + p.shade * 0.1);
      palmCrowns.setColorAt(i, color);
    });
    palmTrunks.instanceMatrix.needsUpdate = true;
    palmCrowns.instanceMatrix.needsUpdate = true;
    if (palmCrowns.instanceColor) palmCrowns.instanceColor.needsUpdate = true;
    this.group.add(palmTrunks, palmCrowns);

    const broadTrunks = new THREE.InstancedMesh(trunkGeo, trunkMat, broad.length);
    const broadCrowns = new THREE.InstancedMesh(broadCanopy, broadMat, broad.length);
    broad.forEach((p, i) => {
      q.setFromAxisAngle(up, p.rot);
      v.copy(p.pos);
      s.set(1.8 * p.size / 3, p.h, 1.8 * p.size / 3);
      m.compose(v, q, s);
      broadTrunks.setMatrixAt(i, m);
      const top = p.pos.clone().add(new THREE.Vector3(0, p.h * 0.94, 0));
      q.setFromEuler(new THREE.Euler(0, p.rot, (p.shade - 0.5) * 0.15));
      s.setScalar(p.size);
      m.compose(top, q, s);
      broadCrowns.setMatrixAt(i, m);
      color.setHSL(0.26 + p.shade * 0.04, 0.35 + p.shade * 0.13, 0.24 + p.shade * 0.1);
      broadCrowns.setColorAt(i, color);
    });
    broadTrunks.instanceMatrix.needsUpdate = true;
    broadCrowns.instanceMatrix.needsUpdate = true;
    if (broadCrowns.instanceColor) broadCrowns.instanceColor.needsUpdate = true;
    this.group.add(broadTrunks, broadCrowns);

    const bushMesh = new THREE.InstancedMesh(bushGeo, bushMat, bushes.length);
    bushes.forEach((p, i) => {
      q.setFromEuler(new THREE.Euler(0, p.rot, 0));
      v.set(p.pos.x, p.pos.y + p.s * 0.42, p.pos.z);
      s.set(p.s * 1.3, p.s * 0.65, p.s);
      m.compose(v, q, s);
      bushMesh.setMatrixAt(i, m);
      color.setHSL(0.27 + p.shade * 0.04, 0.32 + p.shade * 0.16, 0.25 + p.shade * 0.11);
      bushMesh.setColorAt(i, color);
    });
    bushMesh.instanceMatrix.needsUpdate = true;
    if (bushMesh.instanceColor) bushMesh.instanceColor.needsUpdate = true;
    this.group.add(bushMesh);

    const rockMesh = new THREE.InstancedMesh(rockGeo, rockMat, rocks.length);
    rocks.forEach((p, i) => {
      q.setFromEuler(new THREE.Euler(p.shade * 0.4, p.rot, p.shade * 0.3));
      v.set(p.pos.x, p.pos.y + p.s * 0.34, p.pos.z);
      s.set(p.s * 1.2, p.s * 0.8, p.s);
      m.compose(v, q, s);
      rockMesh.setMatrixAt(i, m);
      color.setHSL(0.24, 0.08, 0.36 + p.shade * 0.2);
      rockMesh.setColorAt(i, color);
    });
    rockMesh.instanceMatrix.needsUpdate = true;
    if (rockMesh.instanceColor) rockMesh.instanceColor.needsUpdate = true;
    this.group.add(rockMesh);

    const caneGeo = new THREE.CylinderGeometry(0.075, 0.1, 1, 5);
    caneGeo.translate(0, 0.5, 0);
    const caneMesh = new THREE.InstancedMesh(caneGeo, caneMat, canes.length);
    canes.forEach((p, i) => {
      q.setFromEuler(new THREE.Euler(p.lean, p.rot, p.lean * 0.4));
      v.copy(p.pos);
      s.set(1, p.h, 1);
      m.compose(v, q, s);
      caneMesh.setMatrixAt(i, m);
    });
    caneMesh.instanceMatrix.needsUpdate = true;
    this.group.add(caneMesh);

    this.vegetationMeshes = [palmTrunks, palmCrowns, broadTrunks, broadCrowns, bushMesh, rockMesh, caneMesh];
  }

  buildBanks() {
    // Lily pads and driftwood along the shallows.
    const rand = seededRandom(551);
    const pads = [];
    for (let i = 0; i < 90; i++) {
      const t = rand();
      const side = rand() < 0.5 ? -1 : 1;
      const half = this.track.getWidth(t) / 2;
      const lateral = side * (half - 1.4 - rand() * 2.6);
      const f = this.track.getFrameAt(t);
      pads.push({
        p: new THREE.Vector3(f.pos.x + f.left.x * lateral, 0.11, f.pos.z + f.left.z * lateral),
        s: 0.25 + rand() * 0.55,
        rot: rand() * Math.PI,
      });
    }
    const padGeo = new THREE.CircleGeometry(1, 9);
    padGeo.rotateX(-Math.PI / 2);
    const padMat = new THREE.MeshLambertMaterial({ color: '#4f8f43', side: THREE.DoubleSide });
    const mesh = new THREE.InstancedMesh(padGeo, padMat, pads.length);
    const m = new THREE.Matrix4();
    for (let i = 0; i < pads.length; i++) {
      const p = pads[i];
      m.compose(p.p, new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 1, 0), p.rot), new THREE.Vector3(p.s, 1, p.s));
      mesh.setMatrixAt(i, m);
    }
    mesh.instanceMatrix.needsUpdate = true;
    this.group.add(mesh);
  }

  buildStartArch() {
    const group = new THREE.Group();
    const f = this.track.getFrameAt(0);
    group.position.copy(f.pos);
    group.rotation.y = Math.atan2(f.tangent.x, f.tangent.z);
    const half = f.width / 2;
    const bamboo = new THREE.MeshLambertMaterial({ color: '#bea05c', flatShading: true });
    const darkBamboo = new THREE.MeshLambertMaterial({ color: '#7b6738', flatShading: true });
    const poleGeo = new THREE.CylinderGeometry(0.32, 0.42, 7.1, 6);
    for (const side of [-1, 1]) {
      const pole = new THREE.Mesh(poleGeo, bamboo);
      pole.position.set(side * (half + 1.8), 3.55, 0);
      pole.rotation.z = side * -0.03;
      group.add(pole);
      for (let k = 0; k < 3; k++) {
        const ring = new THREE.Mesh(new THREE.TorusGeometry(0.4, 0.055, 4, 8), darkBamboo);
        ring.rotation.x = Math.PI / 2;
        ring.position.set(side * (half + 1.8), 1.6 + k * 2, 0);
        group.add(ring);
      }
    }
    const crossbar = new THREE.Mesh(new THREE.CylinderGeometry(0.24, 0.24, f.width + 5.4, 6), bamboo);
    crossbar.rotation.z = Math.PI / 2;
    crossbar.position.y = 7.0;
    group.add(crossbar);

    const bannerMat = new THREE.MeshBasicMaterial({
      map: makeBannerTexture('RIVER RUSH', 'START  •  FINISH'),
      side: THREE.DoubleSide, transparent: true,
    });
    const banner = new THREE.Mesh(new THREE.PlaneGeometry(f.width + 1.8, 2.9), bannerMat);
    banner.position.set(0, 5.55, 0.08);
    banner.rotation.y = Math.PI;
    group.add(banner);
    const backBanner = banner.clone();
    backBanner.position.z = -0.04;
    group.add(backBanner);

    for (let i = 0; i < 3; i++) {
      const mat = new THREE.MeshBasicMaterial({ color: '#22352e' });
      const light = new THREE.Mesh(new THREE.SphereGeometry(0.22, 8, 6), mat);
      light.position.set((i - 1) * 2.2, 7.35, 0.3);
      group.add(light);
      this.startLightMats.push(mat);
    }

    // Flags on the top corners.
    const flagMat = new THREE.MeshBasicMaterial({ color: '#d8ff5d', side: THREE.DoubleSide });
    for (const side of [-1, 1]) {
      const flag = new THREE.Mesh(new THREE.PlaneGeometry(1.8, 0.9, 3, 1), flagMat);
      flag.position.set(side * (half + 1.8), 7.9, 0.1);
      flag.rotation.y = Math.PI / 2;
      group.add(flag);
    }
    this.group.add(group);
    this.startArch = group;
  }

  buildBridge() {
    const group = new THREE.Group();
    const t = 0.335;
    const f = this.track.getFrameAt(t);
    group.position.copy(f.pos);
    group.rotation.y = Math.atan2(f.tangent.x, f.tangent.z);
    const span = f.width + 22;
    const plankMat = new THREE.MeshLambertMaterial({ color: '#8c6238', flatShading: true });
    const darkWood = new THREE.MeshLambertMaterial({ color: '#5a3f27', flatShading: true });
    const rope = new THREE.MeshLambertMaterial({ color: '#b59a68', flatShading: true });

    const deck = new THREE.Mesh(new THREE.BoxGeometry(span, 0.24, 7.4), darkWood);
    deck.position.y = 6.1;
    group.add(deck);
    const plankCount = 34;
    for (let i = 0; i < plankCount; i++) {
      const x = -span / 2 + (i + 0.5) * (span / plankCount);
      const plank = new THREE.Mesh(new THREE.BoxGeometry(span / plankCount - 0.06, 0.12, 7.7), plankMat);
      plank.position.set(x, 6.25, 0);
      plank.rotation.y = (Math.random() - 0.5) * 0.025;
      group.add(plank);
    }
    for (const side of [-1, 1]) {
      const rail = new THREE.Mesh(new THREE.BoxGeometry(span, 0.18, 0.18), plankMat);
      rail.position.set(0, 7.5, side * 3.5);
      group.add(rail);
      const rail2 = rail.clone();
      rail2.position.y = 7.05;
      group.add(rail2);
      for (let i = 0; i < 9; i++) {
        const x = -span / 2 + i * (span / 8);
        const post = new THREE.Mesh(new THREE.CylinderGeometry(0.11, 0.13, 1.35, 5), darkWood);
        post.position.set(x, 6.85, side * 3.5);
        group.add(post);
      }
      for (const x of [-span / 2 + 5, 0, span / 2 - 5]) {
        const support = new THREE.Mesh(new THREE.CylinderGeometry(0.35, 0.5, 6.2, 6), darkWood);
        support.position.set(x, 3.1, side * 2.6);
        group.add(support);
        const brace = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.09, 4.6, 4), rope);
        brace.position.set(x, 5.0, side * 3.1);
        brace.rotation.z = 0.55 * (x < 0 ? -1 : 1);
        group.add(brace);
      }
    }
    // Hanging vines.
    for (let i = 0; i < 7; i++) {
      const x = -span / 2 + 4 + Math.random() * (span - 8);
      const len = 1 + Math.random() * 2.5;
      const vine = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, len, 4), new THREE.MeshLambertMaterial({ color: '#477a3b' }));
      vine.position.set(x, 6.1 - len / 2, (Math.random() < 0.5 ? -1 : 1) * (3.8 + Math.random() * 0.6));
      group.add(vine);
    }
    this.group.add(group);
    this.bridge = group;
  }

  buildVillage() {
    const hutSpots = [
      [0.365, -1, 22], [0.395, -1, 27], [0.425, -1, 23],
      [0.375, 1, 25], [0.415, 1, 28],
    ];
    for (const [t, side, offset] of hutSpots) {
      const f = this.track.getFrameAt(t);
      const y = this.track.bankHeight(t, f.width / 2 + offset);
      const group = new THREE.Group();
      group.position.set(
        f.pos.x + f.left.x * side * (f.width / 2 + offset),
        y,
        f.pos.z + f.left.z * side * (f.width / 2 + offset),
      );
      group.rotation.y = Math.atan2(f.left.x * side, f.left.z * side) + Math.PI / 2;
      const wood = new THREE.MeshLambertMaterial({ color: '#7f5c39', flatShading: true });
      const wall = new THREE.MeshLambertMaterial({ color: '#b28b5f', flatShading: true });
      const roof = new THREE.MeshLambertMaterial({ color: '#c29c5a', flatShading: true });
      for (const [sx, sz] of [[-1.7, -1.4], [1.7, -1.4], [-1.7, 1.4], [1.7, 1.4]]) {
        const stilt = new THREE.Mesh(new THREE.CylinderGeometry(0.16, 0.2, 2.2, 5), wood);
        stilt.position.set(sx, 1.1, sz);
        group.add(stilt);
      }
      const platform = new THREE.Mesh(new THREE.BoxGeometry(5.2, 0.28, 4.6), wood);
      platform.position.y = 2.2;
      group.add(platform);
      const walls = new THREE.Mesh(hutBaseGeo, wall);
      walls.position.y = 3.45;
      group.add(walls);
      const roofMesh = new THREE.Mesh(hutRoofGeo, roof);
      roofMesh.position.y = 5.9;
      roofMesh.rotation.y = Math.PI / 4;
      group.add(roofMesh);
      const door = new THREE.Mesh(new THREE.BoxGeometry(0.9, 1.5, 0.06), new THREE.MeshLambertMaterial({ color: '#3f2a1d' }));
      door.position.set(0, 3.15, 1.93);
      group.add(door);
      const windowGlow = new THREE.Mesh(
        new THREE.PlaneGeometry(0.6, 0.5),
        new THREE.MeshBasicMaterial({ color: '#ffd98a' }),
      );
      windowGlow.position.set(1.35, 3.65, 1.94);
      group.add(windowGlow);
      // Dock reaching toward the river.
      const dock = new THREE.Mesh(new THREE.BoxGeometry(2.1, 0.16, 9), wood);
      dock.position.set(0, 1.0, -6.8);
      group.add(dock);
      for (let i = 0; i < 3; i++) {
        const post = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.14, 2.4, 5), wood);
        post.position.set(-0.8, 0.4, -3.5 - i * 3);
        group.add(post);
      }
      const lantern = new THREE.Mesh(new THREE.SphereGeometry(0.18, 7, 5), new THREE.MeshBasicMaterial({ color: '#ffca6b' }));
      lantern.position.set(-0.6, 2.8, 2.25);
      group.add(lantern);
      const lanternGlow = new THREE.Sprite(new THREE.SpriteMaterial({
        map: makeGlowTexture(64), color: '#ffbe5c', transparent: true,
        blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0.55,
      }));
      lanternGlow.position.copy(lantern.position);
      lanternGlow.scale.setScalar(1.4);
      group.add(lanternGlow);
      this.group.add(group);
    }
  }

  buildWaterfall() {
    const t = 0.525;
    const f = this.track.getFrameAt(t);
    const side = -1;
    const off = f.width / 2 + 30;
    const base = new THREE.Vector3(
      f.pos.x + f.left.x * side * off,
      this.track.bankHeight(t, off),
      f.pos.z + f.left.z * side * off,
    );
    const g = new THREE.Group();
    g.position.copy(base);
    g.rotation.y = Math.atan2(-f.left.x * side, -f.left.z * side);
    const rockMat = new THREE.MeshLambertMaterial({ color: '#6f7c67', flatShading: true });
    const rand = seededRandom(303);
    for (let i = 0; i < 9; i++) {
      const r = new THREE.Mesh(rockGeo, rockMat);
      r.scale.set(2 + rand() * 4, 2 + rand() * 7, 2 + rand() * 4);
      r.position.set((rand() - 0.5) * 14, rand() * 8 - 1, (rand() - 0.5) * 8);
      r.rotation.set(rand() * 2, rand() * 3, rand() * 2);
      g.add(r);
    }
    this.fallMat = new THREE.ShaderMaterial({
      vertexShader: fallVert,
      fragmentShader: fallFrag,
      transparent: true,
      depthWrite: false,
      side: THREE.DoubleSide,
      uniforms: {
        uTime: { value: 0 },
        uColor: { value: new THREE.Color('#d9f4e6') },
      },
    });
    const fall = new THREE.Mesh(new THREE.PlaneGeometry(7.5, 13.5), this.fallMat);
    fall.position.set(0.5, 8.6, 3.4);
    g.add(fall);
    const fallBack = new THREE.Mesh(new THREE.PlaneGeometry(5.8, 12.4), this.fallMat);
    fallBack.position.set(0.2, 8.2, 4.1);
    g.add(fallBack);
    // Base foam.
    for (let i = 0; i < 5; i++) {
      const sprite = new THREE.Sprite(new THREE.SpriteMaterial({
        map: makeGlowTexture(128), color: '#edfbef', transparent: true,
        blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0.34,
      }));
      sprite.position.set((rand() - 0.5) * 10, 0.5 + rand() * 2, 3 + rand() * 3);
      sprite.scale.setScalar(4 + rand() * 5);
      g.add(sprite);
      this.mist.push({ sprite, phase: rand() * 6, base: sprite.scale.x, y: sprite.position.y });
    }
    this.group.add(g);
    this.waterfall = g;
  }

  buildBirds() {
    const birdMat = new THREE.MeshBasicMaterial({ color: '#315b5b', side: THREE.DoubleSide, transparent: true, opacity: 0.55 });
    for (let i = 0; i < 8; i++) {
      const g = new THREE.Group();
      for (const side of [-1, 1]) {
        const wing = new THREE.Mesh(new THREE.PlaneGeometry(1.4, 0.22), birdMat);
        wing.position.x = side * 0.7;
        wing.rotation.z = side * 0.22;
        g.add(wing);
      }
      const angle = Math.random() * Math.PI * 2;
      const radius = 90 + Math.random() * 170;
      g.position.set(Math.cos(angle) * radius, 42 + Math.random() * 35, Math.sin(angle) * radius);
      this.group.add(g);
      this.birds.push({ g, angle, radius, speed: 0.03 + Math.random() * 0.05, y: g.position.y, flap: Math.random() * 10 });
    }
  }

  applyPalette(name) {
    const p = PALETTES[name] || PALETTES.morning;
    this.palette = p;
    const u = this.skyMat.uniforms;
    u.uTop.value.set(p.skyTop);
    u.uMid.value.set(p.skyMid);
    u.uHorizon.value.set(p.horizon);
    u.uSun.value.set(p.sun);
    u.uSunDir.value.set(...p.sunPos).normalize();
    this.sunSprite.material.color.set(p.sun);
    this.sunSprite.position.copy(u.uSunDir.value).multiplyScalar(900);
    this.sunSprite.scale.setScalar(name === 'sunset' ? 280 : 210);
    this.sun.color.set(p.light);
    this.sun.intensity = p.lightIntensity;
    this.sun.position.copy(u.uSunDir.value).multiplyScalar(120);
    this.hemi.color.set(p.hemiSky);
    this.hemi.groundColor.set(p.hemiGround);
    this.hemi.intensity = p.ambience + 0.35;
    this.fill.color.set(p.skyMid);
    this.fill.intensity = 0.3;
    if (this.scene.fog) this.scene.fog.color.set(p.fog);
    if (this.mountainMaterials[0]) this.mountainMaterials[0].color.set(name === 'storm' ? '#436057' : name === 'sunset' ? '#6c7a64' : '#4b7c63');
    if (this.cloudMesh) this.cloudMesh.material.color.set(name === 'storm' ? '#cdd8ce' : '#fffaf0');
    this.scene.background = null;
  }

  setStartLights(n) {
    this.startLightMats.forEach((m, i) => {
      m.color.set(i < n ? '#d8ff5d' : '#22352e');
    });
  }

  update(time, dt) {
    this.time = time;
    if (this.fallMat) this.fallMat.uniforms.uTime.value = time;
    // Clouds drift lazily around the valley.
    if (this.cloudMesh) {
      const m = new THREE.Matrix4();
      const q = this.clouds[0]?.q || new THREE.Quaternion();
      for (let i = 0; i < this.clouds.length; i++) {
        const c = this.clouds[i];
        const angle = Math.atan2(c.p.z, c.p.x) + dt * 0.0008 * c.speed;
        const radius = Math.hypot(c.p.x, c.p.z);
        c.p.x = Math.cos(angle) * radius;
        c.p.z = Math.sin(angle) * radius;
        c.p.y += Math.sin(time * 0.12 + c.phase) * dt * 0.03;
        m.compose(c.p, c.q, c.s);
        this.cloudMesh.setMatrixAt(i, m);
      }
      this.cloudMesh.instanceMatrix.needsUpdate = true;
    }
    for (const m of this.mist) {
      const pulse = 1 + Math.sin(time * 1.3 + m.phase) * 0.1;
      m.sprite.scale.setScalar(m.base * pulse);
      m.sprite.position.y = m.y + Math.sin(time * 0.7 + m.phase) * 0.3;
    }
    for (const b of this.birds) {
      b.angle += dt * b.speed;
      b.g.position.set(Math.cos(b.angle) * b.radius, b.y + Math.sin(time * 0.35 + b.flap) * 2, Math.sin(b.angle) * b.radius);
      b.g.rotation.y = -b.angle + Math.PI / 2;
      const flap = Math.sin(time * 7 + b.flap);
      b.g.children.forEach((wing, i) => {
        wing.rotation.z = (i === 0 ? -1 : 1) * (0.22 + flap * 0.25);
      });
    }
  }
}

import * as THREE from 'three';
import { makeGlowTexture, makeLabelTexture, seededRandom } from '../core/utils.js';
import { waveHeight } from './Track.js';

const glow = typeof document !== 'undefined' ? makeGlowTexture(96) : null;

const ROCK_SPOTS = [
  [0.062, -7.5, 1.7], [0.116, 7.8, 2.0], [0.235, -5.5, 1.5], [0.322, 9.2, 1.8],
  [0.438, -8.2, 2.1], [0.548, 6.4, 1.6], [0.648, -7.4, 1.9], [0.782, 8.4, 1.8],
  [0.894, -6.2, 1.6], [0.952, 5.2, 1.4],
];
const LOG_SPOTS = [
  [0.095, 1.5, 0.2], [0.286, -1.8, -0.3], [0.487, 2.4, 0.5], [0.73, -2.0, -0.1], [0.856, 7.0, 0.4],
];
const WHIRL_SPOTS = [
  [0.205, 5.0], [0.596, -4.0], [0.812, 2.0],
];
const PICKUP_SPOTS = [
  [0.045, 0, 'nitro'], [0.085, -4, 'coin'], [0.105, 4, 'coin'], [0.152, 3, 'shield'],
  [0.184, -5, 'coin'], [0.258, 0, 'nitro'], [0.305, -6, 'coin'], [0.352, 5, 'coin'],
  [0.402, -3, 'shield'], [0.46, 4, 'nitro'], [0.515, -2, 'coin'], [0.575, 5, 'coin'],
  [0.622, -5, 'shield'], [0.685, 2, 'nitro'], [0.745, -4, 'coin'], [0.795, 4, 'coin'],
  [0.848, 0, 'nitro'], [0.915, -4, 'shield'], [0.946, 4, 'coin'],
];

function canvasChecker() {
  const c = document.createElement('canvas');
  c.width = 512;
  c.height = 128;
  const ctx = c.getContext('2d');
  const cell = 32;
  for (let y = 0; y < 4; y++) {
    for (let x = 0; x < 16; x++) {
      ctx.fillStyle = (x + y) % 2 ? 'rgba(9,40,34,.55)' : 'rgba(245,252,235,.9)';
      ctx.fillRect(x * cell, y * cell, cell, cell);
    }
  }
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.wrapS = THREE.RepeatWrapping;
  tex.repeat.set(4, 1);
  return tex;
}

export class RaceObjects {
  constructor(scene, track) {
    this.scene = scene;
    this.track = track;
    this.group = new THREE.Group();
    this.scene.add(this.group);
    this.obstacles = [];
    this.pickups = [];
    this.ramps = [];
    this.whirls = [];
    this.flags = [];
    this.rand = seededRandom(613);
    this.checkerTex = canvasChecker();
    this.buildCheckpoints();
    this.buildStartLine();
    this.buildObstacles();
    this.buildPickups();
    this.buildRamps();
    this.buildBuoys();
  }

  buildCheckpoints() {
    const bambooMat = new THREE.MeshLambertMaterial({ color: '#b79a55', flatShading: true });
    const flagMats = [
      new THREE.MeshBasicMaterial({ color: '#ff8a3d', side: THREE.DoubleSide }),
      new THREE.MeshBasicMaterial({ color: '#d8ff5d', side: THREE.DoubleSide }),
      new THREE.MeshBasicMaterial({ color: '#7af3d5', side: THREE.DoubleSide }),
    ];
    for (let i = 0; i < this.track.gateCount; i++) {
      const t = this.track.gateFractions[i];
      const f = this.track.getFrameAt(t);
      const group = new THREE.Group();
      group.position.copy(f.pos);
      group.rotation.y = Math.atan2(f.tangent.x, f.tangent.z);
      const half = f.width / 2;
      for (const side of [-1, 1]) {
        const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.16, 0.24, 4.4, 5), bambooMat);
        pole.position.set(side * (half + 0.7), 2.0, 0);
        group.add(pole);
        const flag = new THREE.Mesh(new THREE.PlaneGeometry(1.5, 0.85, 3, 1), flagMats[i % flagMats.length]);
        flag.position.set(side * (half + 0.7) + side * 0.78, 3.85, 0);
        flag.rotation.y = Math.PI / 2;
        group.add(flag);
        this.flags.push({ mesh: flag, phase: i * 1.1 + (side > 0 ? 0.5 : 0), side });
        const buoy = new THREE.Mesh(
          new THREE.SphereGeometry(0.38, 8, 6),
          new THREE.MeshLambertMaterial({ color: i === this.track.gateCount - 1 ? '#d8ff5d' : '#ff8a3d' }),
        );
        buoy.position.set(side * (half - 1.3), 0.25, 0);
        group.add(buoy);
      }
      const number = new THREE.Sprite(new THREE.SpriteMaterial({
        map: makeLabelTexture(String(i + 1), 'rgba(7,40,35,.82)', '#d8ff5d', 160),
        transparent: true, depthWrite: false,
      }));
      number.position.set(0, 5.4, 0);
      number.scale.setScalar(1.15);
      group.add(number);
      this.group.add(group);
    }
  }

  buildStartLine() {
    const f = this.track.getFrameAt(0);
    const geo = new THREE.PlaneGeometry(f.width + 1, 3.4);
    const mat = new THREE.MeshBasicMaterial({
      map: this.checkerTex, transparent: true, depthWrite: false, opacity: 0.92,
      side: THREE.DoubleSide,
    });
    const line = new THREE.Mesh(geo, mat);
    line.rotation.x = -Math.PI / 2;
    line.rotation.z = -Math.atan2(f.tangent.x, f.tangent.z);
    line.position.set(f.pos.x, 0.14, f.pos.z);
    line.renderOrder = 3;
    this.group.add(line);
  }

  buildObstacles() {
    const rockMat = new THREE.MeshStandardMaterial({ color: '#7d8875', roughness: 0.93, flatShading: true });
    const mossMat = new THREE.MeshLambertMaterial({ color: '#4a7e3d', flatShading: true });
    const logMat = new THREE.MeshStandardMaterial({ color: '#6b4b2c', roughness: 0.9, flatShading: true });
    const darkLog = new THREE.MeshLambertMaterial({ color: '#4b331e', flatShading: true });

    for (const [t, lat, scale] of ROCK_SPOTS) {
      const f = this.track.getFrameAt(t);
      const pos = f.pos.clone().addScaledVector(f.left, lat);
      const group = new THREE.Group();
      group.position.copy(pos);
      const rock = new THREE.Mesh(new THREE.DodecahedronGeometry(1, 0), rockMat);
      rock.scale.set(scale * 1.15, scale * 0.82, scale * 1.05);
      rock.position.y = scale * 0.16;
      rock.rotation.set(this.rand() * 2, this.rand() * 3, this.rand() * 2);
      group.add(rock);
      const moss = new THREE.Mesh(new THREE.IcosahedronGeometry(1, 0), mossMat);
      moss.scale.set(scale * 0.66, scale * 0.25, scale * 0.58);
      moss.position.set(scale * 0.1, scale * 0.55, -scale * 0.1);
      group.add(moss);
      const foam = new THREE.Mesh(
        new THREE.RingGeometry(scale * 0.9, scale * 1.55, 18),
        new THREE.MeshBasicMaterial({ color: '#eaffdf', transparent: true, opacity: 0.25, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide }),
      );
      foam.rotation.x = -Math.PI / 2;
      foam.position.y = 0.06;
      group.add(foam);
      this.group.add(group);
      this.obstacles.push({
        type: 'rock', group, position: pos.clone(), t, lat, radius: scale * 1.25 + 0.5,
        baseY: 0, hit: false,
      });
    }

    for (const [t, lat, rot] of LOG_SPOTS) {
      const f = this.track.getFrameAt(t);
      const pos = f.pos.clone().addScaledVector(f.left, lat);
      const group = new THREE.Group();
      group.position.copy(pos);
      group.rotation.y = Math.atan2(f.tangent.x, f.tangent.z) + rot;
      const log = new THREE.Mesh(new THREE.CylinderGeometry(0.55, 0.62, 6.2, 7), logMat);
      log.rotation.z = Math.PI / 2;
      log.position.y = 0.36;
      group.add(log);
      for (let i = 0; i < 3; i++) {
        const branch = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.14, 1.7, 5), darkLog);
        branch.position.set(-2.2 + i * 2.1, 0.68, (i % 2 ? 0.55 : -0.5));
        branch.rotation.z = Math.PI / 2 + (i - 1) * 0.45;
        branch.rotation.y = i * 0.8;
        group.add(branch);
      }
      // Root tangle on one end.
      const root = new THREE.Mesh(new THREE.IcosahedronGeometry(0.85, 0), darkLog);
      root.scale.set(1.2, 0.8, 1.4);
      root.position.set(3.1, 0.5, 0.2);
      group.add(root);
      this.group.add(group);
      this.obstacles.push({
        type: 'log', group, position: pos.clone(), t, lat, radius: 3.6, baseY: 0, hit: false, phase: this.rand() * 6,
      });
    }

    const whirlMat = new THREE.MeshBasicMaterial({
      color: '#183e38', transparent: true, opacity: 0.52, side: THREE.DoubleSide, depthWrite: false,
    });
    const ringMat = new THREE.MeshBasicMaterial({
      color: '#c7f5e4', transparent: true, opacity: 0.34, side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending, depthWrite: false,
    });
    for (const [t, lat] of WHIRL_SPOTS) {
      const f = this.track.getFrameAt(t);
      const pos = f.pos.clone().addScaledVector(f.left, lat);
      const group = new THREE.Group();
      group.position.copy(pos);
      const disc = new THREE.Mesh(new THREE.CircleGeometry(3.5, 24), whirlMat);
      disc.rotation.x = -Math.PI / 2;
      disc.position.y = 0.08;
      group.add(disc);
      const rings = [];
      for (let i = 0; i < 3; i++) {
        const ring = new THREE.Mesh(new THREE.RingGeometry(1.4 + i * 0.85, 1.6 + i * 0.85, 24), ringMat);
        ring.rotation.x = -Math.PI / 2;
        ring.position.y = 0.1 + i * 0.02;
        group.add(ring);
        rings.push({ mesh: ring, speed: 0.5 + i * 0.25 });
      }
      const foamSprite = new THREE.Sprite(new THREE.SpriteMaterial({
        map: glow, color: '#d9fff3', transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0.25,
      }));
      foamSprite.scale.setScalar(7);
      foamSprite.position.y = 0.4;
      group.add(foamSprite);
      this.group.add(group);
      this.whirls.push({ group, rings, speed: 1.2, phase: this.rand() * 5 });
      this.obstacles.push({
        type: 'whirlpool', group, position: pos.clone(), t, lat, radius: 3.9, baseY: 0, hit: false,
      });
    }
  }

  buildPickups() {
    const nitroMat = new THREE.MeshStandardMaterial({ color: '#5fe9ff', emissive: '#1b9ab5', emissiveIntensity: 0.8, roughness: 0.25 });
    const shieldMat = new THREE.MeshStandardMaterial({ color: '#ffd356', emissive: '#b07c0a', emissiveIntensity: 0.65, roughness: 0.3 });
    const coinMat = new THREE.MeshStandardMaterial({ color: '#ffcf4d', emissive: '#a06b05', emissiveIntensity: 0.55, roughness: 0.22, metalness: 0.65 });
    const whiteMat = new THREE.MeshStandardMaterial({ color: '#f4fff8', roughness: 0.35 });
    const coinGeo = new THREE.CylinderGeometry(0.62, 0.62, 0.12, 18);
    coinGeo.rotateX(Math.PI / 2);
    const coinRim = new THREE.TorusGeometry(0.52, 0.06, 6, 18);
    const capsule = new THREE.CapsuleGeometry(0.22, 0.45, 4, 8);

    for (const [t, lat, type] of PICKUP_SPOTS) {
      const f = this.track.getFrameAt(t);
      const pos = f.pos.clone().addScaledVector(f.left, lat);
      const group = new THREE.Group();
      group.position.copy(pos);
      const spin = new THREE.Group();
      group.add(spin);
      let color = '#7af3d5';
      if (type === 'nitro') {
        const bottle = new THREE.Mesh(capsule, nitroMat);
        bottle.position.y = 0.05;
        spin.add(bottle);
        const cap = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.16, 0.18, 7), whiteMat);
        cap.position.y = 0.44;
        spin.add(cap);
        color = '#5fe9ff';
      } else if (type === 'shield') {
        const s = new THREE.Mesh(new THREE.IcosahedronGeometry(0.62, 1), shieldMat);
        spin.add(s);
        const wire = new THREE.Mesh(
          new THREE.IcosahedronGeometry(0.68, 1),
          new THREE.MeshBasicMaterial({ color: '#ffe7a1', wireframe: true, transparent: true, opacity: 0.35 }),
        );
        spin.add(wire);
        color = '#ffd356';
      } else {
        const coin = new THREE.Mesh(coinGeo, coinMat);
        spin.add(coin);
        const rim = new THREE.Mesh(coinRim, coinMat);
        rim.position.z = 0;
        spin.add(rim);
        color = '#ffd94f';
      }
      const halo = new THREE.Sprite(new THREE.SpriteMaterial({
        map: glow, color, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0.7,
      }));
      halo.scale.setScalar(type === 'coin' ? 2.2 : 2.7);
      halo.position.y = 0.05;
      group.add(halo);
      this.group.add(group);
      this.pickups.push({
        type, group, spin, halo, position: pos.clone(), t, lat, active: true, cooldown: 0, baseY: 1.25,
      });
    }
  }

  buildRamps() {
    const plankMat = new THREE.MeshLambertMaterial({ color: '#a37643', flatShading: true });
    const darkMat = new THREE.MeshLambertMaterial({ color: '#644426', flatShading: true });
    const stripeMat = new THREE.MeshBasicMaterial({ color: '#d8ff5d' });
    const warnMat = new THREE.MeshBasicMaterial({ color: '#ff7a48' });
    for (const t of this.track.rampTs) {
      const f = this.track.getFrameAt(t);
      const group = new THREE.Group();
      group.position.copy(f.pos);
      group.rotation.y = Math.atan2(f.tangent.x, f.tangent.z);
      const deck = new THREE.Mesh(new THREE.BoxGeometry(10, 0.32, 12), plankMat);
      deck.position.set(0, 0.78, 0);
      deck.rotation.x = -0.23;
      group.add(deck);
      const back = new THREE.Mesh(new THREE.BoxGeometry(10.4, 0.24, 3.2), darkMat);
      back.position.set(0, 0.32, -5.4);
      back.rotation.x = -0.23;
      group.add(back);
      for (const side of [-1, 1]) {
        const rail = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.7, 12), darkMat);
        rail.position.set(side * 4.9, 1.25, 0);
        rail.rotation.x = -0.23;
        group.add(rail);
        const flagPole = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.08, 3.4, 5), darkMat);
        flagPole.position.set(side * 4.6, 1.9, 4.6);
        group.add(flagPole);
        const flag = new THREE.Mesh(new THREE.PlaneGeometry(1.1, 0.6), stripeMat);
        flag.position.set(side * 5.2, 3.2, 4.6);
        flag.rotation.y = Math.PI / 2;
        group.add(flag);
      }
      for (let i = 0; i < 5; i++) {
        const stripe = new THREE.Mesh(new THREE.BoxGeometry(9.6, 0.035, 0.34), i % 2 ? warnMat : stripeMat);
        stripe.position.set(0, 0.96 + 0.03, -4.2 + i * 1.8);
        stripe.rotation.x = -0.23;
        group.add(stripe);
      }
      this.group.add(group);
      this.ramps.push({ t, group, lateral: 0, halfWidth: 5.4, length: 12 });
    }
  }

  buildBuoys() {
    const count = 46;
    const geo = new THREE.SphereGeometry(0.32, 7, 5);
    geo.scale(1, 1.35, 1);
    const mat = new THREE.MeshStandardMaterial({ roughness: 0.45, metalness: 0.05 });
    const mesh = new THREE.InstancedMesh(geo, mat, count * 2);
    const m = new THREE.Matrix4();
    const c = new THREE.Color();
    let idx = 0;
    for (let i = 0; i < count; i++) {
      const t = i / count;
      const f = this.track.getFrameAt(t);
      for (const side of [-1, 1]) {
        const lat = side * (f.width / 2 - 1.1);
        const p = f.pos.clone().addScaledVector(f.left, lat);
        p.y = waveHeight(p.x, p.z, 0) + 0.16;
        m.compose(p, new THREE.Quaternion(), new THREE.Vector3(1, 1, 1));
        mesh.setMatrixAt(idx, m);
        c.set(i % 2 ? '#ff8a3d' : '#d8ff5d');
        mesh.setColorAt(idx, c);
        idx++;
      }
    }
    mesh.instanceMatrix.needsUpdate = true;
    if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
    this.group.add(mesh);
    this.buoys = mesh;
  }

  reset() {
    for (const p of this.pickups) {
      p.active = true;
      p.cooldown = 0;
      p.group.visible = true;
    }
    for (const o of this.obstacles) o.hit = false;
  }

  update(dt, time) {
    for (const p of this.pickups) {
      if (!p.active) {
        p.cooldown -= dt;
        if (p.cooldown <= 0) {
          p.active = true;
          p.group.visible = true;
        }
        continue;
      }
      const y = waveHeight(p.position.x, p.position.z, time) + p.baseY + Math.sin(time * 2.2 + p.t * 17) * 0.16;
      p.group.position.set(p.position.x, y, p.position.z);
      p.spin.rotation.y += dt * 1.6;
      p.spin.rotation.x = Math.sin(time * 1.2 + p.t * 9) * 0.12;
      p.halo.material.opacity = 0.55 + Math.sin(time * 3 + p.t * 20) * 0.15;
    }
    for (const o of this.obstacles) {
      if (o.type === 'log') {
        o.group.position.y = Math.sin(time * 1.25 + o.phase) * 0.12;
        o.group.rotation.z = Math.sin(time * 1.05 + o.phase) * 0.035;
      } else if (o.type === 'rock') {
        o.group.position.y = Math.sin(time * 0.9 + o.t * 30) * 0.05;
      }
    }
    for (const w of this.whirls) {
      w.group.rotation.y += dt * w.speed;
      w.rings.forEach((r, i) => {
        r.mesh.scale.setScalar(1 + Math.sin(time * 1.7 + i + w.phase) * 0.06);
      });
    }
    for (const f of this.flags) {
      f.mesh.rotation.z = Math.sin(time * 4 + f.phase) * 0.12;
    }
  }

  collect(position, radius = 2.3) {
    for (const p of this.pickups) {
      if (!p.active) continue;
      const dx = position.x - p.position.x;
      const dz = position.z - p.position.z;
      if (dx * dx + dz * dz < radius * radius) {
        p.active = false;
        p.cooldown = 13;
        p.group.visible = false;
        return p;
      }
    }
    return null;
  }

  collide(position, airborne = false) {
    for (const o of this.obstacles) {
      if (o.type === 'rock' && airborne) continue;
      const dx = position.x - o.position.x;
      const dz = position.z - o.position.z;
      const r = o.radius + 0.8;
      if (dx * dx + dz * dz < r * r) return o;
    }
    return null;
  }

  rampAt(t, lateral) {
    for (const r of this.ramps) {
      const diff = Math.abs(((t - r.t + 1.5) % 1) - 0.5);
      if (diff < 0.008 && Math.abs(lateral) < r.halfWidth) return r;
    }
    return null;
  }
}

import * as THREE from 'three';

const vert = /* glsl */`
  attribute float aSize;
  attribute float aAlpha;
  attribute vec3 aColor;
  uniform float uScale;
  varying vec3 vColor;
  varying float vAlpha;
  void main() {
    vColor = aColor;
    vAlpha = aAlpha;
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    gl_Position = projectionMatrix * mv;
    gl_PointSize = clamp(aSize * uScale / max(1.0, -mv.z), 1.0, 90.0);
  }
`;

const frag = /* glsl */`
  varying vec3 vColor;
  varying float vAlpha;
  void main() {
    vec2 p = gl_PointCoord - 0.5;
    float d = length(p);
    if (d > 0.5) discard;
    float soft = smoothstep(0.5, 0.12, d);
    gl_FragColor = vec4(vColor, vAlpha * soft);
  }
`;

class ParticlePool {
  constructor(scene, capacity, blending) {
    this.capacity = capacity;
    this.scene = scene;
    this.cursor = 0;
    const geo = new THREE.BufferGeometry();
    this.pos = new Float32Array(capacity * 3);
    this.col = new Float32Array(capacity * 3);
    this.size = new Float32Array(capacity);
    this.alpha = new Float32Array(capacity);
    this.vel = new Float32Array(capacity * 3);
    this.life = new Float32Array(capacity);
    this.maxLife = new Float32Array(capacity);
    this.gravity = new Float32Array(capacity);
    this.drag = new Float32Array(capacity);
    this.grow = new Float32Array(capacity);
    this.baseAlpha = new Float32Array(capacity);
    this.baseSize = new Float32Array(capacity);
    for (let i = 0; i < capacity; i++) this.alpha[i] = 0;
    geo.setAttribute('position', new THREE.BufferAttribute(this.pos, 3).setUsage(THREE.DynamicDrawUsage));
    geo.setAttribute('aColor', new THREE.BufferAttribute(this.col, 3).setUsage(THREE.DynamicDrawUsage));
    geo.setAttribute('aSize', new THREE.BufferAttribute(this.size, 1).setUsage(THREE.DynamicDrawUsage));
    geo.setAttribute('aAlpha', new THREE.BufferAttribute(this.alpha, 1).setUsage(THREE.DynamicDrawUsage));
    this.geometry = geo;
    this.material = new THREE.ShaderMaterial({
      vertexShader: vert,
      fragmentShader: frag,
      transparent: true,
      depthWrite: false,
      blending,
      uniforms: { uScale: { value: 110 } },
    });
    this.points = new THREE.Points(geo, this.material);
    this.points.frustumCulled = false;
    this.points.renderOrder = 4;
    scene.add(this.points);
  }

  spawn(x, y, z, vx, vy, vz, color, size, life, gravity = 0, drag = 0.6, grow = 0.4, baseAlpha = 0.8) {
    const i = this.cursor;
    this.cursor = (this.cursor + 1) % this.capacity;
    const i3 = i * 3;
    this.pos[i3] = x; this.pos[i3 + 1] = y; this.pos[i3 + 2] = z;
    this.vel[i3] = vx; this.vel[i3 + 1] = vy; this.vel[i3 + 2] = vz;
    this.col[i3] = color.r; this.col[i3 + 1] = color.g; this.col[i3 + 2] = color.b;
    this.size[i] = size;
    this.baseSize[i] = size;
    this.alpha[i] = baseAlpha;
    this.baseAlpha[i] = baseAlpha;
    this.life[i] = life;
    this.maxLife[i] = life;
    this.gravity[i] = gravity;
    this.drag[i] = drag;
    this.grow[i] = grow;
  }

  update(dt) {
    for (let i = 0; i < this.capacity; i++) {
      if (this.life[i] <= 0) {
        if (this.alpha[i] !== 0) this.alpha[i] = 0;
        continue;
      }
      this.life[i] -= dt;
      const i3 = i * 3;
      const k = Math.max(0, this.life[i] / this.maxLife[i]);
      this.alpha[i] = k * this.baseAlpha[i];
      const dragK = Math.exp(-this.drag[i] * dt);
      this.vel[i3] *= dragK;
      this.vel[i3 + 2] *= dragK;
      this.vel[i3 + 1] = this.vel[i3 + 1] * dragK - this.gravity[i] * dt;
      this.pos[i3] += this.vel[i3] * dt;
      this.pos[i3 + 1] += this.vel[i3 + 1] * dt;
      this.pos[i3 + 2] += this.vel[i3 + 2] * dt;
      this.size[i] = this.baseSize[i] * (1 + (1 - k) * this.grow[i]);
      if (this.life[i] <= 0) this.alpha[i] = 0;
    }
    this.geometry.attributes.position.needsUpdate = true;
    this.geometry.attributes.aColor.needsUpdate = true;
    this.geometry.attributes.aSize.needsUpdate = true;
    this.geometry.attributes.aAlpha.needsUpdate = true;
  }
}

const TMP = new THREE.Vector3();
const FORWARD = new THREE.Vector3();

export class Effects {
  constructor(scene) {
    this.scene = scene;
    this.foam = new ParticlePool(scene, 420, THREE.NormalBlending);
    this.spark = new ParticlePool(scene, 340, THREE.AdditiveBlending);
    this.colors = {
      foam: new THREE.Color('#e7f8e3'),
      foamDeep: new THREE.Color('#b7ddc9'),
      spark: new THREE.Color('#ffcf5e'),
      sparkHot: new THREE.Color('#ff7a48'),
      nitro: new THREE.Color('#6ffbe8'),
      shield: new THREE.Color('#ffd356'),
      coin: new THREE.Color('#ffd94f'),
      blue: new THREE.Color('#65cfff'),
    };
    this.trailTimer = 0;
    this.aiTimer = 0;
  }

  emitWake(x, y, z, yaw, speed, width = 1) {
    FORWARD.set(Math.sin(yaw), 0, Math.cos(yaw));
    const right = TMP.set(FORWARD.z, 0, -FORWARD.x);
    const sx = x - FORWARD.x * 1.45;
    const sz = z - FORWARD.z * 1.45;
    const strength = Math.min(1, speed / 28);
    for (const side of [-1, 1]) {
      const px = sx + right.x * side * 0.52;
      const pz = sz + right.z * side * 0.52;
      this.foam.spawn(
        px, y + 0.1, pz,
        (Math.random() - 0.5) * 1.2 + right.x * side * (0.5 + strength),
        0.4 + Math.random() * 0.8,
        (Math.random() - 0.5) * 1.2 + right.z * side * (0.5 + strength),
        this.colors.foam,
        (0.5 + Math.random() * 0.7) * width,
        0.55 + Math.random() * 0.45,
        0.3, 1.2, 2.4, 0.36 + strength * 0.2,
      );
    }
    if (speed > 8) {
      const count = 1 + Math.floor(strength * 3);
      for (let i = 0; i < count; i++) {
        const side = Math.random() < 0.5 ? -1 : 1;
        this.foam.spawn(
          sx + right.x * side * 0.7, y + 0.2, sz + right.z * side * 0.7,
          right.x * side * (1.2 + Math.random() * 2.2) - FORWARD.x * 1.5,
          1.5 + Math.random() * 2.2,
          right.z * side * (1.2 + Math.random() * 2.2) - FORWARD.z * 1.5,
          this.colors.foam,
          0.18 + Math.random() * 0.2,
          0.4 + Math.random() * 0.25,
          7.5, 0.8, -0.4, 0.8,
        );
      }
    }
  }

  driftSparks(x, y, z, yaw, side) {
    FORWARD.set(Math.sin(yaw), 0, Math.cos(yaw));
    const right = TMP.set(FORWARD.z, 0, -FORWARD.x);
    for (let i = 0; i < 2; i++) {
      const col = Math.random() < 0.55 ? this.colors.spark : this.colors.sparkHot;
      this.spark.spawn(
        x + right.x * side * 0.58 - FORWARD.x * 0.9,
        y + 0.25,
        z + right.z * side * 0.58 - FORWARD.z * 0.9,
        right.x * side * (1 + Math.random() * 2) + (Math.random() - 0.5) * 1.4,
        1.2 + Math.random() * 2.6,
        right.z * side * (1 + Math.random() * 2) + (Math.random() - 0.5) * 1.4,
        col,
        0.13 + Math.random() * 0.12,
        0.25 + Math.random() * 0.3,
        8, 0.5, 0.4, 1,
      );
    }
  }

  boostTrail(x, y, z, yaw) {
    FORWARD.set(Math.sin(yaw), 0, Math.cos(yaw));
    for (let i = 0; i < 3; i++) {
      this.spark.spawn(
        x - FORWARD.x * 1.7 + (Math.random() - 0.5) * 0.5,
        y + 0.15 + (Math.random() - 0.5) * 0.3,
        z - FORWARD.z * 1.7 + (Math.random() - 0.5) * 0.5,
        -FORWARD.x * (4 + Math.random() * 4) + (Math.random() - 0.5) * 2,
        0.4 + Math.random() * 1.6,
        -FORWARD.z * (4 + Math.random() * 4) + (Math.random() - 0.5) * 2,
        Math.random() < 0.5 ? this.colors.nitro : this.colors.blue,
        0.2 + Math.random() * 0.28,
        0.35 + Math.random() * 0.3,
        0, 1.2, 0.8, 0.9,
      );
    }
  }

  splash(x, y, z, strength = 1) {
    const count = Math.floor(22 + strength * 34);
    for (let i = 0; i < count; i++) {
      const a = Math.random() * Math.PI * 2;
      const r = 1.5 + Math.random() * 3.5;
      this.foam.spawn(
        x + Math.cos(a) * Math.random() * 1.2,
        y + 0.15,
        z + Math.sin(a) * Math.random() * 1.2,
        Math.cos(a) * r,
        2.5 + Math.random() * (4.2 * strength),
        Math.sin(a) * r,
        Math.random() < 0.3 ? this.colors.foamDeep : this.colors.foam,
        0.32 + Math.random() * 0.55,
        0.55 + Math.random() * 0.5,
        9.5, 0.55, 0.5, 0.9,
      );
    }
    for (let i = 0; i < 16; i++) {
      const a = Math.random() * Math.PI * 2;
      this.spark.spawn(
        x, y + 0.5, z,
        Math.cos(a) * (2 + Math.random() * 4), 3 + Math.random() * 5, Math.sin(a) * (2 + Math.random() * 4),
        this.colors.foam, 0.15 + Math.random() * 0.2, 0.5 + Math.random() * 0.3, 10, 0.7, 0.4, 0.55,
      );
    }
  }

  pickupBurst(x, y, z, type) {
    const color = type === 'nitro' ? this.colors.nitro : type === 'shield' ? this.colors.shield : this.colors.coin;
    for (let i = 0; i < 20; i++) {
      const a = Math.random() * Math.PI * 2;
      const s = 2.5 + Math.random() * 4.5;
      this.spark.spawn(
        x, y, z,
        Math.cos(a) * s, 1 + Math.random() * 3.5, Math.sin(a) * s,
        color, 0.12 + Math.random() * 0.18, 0.45 + Math.random() * 0.35, 2, 1.6, 0.2, 1,
      );
    }
  }

  impact(x, y, z, strength = 1) {
    for (let i = 0; i < 28; i++) {
      const a = Math.random() * Math.PI * 2;
      const s = 3 + Math.random() * 6;
      this.spark.spawn(
        x, y + 0.4, z,
        Math.cos(a) * s, 1.5 + Math.random() * 4, Math.sin(a) * s,
        Math.random() < 0.4 ? this.colors.sparkHot : this.colors.spark,
        0.16 + Math.random() * 0.2, 0.35 + Math.random() * 0.3, 9, 1.2, 0.3, 0.9 * strength,
      );
    }
    this.splash(x, y, z, strength * 1.2);
  }

  shieldBreak(x, y, z) {
    for (let i = 0; i < 32; i++) {
      const a = Math.random() * Math.PI * 2;
      const b = Math.random() * Math.PI - Math.PI / 2;
      const s = 3 + Math.random() * 4;
      this.spark.spawn(
        x, y + 0.7, z,
        Math.cos(a) * Math.cos(b) * s, Math.sin(b) * s + 1.5, Math.sin(a) * Math.cos(b) * s,
        this.colors.shield, 0.16 + Math.random() * 0.22, 0.5 + Math.random() * 0.3, 3, 0.8, 0.3, 1,
      );
    }
  }

  update(dt) {
    this.foam.update(dt);
    this.spark.update(dt);
  }

  setPixelScale(scale) {
    this.foam.material.uniforms.uScale.value = scale;
    this.spark.material.uniforms.uScale.value = scale;
  }
}

import { clamp, damp } from '../core/utils.js';

export class Input {
  constructor({ onPause } = {}) {
    this.onPause = onPause;
    this.steer = 0;
    this.steerTarget = 0;
    this.nitroHeld = false;
    this.brakeHeld = false;
    this.jumpQueued = false;
    this.nitroTapQueued = false;
    this.controlScheme = 'joystick';
    this.joystickActive = false;
    this.pointerId = null;
    this.keys = new Set();
    this.tiltRaw = 0;
    this.tiltCenter = null;
    this.tiltSamples = [];
    this.tiltReady = false;
    this.tiltPermission = 'unknown';
    this.tiltHandler = null;
    this.swipe = null;
    this.enabled = false;
    this.joystickRadius = 48;
    this.knobEl = null;
    this.joystickEl = null;
    this.bind();
  }

  bind() {
    this.joystickEl = document.getElementById('joystickZone');
    this.knobEl = document.getElementById('joystickKnob');
    this.nitroBtn = document.getElementById('nitroBtn');
    this.brakeBtn = document.getElementById('brakeBtn');

    this.bindJoystick();
    this.bindHoldButton(this.nitroBtn, 'nitro');
    this.bindHoldButton(this.brakeBtn, 'brake');
    this.bindSwipe();
    this.bindKeyboard();

    window.addEventListener('blur', () => this.reset());
    document.addEventListener('visibilitychange', () => {
      if (document.hidden) this.reset();
    });
  }

  bindJoystick() {
    const zone = this.joystickEl;
    if (!zone) return;
    const update = (e) => {
      const rect = zone.getBoundingClientRect();
      const cx = rect.left + rect.width / 2;
      const cy = rect.top + rect.height * 0.42;
      let dx = e.clientX - cx;
      let dy = e.clientY - cy;
      const radius = Math.min(rect.width * 0.38, 52);
      const len = Math.hypot(dx, dy);
      if (len > radius) {
        dx = (dx / len) * radius;
        dy = (dy / len) * radius;
      }
      this.steerTarget = clamp(dx / radius, -1, 1);
      if (this.knobEl) this.knobEl.style.transform = `translate(${dx}px, ${dy}px)`;
    };
    zone.addEventListener('pointerdown', (e) => {
      if (!this.enabled || this.controlScheme !== 'joystick') return;
      e.preventDefault();
      this.joystickActive = true;
      this.pointerId = e.pointerId;
      zone.setPointerCapture(e.pointerId);
      update(e);
    });
    zone.addEventListener('pointermove', (e) => {
      if (!this.joystickActive || e.pointerId !== this.pointerId) return;
      e.preventDefault();
      update(e);
    });
    const end = (e) => {
      if (e.pointerId !== this.pointerId) return;
      this.joystickActive = false;
      this.pointerId = null;
      this.steerTarget = 0;
      if (this.knobEl) this.knobEl.style.transform = 'translate(0px, 0px)';
    };
    zone.addEventListener('pointerup', end);
    zone.addEventListener('pointercancel', end);
    zone.addEventListener('lostpointercapture', end);
  }

  bindHoldButton(el, type) {
    if (!el) return;
    const down = (e) => {
      if (!this.enabled) return;
      e.preventDefault();
      el.setPointerCapture?.(e.pointerId);
      el.classList.add('held');
      if (type === 'nitro') {
        this.nitroHeld = true;
        this.nitroTapQueued = true;
      } else {
        this.brakeHeld = true;
      }
    };
    const up = (e) => {
      e.preventDefault();
      el.classList.remove('held');
      if (type === 'nitro') this.nitroHeld = false;
      else this.brakeHeld = false;
    };
    el.addEventListener('pointerdown', down);
    el.addEventListener('pointerup', up);
    el.addEventListener('pointercancel', up);
    el.addEventListener('lostpointercapture', up);
    el.addEventListener('contextmenu', (e) => e.preventDefault());
  }

  bindSwipe() {
    const canvas = document.getElementById('game-canvas');
    if (!canvas) return;
    canvas.addEventListener('pointerdown', (e) => {
      if (!this.enabled) return;
      this.swipe = { id: e.pointerId, x: e.clientX, y: e.clientY, time: performance.now() };
    });
    canvas.addEventListener('pointerup', (e) => {
      if (!this.enabled || !this.swipe || e.pointerId !== this.swipe.id) return;
      const dy = e.clientY - this.swipe.y;
      const dx = e.clientX - this.swipe.x;
      const dt = performance.now() - this.swipe.time;
      if (dt < 650 && dy < -54 && Math.abs(dx) < 95) this.jumpQueued = true;
      this.swipe = null;
    });
    canvas.addEventListener('pointercancel', () => { this.swipe = null; });
    canvas.addEventListener('contextmenu', (e) => e.preventDefault());
  }

  bindKeyboard() {
    window.addEventListener('keydown', (e) => {
      if (['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Space'].includes(e.code)) e.preventDefault();
      this.keys.add(e.code);
      if (!this.enabled) return;
      if (e.code === 'Escape' || e.code === 'KeyP') this.onPause?.();
      if (e.code === 'Space') this.jumpQueued = true;
      if (e.code === 'KeyN' || e.code === 'ShiftLeft' || e.code === 'ShiftRight') {
        this.nitroHeld = true;
        this.nitroTapQueued = true;
      }
      if (e.code === 'KeyB' || e.code === 'KeyS') this.brakeHeld = true;
    });
    window.addEventListener('keyup', (e) => {
      this.keys.delete(e.code);
      if (e.code === 'KeyN' || e.code === 'ShiftLeft' || e.code === 'ShiftRight') this.nitroHeld = false;
      if (e.code === 'KeyB' || e.code === 'KeyS') this.brakeHeld = false;
    });
  }

  setEnabled(on) {
    this.enabled = on;
    if (!on) this.reset();
  }

  setControlScheme(scheme) {
    this.controlScheme = scheme;
    if (scheme === 'tilt') this.enableTilt();
  }

  async enableTilt() {
    if (this.tiltHandler) return true;
    try {
      if (typeof DeviceOrientationEvent !== 'undefined' && typeof DeviceOrientationEvent.requestPermission === 'function') {
        const permission = await DeviceOrientationEvent.requestPermission();
        this.tiltPermission = permission;
        if (permission !== 'granted') return false;
      }
      this.tiltHandler = (e) => {
        const angle = (screen.orientation && screen.orientation.angle) || window.orientation || 0;
        let raw = 0;
        if (Math.abs(angle) === 90) raw = e.beta ?? 0;
        else raw = e.gamma ?? 0;
        if (angle === -90 || angle === 270) raw = -raw;
        this.tiltRaw = raw;
        if (this.tiltCenter == null) {
          this.tiltSamples.push(raw);
          if (this.tiltSamples.length > 8) {
            this.tiltCenter = this.tiltSamples.reduce((a, b) => a + b, 0) / this.tiltSamples.length;
            this.tiltReady = true;
          }
        }
      };
      window.addEventListener('deviceorientation', this.tiltHandler, true);
      this.tiltPermission = 'granted';
      return true;
    } catch {
      this.tiltPermission = 'denied';
      return false;
    }
  }

  calibrateTilt() {
    this.tiltCenter = null;
    this.tiltSamples = [];
  }

  update(dt) {
    let target = 0;
    if (this.controlScheme === 'joystick') {
      target = this.steerTarget;
      if (this.keys.has('ArrowLeft') || this.keys.has('KeyA')) target -= 1;
      if (this.keys.has('ArrowRight') || this.keys.has('KeyD')) target += 1;
      target = clamp(target, -1, 1);
    } else {
      if (this.tiltReady) {
        const delta = this.tiltRaw - this.tiltCenter;
        const dead = 1.8;
        const sign = Math.sign(delta);
        target = Math.abs(delta) < dead ? 0 : clamp((delta - sign * dead) / 16, -1, 1);
      }
      if (this.keys.has('ArrowLeft') || this.keys.has('KeyA')) target -= 1;
      if (this.keys.has('ArrowRight') || this.keys.has('KeyD')) target += 1;
      target = clamp(target, -1, 1);
    }
    if (!this.enabled) target = 0;
    this.steer = damp(this.steer, target, 13, dt);
  }

  consumeJump() {
    if (!this.jumpQueued) return false;
    this.jumpQueued = false;
    return true;
  }

  consumeNitroTap() {
    if (!this.nitroTapQueued) return false;
    this.nitroTapQueued = false;
    return true;
  }

  reset() {
    this.steer = 0;
    this.steerTarget = 0;
    this.nitroHeld = false;
    this.brakeHeld = false;
    this.jumpQueued = false;
    this.nitroTapQueued = false;
    this.joystickActive = false;
    this.pointerId = null;
    this.keys.clear();
    this.nitroBtn?.classList.remove('held');
    this.brakeBtn?.classList.remove('held');
    if (this.knobEl) this.knobEl.style.transform = 'translate(0px, 0px)';
  }
}

import * as THREE from 'three';
import { clamp, damp, smoothstep, formatTime } from '../core/utils.js';
import { waveHeight } from '../world/Track.js';

const START_T = 0.981;
const START_LATERAL = 0;

export class Player {
  constructor(track, effects) {
    this.track = track;
    this.effects = effects;
    this.position = new THREE.Vector3();
    this.right = new THREE.Vector3(1, 0, 0);
    this.forward = new THREE.Vector3(0, 0, 1);
    this.events = {};
    this.model = null;
    this.resetStats();
    this.reset(3);
  }

  setModel(model) {
    this.model = model;
  }

  applyPerformance(perf) {
    this.perf = perf;
    this.maxSpeed = 38 * perf.speed;
    this.accel = 13.2 * perf.speed;
    this.turnRate = 1.78 * perf.handling;
    this.boostPower = 10.5 * perf.boost;
  }

  resetStats() {
    this.perf = { speed: 1, handling: 1, boost: 1 };
    this.maxSpeed = 38;
    this.accel = 13.2;
    this.turnRate = 1.78;
    this.boostPower = 10.5;
    this.topSpeedSeen = 0;
  }

  reset(laps = 3) {
    this.laps = laps;
    const f = this.track.getFrameAt(START_T);
    this.position.copy(f.pos).addScaledVector(f.left, START_LATERAL);
    this.yaw = Math.atan2(f.tangent.x, f.tangent.z);
    this.speed = 0;
    this.steerVisual = 0;
    this.raceDist = (START_T - 1) * this.track.length;
    this.lastT = START_T;
    this.prevT = START_T;
    this.lateral = START_LATERAL;
    this.lap = 0;
    this.nextGate = 0;
    this.checkpoints = 0;
    this.lastHint = null;
    this.finished = false;
    this.finishTime = 0;
    this.speed = 0;
    this.stun = 0;
    this.invuln = 0;
    this.shieldTimer = 0;
    this.nitro = 12;
    this.boosting = false;
    this.superTimer = 0;
    this.boostVisual = 0;
    this.driftActive = false;
    this.driftAmount = 0;
    this.driftCharge = 0;
    this.driftDistance = 0;
    this.airborne = false;
    this.elevation = 0;
    this.vy = 0;
    this.jumpCooldown = 0;
    this.jumpCount = 0;
    this.boostCount = 0;
    this.coins = 0;
    this.waterY = 0;
    this.time = 0;
    this.trailTimer = 0;
    this.sparkTimer = 0;
    this.boostParticleTimer = 0;
    this.collisionCooldown = 0;
    this.lapStartTime = 0;
    this.bestLap = null;
    this.lastLapTime = null;
    this.edgeTimer = 0;
    this.active = false;
  }

  start() {
    this.active = true;
  }

  get displayLap() {
    return clamp(this.lap + 1, 1, this.laps);
  }

  get speedKmh() {
    return Math.round(this.speed * 3.6);
  }

  get nitroReady() {
    return this.nitro >= 99;
  }

  get shielded() {
    return this.shieldTimer > 0;
  }

  jump(power = 6.4, big = false) {
    if (this.airborne || this.jumpCooldown > 0 || this.speed < 4) return false;
    this.airborne = true;
    this.elevation = 0.15;
    this.vy = power;
    this.jumpCooldown = big ? 1.4 : 0.9;
    if (big) {
      this.jumpCount++;
      this.events.onJump?.(true);
    } else {
      this.events.onJump?.(false);
    }
    return true;
  }

  hitObstacle(obstacle) {
    if (this.invuln > 0 || this.finished) return 'none';
    this.invuln = 1.35;
    if (this.shieldTimer > 0) {
      this.shieldTimer = 0;
      this.effects.shieldBreak(this.position.x, this.waterY, this.position.z);
      this.events.onShieldBreak?.();
      return 'shield';
    }
    this.speed *= 0.32;
    this.stun = 0.82;
    this.driftActive = false;
    this.driftAmount = 0;
    this.nitro = Math.max(0, this.nitro - 8);
    this.effects.impact(this.position.x, this.waterY, this.position.z, 1);
    this.events.onHit?.(obstacle);
    return 'hit';
  }

  givePickup(type) {
    if (type === 'nitro') {
      this.nitro = clamp(this.nitro + 32, 0, 100);
      return 'nitro';
    }
    if (type === 'shield') {
      this.shieldTimer = 8;
      return 'shield';
    }
    this.coins++;
    return 'coin';
  }

  update(dt, input, time, raceTime) {
    if (!this.active) return;
    this.time = time;
    this.jumpCooldown = Math.max(0, this.jumpCooldown - dt);
    this.invuln = Math.max(0, this.invuln - dt);
    this.collisionCooldown = Math.max(0, this.collisionCooldown - dt);
    this.stun = Math.max(0, this.stun - dt);
    this.shieldTimer = Math.max(0, this.shieldTimer - dt);
    this.superTimer = Math.max(0, this.superTimer - dt);

    const canControl = this.stun <= 0 && !this.finished;
    let steer = canControl ? input.steer : 0;
    if (this.airborne) steer *= 0.55;
    this.steerVisual = damp(this.steerVisual, steer, 10, dt);

    // --- Speed / auto throttle ---
    const speedRatio = this.speed / this.maxSpeed;
    let targetSpeed = this.maxSpeed;
    const wantsBoost = canControl && input.nitroHeld && this.nitro > 0.4 && !this.airborne && this.speed > 3;
    let boosting = false;
    if (this.superTimer > 0) {
      targetSpeed += this.boostPower * 1.55;
      boosting = true;
      this.nitro = Math.max(0, this.nitro - 30 * dt);
    } else if (wantsBoost) {
      targetSpeed += this.boostPower;
      boosting = true;
      this.nitro = Math.max(0, this.nitro - 19 * dt);
      this.boostCount += dt > 0 ? dt * 2.2 : 0;
    }
    if (canControl && input.consumeNitroTap() && this.nitro >= 99) {
      this.superTimer = 1.5;
      this.boostCount += 1;
      this.events.onSuperBoost?.();
    }
    if (boosting && !this.boosting) {
      this.events.onBoost?.();
      this.boostCount += 1;
    }
    this.boosting = boosting;
    this.boostVisual = damp(this.boostVisual, boosting ? 1 : 0, 6, dt);

    if (input.brakeHeld && canControl && !this.airborne) {
      this.speed -= 24 * dt;
      this.speed = Math.max(3, this.speed);
    } else if (this.finished) {
      this.speed = Math.max(0, this.speed - 9 * dt);
    } else if (canControl) {
      const accel = this.accel * (1 + (1 - speedRatio) * 0.28);
      this.speed += accel * dt;
      if (this.speed > targetSpeed) this.speed = damp(this.speed, targetSpeed, 4.5, dt);
    } else {
      this.speed = Math.max(0, this.speed - 7 * dt);
    }
    this.speed = clamp(this.speed, 0, this.maxSpeed + this.boostPower * 1.7);

    // --- Drift ---
    const driftCondition = canControl && !this.airborne && !input.brakeHeld &&
      Math.abs(steer) > 0.58 && this.speed > this.maxSpeed * 0.4;
    this.driftAmount = damp(this.driftAmount, driftCondition ? 1 : 0, 8, dt);
    this.driftActive = driftCondition && this.driftAmount > 0.35;
    if (this.driftActive) {
      this.nitro = clamp(this.nitro + 9.5 * dt, 0, 100);
      this.driftDistance += this.speed * dt;
      this.speed = Math.max(this.maxSpeed * 0.35, this.speed - this.speed * 0.055 * dt);
      this.driftCharge += dt;
      if (this.driftCharge > 0.7 && !this.wasDrifting) this.events.onDriftStart?.();
      this.wasDrifting = true;
      this.sparkTimer -= dt;
      if (this.sparkTimer <= 0) {
        this.sparkTimer = 0.035;
        const f = this.forward;
        this.right.set(f.z, 0, -f.x);
        const side = steer < 0 ? -1 : 1;
        this.effects.driftSparks(
          this.position.x, this.waterY, this.position.z,
          this.yaw, side,
        );
      }
    } else {
      this.wasDrifting = false;
      this.driftCharge = 0;
    }

    // --- Steering ---
    if (canControl && !this.airborne) {
      const highSpeedFactor = 0.72 + 0.28 * (1 - clamp(this.speed / this.maxSpeed, 0, 1));
      const driftTurn = this.driftActive ? 1.12 : 1;
      const brakeTurn = input.brakeHeld ? 1.25 : 1;
      const yawRate = this.turnRate * steer * highSpeedFactor * driftTurn * brakeTurn;
      this.yaw += yawRate * dt;
      if (this.stun > 0) this.yaw += Math.sin(time * 30) * 0.02;
    }

    this.forward.set(Math.sin(this.yaw), 0, Math.cos(this.yaw));
    this.right.set(this.forward.z, 0, -this.forward.x);

    // --- Integrate ---
    this.position.addScaledVector(this.forward, this.speed * dt);
    if (this.driftActive) {
      this.position.addScaledVector(this.right, -Math.sign(steer) * 1.35 * this.driftAmount * dt);
    }
    // River current: a steady push downstream plus a gentle lateral swirl.
    const hint = this.lastHint;
    const preFrame = this.track.nearest(this.position, hint);
    this.track.nearest(this.position, hint);
    const tNow = preFrame.t;
    const current = 0.85 * clamp(1 - Math.abs(preFrame.lateral) / (preFrame.frame.width * 0.5), 0.2, 1);
    this.position.addScaledVector(preFrame.frame.tangent, current * dt);
    this.position.addScaledVector(preFrame.frame.left, Math.sin(tNow * Math.PI * 8 + time * 0.4) * 0.24 * dt);

    // --- Keep the rider inside the river ---
    const near = this.track.nearest(this.position, this.lastHint);
    this.lastHint = near.index;
    this.lateral = near.lateral;
    const half = near.frame.width / 2;
    const limit = half - 1.0;
    if (Math.abs(near.lateral) > limit) {
      const overshoot = Math.abs(near.lateral) - limit;
      const dir = Math.sign(near.lateral);
      this.position.addScaledVector(near.frame.left, -dir * Math.min(overshoot, 3));
      this.speed *= 1 - Math.min(0.9, overshoot * 0.2 + 0.07) * dt * 6;
      this.edgeTimer -= dt;
      if (this.edgeTimer <= 0 && this.speed > 6) {
        this.edgeTimer = 0.25;
        this.effects.splash(this.position.x, this.waterY, this.position.z, 0.4);
      }
      this.events.onEdge?.(overshoot);
    }

    // --- Track progress & checkpoints ---
    const delta = this.track.deltaT(this.lastT, near.t);
    if (Math.abs(delta) < 0.03) this.raceDist += delta * this.track.length;
    this.prevT = this.lastT;
    this.lastT = near.t;

    const currentLapStart = this.lap * this.track.length;
    while (this.nextGate < this.track.gateCount &&
      this.raceDist >= currentLapStart + this.track.gateDistances[this.nextGate]) {
      this.nextGate++;
      this.checkpoints++;
      this.onCheckpoint();
    }
    if (this.raceDist >= (this.lap + 1) * this.track.length && this.lap < this.laps) {
      if (this.nextGate >= this.track.gateCount) {
        this.lastLapTime = raceTime - this.lapStartTime;
        this.bestLap = this.bestLap == null ? this.lastLapTime : Math.min(this.bestLap, this.lastLapTime);
        this.lap++;
        this.nextGate = 0;
        this.lapStartTime = raceTime;
        this.events.onLap?.(this.lap, this.lastLapTime);
        if (this.lap >= this.laps) {
          this.finished = true;
          this.finishTime = raceTime;
          this.active = false;
          this.events.onFinish?.(raceTime);
        }
      } else {
        // Push back to the line; missing a checkpoint never grants a lap.
        this.raceDist = Math.min(this.raceDist, (this.lap + 1) * this.track.length - 0.5);
      }
    }

    // --- Airborne ---
    this.waterY = waveHeight(this.position.x, this.position.z, time);
    if (this.airborne) {
      this.elevation += this.vy * dt;
      this.vy -= 21 * dt;
      if (this.elevation <= 0) {
        const impact = Math.abs(this.vy);
        this.elevation = 0;
        this.airborne = false;
        this.vy = 0;
        this.effects.splash(this.position.x, this.waterY, this.position.z, clamp(impact / 8, 0.6, 1.6));
        this.events.onLand?.(impact);
        this.nitro = clamp(this.nitro + 4, 0, 100);
      }
    }

    this.topSpeedSeen = Math.max(this.topSpeedSeen, this.speed);

    // --- Visuals & continuous trails ---
    if (this.model) {
      this.model.setTransform(
        this.position, this.yaw, this.waterY, time,
        {
          speed: this.speed,
          steer: this.steerVisual,
          drift: this.driftAmount,
          boost: this.boostVisual,
          airborne: this.airborne,
          shield: this.shieldTimer > 0,
          stun: this.stun,
        },
      );
    }

    this.trailTimer -= dt;
    if (this.speed > 3 && this.trailTimer <= 0) {
      this.trailTimer = 0.055;
      this.effects.emitWake(this.position.x, this.waterY, this.position.z, this.yaw, this.speed, 1);
    }
    this.boostParticleTimer -= dt;
    if (this.boosting && this.boostParticleTimer <= 0) {
      this.boostParticleTimer = 0.035;
      this.effects.boostTrail(this.position.x, this.waterY, this.position.z, this.yaw);
    }
  }

  onCheckpoint() {
    this.events.onCheckpoint?.(this.nextGate, this.track.gateCount);
  }
}

import * as THREE from 'three';
import { clamp, damp, lerp } from '../core/utils.js';
import { waveHeight } from '../world/Track.js';

const PROFILES = [
  { name: 'Kai', c1: '#ff8a3d', c2: '#c1401b', accent: '#ffd356', trim: '#ffeede', riderColor: '#ffd356', helmet: '#f8f5e6', base: 36.7, lane: -6 },
  { name: 'Maya', c1: '#d8ff5d', c2: '#5c9a1d', accent: '#7af3d5', trim: '#f4ffe2', riderColor: '#16a58e', helmet: '#f8f5e6', base: 37.4, lane: 6 },
  { name: 'Nui', c1: '#ff72b6', c2: '#a22c6b', accent: '#ffe4f0', trim: '#fff4fa', riderColor: '#ff72b6', helmet: '#f8f5e6', base: 36.2, lane: 0 },
  { name: 'Tane', c1: '#8ca7ff', c2: '#344ba8', accent: '#c9f5ff', trim: '#eef4ff', riderColor: '#8ca7ff', helmet: '#f8f5e6', base: 37.0, lane: -3 },
  { name: 'Lani', c1: '#ffc857', c2: '#b97a1e', accent: '#fff3c4', trim: '#fff9ec', riderColor: '#ff7a48', helmet: '#f8f5e6', base: 35.7, lane: 3 },
];

export class Opponent {
  constructor(index, track, effects, model) {
    this.index = index;
    this.profile = PROFILES[index % PROFILES.length];
    this.track = track;
    this.effects = effects;
    this.model = model;
    this.position = new THREE.Vector3();
    this.lane = this.profile.lane;
    this.targetLane = this.lane;
    this.time = 0;
    this.reset(3, 1, 0);
  }

  reset(laps, difficulty = 1, startIndex = 0) {
    const rows = [
      { t: 0.992, lat: -8.2 },
      { t: 0.992, lat: 8.2 },
      { t: 0.989, lat: 0 },
      { t: 0.974, lat: -8.2 },
      { t: 0.974, lat: 8.2 },
    ];
    const row = rows[startIndex % rows.length];
    this.startT = row.t;
    this.raceDist = (row.t - 1) * this.track.length;
    this.lateral = row.lat;
    this.targetLane = row.lat;
    this.lane = row.lat;
    this.laps = laps;
    this.speed = 0;
    this.baseSpeed = this.profile.base * (0.965 + difficulty * 0.035);
    this.finished = false;
    this.finishTime = 0;
    this.stun = 0;
    this.air = 0;
    this.vy = 0;
    this.airborne = false;
    this.yaw = 0;
    this.steerVisual = 0;
    this.wakeTimer = Math.random() * 0.1;
    this.laneTimer = Math.random() * 4;
    this.laneTarget = row.lat;
    this.bobPhase = Math.random() * 6;
    this.jumpCheck = row.t;
    const f = this.track.getFrameAt(row.t);
    this.position.copy(f.pos).addScaledVector(f.left, row.lat);
    this.yaw = Math.atan2(f.tangent.x, f.tangent.z);
    if (this.model) {
      this.model.setTransform(this.position, this.yaw, 0, 0, { speed: 0 });
    }
  }

  update(dt, time, player, race) {
    this.time = time;
    if (this.finished) {
      this.speed = Math.max(0, this.speed - 5 * dt);
      this.raceDist += this.speed * dt;
    } else {
      const t = ((this.raceDist / this.track.length) % 1 + 1) % 1;
      const f = this.track.getFrameAt(t);
      const ahead = this.track.getFrameAt((t + 0.014) % 1);
      const curvature = Math.acos(clamp(f.tangent.dot(ahead.tangent), -1, 1));
      const curveFactor = clamp(1 - curvature * 0.55, 0.72, 1);
      const diff = (player?.raceDist ?? 0) - this.raceDist;
      let rubber = 0;
      if (diff > 10) rubber = clamp(diff * 0.025, 0, 3.2);
      else if (diff < -15) rubber = -clamp((-diff - 15) * 0.018, 0, 2.2);
      let targetSpeed = this.baseSpeed * curveFactor + rubber;
      targetSpeed = clamp(targetSpeed, 21, 41);

      const accel = this.speed < targetSpeed ? 11 : 16;
      this.speed = damp(this.speed, targetSpeed, this.speed < targetSpeed ? 2.2 : 5.5, dt);
      this.speed = clamp(this.speed, 0, 42);
      this.raceDist += this.speed * dt;

      if (this.raceDist >= this.laps * this.track.length) {
        this.finished = true;
        this.finishTime = race?.time ?? 0;
      }
    }

    const t = ((this.raceDist / this.track.length) % 1 + 1) % 1;
    const f = this.track.getFrameAt(t);
    const half = f.width / 2;

    // Lane changes and simple obstacle avoidance.
    this.laneTimer -= dt;
    if (this.laneTimer <= 0) {
      this.laneTimer = 3.4 + Math.random() * 3;
      this.laneTarget = (Math.random() - 0.5) * (half * 1.15);
    }
    if (race?.objects) {
      const nearby = race.objects.obstacles;
      for (const o of nearby) {
        const aheadT = ((t - o.t + 1) % 1);
        if (aheadT > 0.002 && aheadT < 0.018 && Math.abs(o.lat - this.lateral) < 5.2) {
          this.laneTarget = clamp(o.lat + (o.lat > this.lateral ? -5.5 : 5.5), -half + 2, half - 2);
          break;
        }
      }
    }
    this.laneTarget = clamp(this.laneTarget, -half + 2, half - 2);
    const prevLateral = this.lateral;
    this.lateral = damp(this.lateral, this.laneTarget, 0.85, dt);
    const lateralVel = (this.lateral - prevLateral) / Math.max(dt, 0.0001);
    this.steerVisual = damp(this.steerVisual, clamp(lateralVel * 0.15, -0.45, 0.45), 5, dt);

    const pos = f.pos.clone().addScaledVector(f.left, this.lateral);
    this.position.copy(pos);
    this.yaw = Math.atan2(f.tangent.x, f.tangent.z);

    // Occasional ramp jumps for life.
    if (race?.objects) {
      const crossed = ((this.jumpCheck - 0.5 + 1) % 1);
      const now = ((t - 0.5 + 1) % 1);
      if (crossed !== now) {
        for (const r of race.objects.ramps) {
          const diff = Math.abs(((t - r.t + 1.5) % 1) - 0.5);
          if (diff < 0.004 && Math.abs(this.lateral) < r.halfWidth && !this.airborne && this.index % 2 === 0) {
            this.airborne = true;
            this.vy = 5.6 + Math.random() * 1.4;
            this.air = 0.2;
          }
        }
      }
    }
    this.jumpCheck = t;

    let elevation = 0;
    if (this.airborne) {
      this.air += this.vy * dt;
      this.vy -= 20 * dt;
      elevation = Math.max(0, this.air);
      if (this.air <= 0) {
        this.airborne = false;
        this.effects.splash(this.position.x, waveHeight(this.position.x, this.position.z, time), this.position.z, 0.8);
      }
    }

    const waterY = waveHeight(this.position.x, this.position.z, time);
    if (this.model) {
      this.model.setTransform(
        this.position, this.yaw, waterY, time,
        {
          speed: this.speed,
          steer: this.steerVisual,
          drift: 0,
          boost: 0,
          airborne: this.airborne,
          shield: false,
          stun: 0,
        },
      );
    }

    if (this.model) {
      this.model.group.position.y += elevation;
      this.model.shadow.visible = !this.airborne;
    }

    this.wakeTimer -= dt;
    if (this.wakeTimer <= 0 && !this.finished && this.speed > 4) {
      this.wakeTimer = 0.16 + Math.random() * 0.08;
      if (player && this.position.distanceToSquared(player.position) < 150 * 150) {
        this.effects.emitWake(this.position.x, waterY, this.position.z, this.yaw, this.speed, 0.72);
      }
    }
  }

  get displayLap() {
    return clamp(Math.floor(this.raceDist / this.track.length) + 1, 1, this.laps);
  }
}

export { PROFILES };

import { clamp, lerp } from '../core/utils.js';

const SOUND_SPEED = 343;

export class AudioEngine {
  constructor(progress) {
    this.progress = progress;
    this.ctx = null;
    this.ready = false;
    this.muted = !progress.settings.sound;
    this.paused = false;
    this.noiseBuffer = null;
    this.birdTimer = 6;
    this.boostAmount = 0;
    this.lastSplash = 0;
    this.buildWhenReady = false;
  }

  async unlock() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') await this.ctx.resume().catch(() => {});
      return true;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return false;
    this.ctx = new Ctx();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.5;
    this.master.connect(this.ctx.destination);
    this.makeNoise();
    this.buildEngine();
    this.buildAmbience();
    this.buildOpponent();
    this.buildBoost();
    this.ready = true;
    await this.ctx.resume().catch(() => {});
    return true;
  }

  makeNoise() {
    const len = this.ctx.sampleRate * 2;
    const buffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    this.noiseBuffer = buffer;
  }

  makeLoopNoise() {
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.loop = true;
    return src;
  }

  buildEngine() {
    const ctx = this.ctx;
    this.engineGain = ctx.createGain();
    this.engineGain.gain.value = 0;
    this.engineFilter = ctx.createBiquadFilter();
    this.engineFilter.type = 'lowpass';
    this.engineFilter.frequency.value = 420;
    this.engineFilter.Q.value = 2.5;
    this.engineGain.connect(this.engineFilter);
    this.engineFilter.connect(this.master);

    this.engineOsc = ctx.createOscillator();
    this.engineOsc.type = 'sawtooth';
    this.engineOsc.frequency.value = 52;
    this.engineOsc.connect(this.engineGain);

    this.engineSub = ctx.createOscillator();
    this.engineSub.type = 'square';
    this.engineSub.frequency.value = 26;
    const subGain = ctx.createGain();
    subGain.gain.value = 0.35;
    this.engineSub.connect(subGain);
    subGain.connect(this.engineGain);

    this.engineTone = ctx.createOscillator();
    this.engineTone.type = 'triangle';
    this.engineTone.frequency.value = 104;
    const toneGain = ctx.createGain();
    toneGain.gain.value = 0.18;
    this.engineTone.connect(toneGain);
    toneGain.connect(this.engineGain);

    this.engineOsc.start();
    this.engineSub.start();
    this.engineTone.start();

    // Water rush.
    const water = this.makeLoopNoise();
    this.waterFilter = ctx.createBiquadFilter();
    this.waterFilter.type = 'bandpass';
    this.waterFilter.frequency.value = 620;
    this.waterFilter.Q.value = 0.6;
    this.waterGain = ctx.createGain();
    this.waterGain.gain.value = 0.05;
    water.connect(this.waterFilter);
    this.waterFilter.connect(this.waterGain);
    this.waterGain.connect(this.master);
    water.start();
  }

  buildAmbience() {
    const pad = this.ctx.createOscillator();
    pad.type = 'sine';
    pad.frequency.value = 92;
    const pad2 = this.ctx.createOscillator();
    pad2.type = 'sine';
    pad2.frequency.value = 138.5;
    this.ambientGain = this.ctx.createGain();
    this.ambientGain.gain.value = 0.022;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 220;
    pad.connect(filter);
    pad2.connect(filter);
    filter.connect(this.ambientGain);
    this.ambientGain.connect(this.master);
    pad.start();
    pad2.start();
  }

  buildOpponent() {
    const ctx = this.ctx;
    this.oppGain = ctx.createGain();
    this.oppGain.gain.value = 0;
    this.oppPan = ctx.createStereoPanner ? ctx.createStereoPanner() : null;
    this.oppOsc = ctx.createOscillator();
    this.oppOsc.type = 'sawtooth';
    this.oppOsc.frequency.value = 58;
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 500;
    this.oppOsc.connect(filter);
    if (this.oppPan) {
      filter.connect(this.oppGain);
      this.oppGain.connect(this.oppPan);
      this.oppPan.connect(this.master);
    } else {
      filter.connect(this.oppGain);
      this.oppGain.connect(this.master);
    }
    this.oppOsc.start();
  }

  buildBoost() {
    const ctx = this.ctx;
    this.boostNoise = this.makeLoopNoise();
    const filter = ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.value = 1200;
    filter.Q.value = 0.9;
    this.boostGain = ctx.createGain();
    this.boostGain.gain.value = 0;
    this.boostNoise.connect(filter);
    filter.connect(this.boostGain);
    this.boostGain.connect(this.master);
    this.boostNoise.start();
    this.boostFilter = filter;
  }

  setMuted(muted) {
    this.muted = muted;
    if (this.master) this.master.gain.setTargetAtTime(muted ? 0 : 0.5, this.ctx.currentTime, 0.15);
  }

  setPaused(paused) {
    this.paused = paused;
    if (this.ready) {
      const t = this.ctx.currentTime;
      this.engineGain.gain.setTargetAtTime(paused ? 0.02 : 0.12, t, 0.2);
      this.waterGain.gain.setTargetAtTime(paused ? 0.01 : 0.05, t, 0.2);
    }
  }

  update(dt, state) {
    if (!this.ready || !this.ctx) return;
    const { speed = 0, maxSpeed = 38, boosting = false, active = false, opponents, player, camera } = state;
    const rpm = clamp(speed / maxSpeed, 0, 1.2);
    const boost = boosting ? 1 : 0;
    this.boostAmount = lerp(this.boostAmount, boost, 1 - Math.exp(-6 * dt));
    const t = this.ctx.currentTime;
    const engineVol = active && !this.paused ? 0.1 + rpm * 0.12 : 0;
    this.engineGain.gain.setTargetAtTime(engineVol, t, 0.09);
    this.engineFilter.frequency.setTargetAtTime(340 + rpm * 1350 + this.boostAmount * 500, t, 0.09);
    const baseFreq = 48 + rpm * 140 + this.boostAmount * 30;
    this.engineOsc.frequency.setTargetAtTime(baseFreq, t, 0.09);
    this.engineSub.frequency.setTargetAtTime(baseFreq * 0.5, t, 0.1);
    this.engineTone.frequency.setTargetAtTime(baseFreq * 2.02, t, 0.09);
    this.waterGain.gain.setTargetAtTime(active && !this.paused ? 0.05 + rpm * 0.055 : 0.045, t, 0.25);
    this.waterFilter.frequency.setTargetAtTime(470 + rpm * 900, t, 0.2);
    this.boostGain.gain.setTargetAtTime(active && !this.paused ? this.boostAmount * 0.085 : 0, t, 0.08);
    this.boostFilter.frequency.setTargetAtTime(900 + rpm * 1200, t, 0.1);

    // Nearest rival engine, with distance gain, stereo pan and doppler shift.
    if (opponents && player) {
      let nearest = null;
      let best = Infinity;
      for (const o of opponents) {
        if (o.finished) continue;
        const d = o.position.distanceToSquared(player.position);
        if (d < best) { best = d; nearest = o; }
      }
      if (nearest && active && !this.paused) {
        const dist = Math.sqrt(best);
        const gain = clamp(1 - dist / 70, 0, 1) * 0.055;
        this.oppGain.gain.setTargetAtTime(gain, t, 0.15);
        const relX = nearest.position.x - player.position.x;
        const relZ = nearest.position.z - player.position.z;
        const pan = clamp((relX * Math.cos(player.yaw) - relZ * Math.sin(player.yaw)) / Math.max(1, dist), -1, 1);
        this.oppPan?.pan.setTargetAtTime(pan * 0.8, t, 0.15);
        const closing = nearest.speed - player.speed;
        const doppler = clamp(SOUND_SPEED / (SOUND_SPEED - clamp(closing, -20, 20)), 0.88, 1.14);
        this.oppOsc.frequency.setTargetAtTime((55 + clamp(nearest.speed / 40, 0, 1) * 105) * doppler, t, 0.1);
      } else {
        this.oppGain.gain.setTargetAtTime(0, t, 0.2);
      }
    } else {
      this.oppGain?.gain.setTargetAtTime(0, t, 0.2);
    }

    // Occasional tropical bird calls.
    this.birdTimer -= dt;
    if (this.birdTimer <= 0 && active && !this.paused) {
      this.birdTimer = 7 + Math.random() * 12;
      this.chirp();
    }
  }

  tone(freq, dur, type = 'sine', gain = 0.12, slideTo = null, delay = 0) {
    if (!this.ready || this.muted) return;
    const t = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (slideTo) osc.frequency.exponentialRampToValueAtTime(Math.max(20, slideTo), t + dur);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(gain, t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(g);
    g.connect(this.master);
    osc.start(t);
    osc.stop(t + dur + 0.03);
  }

  noiseBurst(dur = 0.3, freq = 900, gain = 0.15, q = 0.8) {
    if (!this.ready || this.muted) return;
    const ctx = this.ctx;
    const t = ctx.currentTime;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const filter = ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.value = freq;
    filter.Q.value = q;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(gain, t + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(filter);
    filter.connect(g);
    g.connect(this.master);
    src.start(t);
    src.stop(t + dur + 0.05);
  }

  chirp() {
    if (!this.ready || this.muted) return;
    const base = 1300 + Math.random() * 900;
    this.tone(base, 0.09, 'sine', 0.018, base * 1.4);
    this.tone(base * 1.2, 0.12, 'sine', 0.012, base * 0.8, 0.1);
  }

  countdown(step) {
    if (step > 0) {
      this.tone(440, 0.16, 'sine', 0.1, 440);
      this.tone(880, 0.08, 'triangle', 0.03);
    } else {
      this.tone(880, 0.35, 'sawtooth', 0.09, 1320);
      this.tone(660, 0.5, 'sine', 0.08);
    }
  }

  splash(amount = 1) {
    this.noiseBurst(0.35 + amount * 0.25, 650, 0.045 + amount * 0.06, 0.6);
  }

  hit() {
    this.noiseBurst(0.28, 220, 0.22, 0.9);
    this.tone(90, 0.25, 'sine', 0.18, 42);
  }

  coin() {
    this.tone(1180, 0.09, 'triangle', 0.06);
    this.tone(1760, 0.12, 'triangle', 0.045, null, 0.06);
  }

  pickup(type) {
    if (type === 'nitro') {
      this.tone(560, 0.16, 'sawtooth', 0.04, 980);
      this.tone(840, 0.2, 'sine', 0.035, 1200, 0.04);
    } else if (type === 'shield') {
      this.tone(520, 0.2, 'triangle', 0.05, 760);
      this.tone(780, 0.3, 'sine', 0.035, 1040, 0.08);
    } else {
      this.coin();
    }
  }

  boost() {
    this.noiseBurst(0.7, 1600, 0.08, 1.2);
    this.tone(130, 0.55, 'sawtooth', 0.06, 280);
  }

  jump() {
    this.tone(240, 0.25, 'triangle', 0.05, 460);
    this.noiseBurst(0.18, 900, 0.03, 0.7);
  }

  land(amount = 1) {
    this.noiseBurst(0.5, 500, 0.07 + amount * 0.04, 0.8);
    this.tone(70, 0.2, 'sine', 0.1, 45);
  }

  lap() {
    this.tone(660, 0.12, 'triangle', 0.06);
    this.tone(880, 0.12, 'triangle', 0.06, null, 0.11);
    this.tone(1100, 0.22, 'sine', 0.05, null, 0.22);
  }

  finish(win = false) {
    const notes = win ? [523, 659, 784, 1046] : [440, 554, 659, 880];
    notes.forEach((n, i) => this.tone(n, 0.5, i === 3 ? 'sine' : 'triangle', 0.06, null, i * 0.13));
  }

  shieldBreak() {
    this.noiseBurst(0.35, 1400, 0.08, 1.2);
    this.tone(900, 0.3, 'triangle', 0.05, 300);
  }

  ui() {
    this.tone(780, 0.06, 'sine', 0.035);
  }

  splashIfReady(amount) {
    const now = performance.now();
    if (now - this.lastSplash > 220) {
      this.lastSplash = now;
      this.splash(amount);
    }
  }
}

