export class UI {
  constructor(game) {
    this.game = game;
    this.progress = game.progress;
    this.hudAccum = 0;
    this.messageTimer = null;
    this.toastTimer = null;
    this.swipeHintTimer = null;
    this.panelOpen = false;
    this.activePanel = null;
    this.garagePreview = this.progress.save.selected;
    this.bind();
    this.cacheMinimap();
    this.refreshMenu();
  }

  bind() {
    const on = (id, fn) => $(id)?.addEventListener('click', (e) => {
      this.game.audio?.ui?.();
      fn(e);
    });
    on('quickRaceBtn', () => this.game.startRace({ mode: 'quick' }));
    on('careerBtn', () => this.openCareer());
    on('timeTrialBtn', () => this.game.startRace({ mode: 'time' }));
    on('garageBtn', () => this.openGarage());
    on('dailyBtn', () => this.openDaily());
    on('menuDailyBtn', () => this.openDaily());
    on('settingsBtn', () => this.openSettings());
    on('pauseBtn', () => this.game.pause());
    on('resumeBtn', () => this.game.resume());
    on('restartBtn', () => this.game.restartRace());
    on('pauseSettingsBtn', () => this.openSettings(true));
    on('quitBtn', () => this.game.quitToMenu());
    on('againBtn', () => this.game.restartRace());
    on('resultsMenuBtn', () => this.game.quitToMenu());

    $('panelLayer')?.addEventListener('pointerdown', (e) => {
      if (e.target === $('panelLayer')) this.closePanel();
    });
    $('panelCard')?.addEventListener('click', (e) => this.onPanelClick(e));
    window.addEventListener('keydown', (e) => {
      if (e.code !== 'Escape') return;
      if (this.panelOpen) {
        this.closePanel();
      }
    });
    document.addEventListener('pointerdown', () => this.game.audio?.unlock?.(), { once: true, capture: true });
    window.addEventListener('orientationchange', () => setTimeout(() => this.cacheMinimap(), 250));
    window.addEventListener('resize', () => this.cacheMinimap());
  }

  refreshMenu() {
    $('menuCoins').textContent = formatNumber(this.progress.coins);
    const careerCount = this.progress.careerUnlockedCount();
    $('careerBadge').textContent = `${careerCount}/${CAREER_EVENTS.length}`;
    const daily = this.progress.dailyAvailable() || this.progress.missions.some((m) => !m.claimed && m.progress >= m.target);
    $('dailyDot').classList.toggle('hidden', !this.progress.dailyAvailable());
    $('dailyBadge').classList.toggle('hidden', !daily);
  }

  showMenu() {
    $('menu').classList.remove('hidden');
    $('hud').classList.add('hidden');
    $('pause').classList.add('hidden');
    $('results').classList.add('hidden');
    $('countdown').classList.add('hidden');
    $('boostOverlay').classList.remove('active');
    $('slowmoOverlay').classList.remove('active');
    this.closePanel();
    this.refreshMenu();
  }

  showRaceHUD(mode, laps, rivals, scheme) {
    $('menu').classList.add('hidden');
    $('hud').classList.remove('hidden');
    $('hud').classList.toggle('tilt-mode', scheme === 'tilt');
    $('modeChip').textContent = mode === 'career' ? 'CAREER' : mode === 'time' ? 'TIME TRIAL' : 'QUICK RACE';
    $('hudLap').nextElementSibling.textContent = `/${laps}`;
    $('hudPos').parentElement.querySelector('i').textContent = `/${rivals + 1}`;
    $('raceMessage').classList.remove('show');
    $('checkpointToast').classList.remove('show');
    $('swipeHint').classList.remove('hide');
    clearTimeout(this.swipeHintTimer);
    this.swipeHintTimer = setTimeout(() => $('swipeHint').classList.add('hide'), 8000);
  }

  showCountdown() {
    $('countdown').classList.remove('hidden');
    $('countdownValue').classList.remove('go');
  }

  updateCountdown(value, sub) {
    const el = $('countdownValue');
    el.textContent = value;
    $('countdownSub').textContent = sub || '';
    el.classList.toggle('go', value === 'GO!');
    // restart pop animation
    el.style.animation = 'none';
    void el.offsetHeight;
    el.style.animation = '';
    const lights = document.querySelectorAll('.start-lights i');
    lights.forEach((l, i) => l.classList.toggle('on', value !== 'GO!' && i < 3 - (Number(value) - 1 || 0)));
  }

  hideCountdown() {
    $('countdown').classList.add('hidden');
    $('countdownValue').classList.remove('go');
  }

  showRaceMessage(text, sub = '', duration = 1300, big = false) {
    const el = $('raceMessage');
    el.innerHTML = `${text}${sub ? `<small>${sub}</small>` : ''}`;
    el.classList.toggle('big', big);
    el.classList.add('show');
    clearTimeout(this.messageTimer);
    if (duration > 0) this.messageTimer = setTimeout(() => el.classList.remove('show'), duration);
  }

  hideRaceMessage() {
    clearTimeout(this.messageTimer);
    $('raceMessage').classList.remove('show');
  }

  checkpointToast(text) {
    const el = $('checkpointToast');
    el.textContent = text;
    el.classList.add('show');
    clearTimeout(this.checkpointTimer);
    this.checkpointTimer = setTimeout(() => el.classList.remove('show'), 1700);
  }

  updateHUD(state) {
    const { player, position, racers, time, lapTime, mode, boost, slowmo } = state;
    const posEl = $('hudPos');
    posEl.textContent = position;
    $('hudLap').textContent = player.displayLap;
    $('hudTimer').textContent = formatTime(time);
    $('hudLapTime').textContent = `LAP ${formatTime(lapTime)}`;
    $('speedVal').textContent = player.speedKmh;
    const ratio = clamp(player.speed / (player.maxSpeed + player.boostPower), 0, 1);
    const arc = $('speedArc');
    arc.style.strokeDasharray = `${ratio * 240} 321`;
    const pct = Math.round(player.nitro);
    $('nitroFill').style.width = `${pct}%`;
    $('nitroPct').textContent = `${pct}%`;
    const wrap = $('nitroFill').closest('.nitro-wrap');
    wrap.classList.toggle('full', pct >= 99);
    $('nitroBtn').classList.toggle('ready', pct >= 99);
    $('driftTag').classList.toggle('hidden', !player.driftActive);
    $('shieldTag').classList.toggle('hidden', player.shieldTimer <= 0);
    if (player.shieldTimer > 0) $('shieldTime').textContent = `${Math.ceil(player.shieldTimer)}s`;
    $('coinTag').classList.toggle('hidden', player.coins <= 0);
    $('raceCoins').textContent = player.coins;
    $('boostOverlay').classList.toggle('active', boost > 0.25);
    $('slowmoOverlay').classList.toggle('active', slowmo);
    $('hud').classList.toggle('tilt-mode', this.game.controlScheme === 'tilt');

    this.hudAccum += 1;
    if (this.hudAccum % 2 === 0) this.drawMinimap(racers, player, position);
  }

  cacheMinimap() {
    const track = this.game.track;
    if (!track) return;
    const pts = [];
    for (let i = 0; i <= 240; i++) {
      const f = track.getFrameAt(i / 240);
      pts.push({ x: f.pos.x, z: f.pos.z });
    }
    let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
    for (const p of pts) {
      minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x);
      minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z);
    }
    this.mapBounds = { minX, maxX, minZ, maxZ };
    this.mapPoints = pts;
  }

  mapXY(x, z) {
    const size = 220;
    const pad = 32;
    const b = this.mapBounds;
    const spanX = b.maxX - b.minX;
    const spanZ = b.maxZ - b.minZ;
    const scale = (size - pad * 2) / Math.max(spanX, spanZ);
    const cx = (b.minX + b.maxX) / 2;
    const cz = (b.minZ + b.maxZ) / 2;
    return {
      x: size / 2 + (x - cx) * scale,
      y: size / 2 + (z - cz) * scale,
    };
  }

  drawMinimap(racers, player, position) {
    const canvas = $('minimap');
    if (!canvas || !this.mapPoints) return;
    const ctx = canvas.getContext('2d');
    const size = 220;
    ctx.clearRect(0, 0, size, size);
    ctx.save();
    ctx.beginPath();
    ctx.arc(size / 2, size / 2, size / 2 - 1, 0, Math.PI * 2);
    ctx.clip();
    ctx.fillStyle = 'rgba(4,30,26,.42)';
    ctx.fillRect(0, 0, size, size);

    // Jungle haze
    const grad = ctx.createRadialGradient(size / 2, size / 2, 10, size / 2, size / 2, size / 2);
    grad.addColorStop(0, 'rgba(58,125,88,.18)');
    grad.addColorStop(1, 'rgba(10,48,38,.05)');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, size, size);

    const drawPath = (width, color) => {
      ctx.beginPath();
      this.mapPoints.forEach((p, i) => {
        const q = this.mapXY(p.x, p.z);
        if (i === 0) ctx.moveTo(q.x, q.y);
        else ctx.lineTo(q.x, q.y);
      });
      ctx.closePath();
      ctx.lineWidth = width;
      ctx.lineJoin = 'round';
      ctx.lineCap = 'round';
      ctx.strokeStyle = color;
      ctx.stroke();
    };
    drawPath(17, 'rgba(2,22,18,.55)');
    drawPath(12, '#2f6b5b');
    drawPath(7, '#72bda5');
    drawPath(2.5, 'rgba(210,255,232,.5)');

    // Checkpoint pips
    const track = this.game.track;
    if (track) {
      ctx.fillStyle = 'rgba(216,255,93,.65)';
      track.gateFractions.forEach((f) => {
        const fr = track.getFrameAt(f);
        const q = this.mapXY(fr.pos.x, fr.pos.z);
        ctx.beginPath();
        ctx.arc(q.x, q.y, 2, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    // Rival dots
    for (const r of racers) {
      if (r === player) continue;
      const q = this.mapXY(r.position.x, r.position.z);
      ctx.beginPath();
      ctx.arc(q.x, q.y, 3.6, 0, Math.PI * 2);
      ctx.fillStyle = r.profile?.c1 || '#ff8a3d';
      ctx.fill();
      ctx.strokeStyle = 'rgba(4,28,24,.8)';
      ctx.lineWidth = 1.5;
      ctx.stroke();
    }

    // Player arrow
    const q = this.mapXY(position.x, position.z);
    ctx.save();
    ctx.translate(q.x, q.y);
    const b = this.mapBounds;
    const spanX = b.maxX - b.minX;
    const spanZ = b.maxZ - b.minZ;
    const scale = (size - 64) / Math.max(spanX, spanZ);
    ctx.rotate(Math.atan2(Math.sin(player.yaw), Math.cos(player.yaw)));
    ctx.beginPath();
    ctx.moveTo(0, -7.5);
    ctx.lineTo(5, 5.5);
    ctx.lineTo(0, 2.6);
    ctx.lineTo(-5, 5.5);
    ctx.closePath();
    ctx.fillStyle = '#d8ff5d';
    ctx.shadowColor = 'rgba(216,255,93,.9)';
    ctx.shadowBlur = 8;
    ctx.fill();
    ctx.restore();
    ctx.restore();

    // Ring highlight
    ctx.beginPath();
    ctx.arc(size / 2, size / 2, size / 2 - 1, 0, Math.PI * 2);
    ctx.strokeStyle = 'rgba(216,255,93,.18)';
    ctx.lineWidth = 2;
    ctx.stroke();
  }

  showPause() { $('pause').classList.remove('hidden'); }
  hidePause() { $('pause').classList.add('hidden'); }

  showResults(data) {
    const place = ordinal(data.place);
    $('resultKicker').textContent = data.kicker || 'RACE COMPLETE';
    $('resultOrdinal').textContent = place;
    $('resultPlaceLabel').textContent = data.place === 1 ? 'CHAMPION' : 'PLACE';
    $('resultTitle').textContent = data.title;
    $('resultSub').textContent = data.sub;
    $('resultTime').textContent = formatTime(data.time);
    $('resultBestLap').textContent = formatTime(data.bestLap || 0);
    $('resultSpeed').textContent = Math.round(data.topSpeed);
    $('rewardPrize').textContent = `+${formatNumber(data.prize)}`;
    $('rewardCoins').textContent = `+${formatNumber(data.coins)}`;
    $('rewardMissions').textContent = data.missionProgress ?? '—';
    $('rewardTotal').textContent = formatNumber(data.total);
    $('resultNew').classList.toggle('hidden', !data.newBest);
    $('results').classList.remove('hidden');
    $('hud').classList.add('hidden');
    $('boostOverlay').classList.remove('active');
    $('slowmoOverlay').classList.remove('active');
    this.refreshMenu();
  }

  hideResults() { $('results').classList.add('hidden'); }

  toast(text, duration = 1900) {
    const el = $('toast');
    el.textContent = text;
    el.classList.remove('hidden');
    el.style.animation = 'none';
    void el.offsetHeight;
    el.style.animation = '';
    clearTimeout(this.toastTimer);
    this.toastTimer = setTimeout(() => el.classList.add('hidden'), duration);
  }

  // ---------------- Panels ----------------
  openPanel(html, kind) {
    this.panelOpen = true;
    this.activePanel = kind;
    $('panelCard').innerHTML = html;
    $('panelLayer').classList.remove('hidden');
  }

  closePanel() {
    if (!this.panelOpen) return;
    this.panelOpen = false;
    this.activePanel = null;
    $('panelLayer').classList.add('hidden');
    this.refreshMenu();
  }

  panelShell(kicker, title, bodyHtml) {
    return `
      <div class="panel-head">
        <div class="panel-head-left"><span class="panel-kicker">${kicker}</span><h2>${title}</h2></div>
        <div class="panel-head-right">
          <div class="pill-btn coin-pill"><span class="coin-glyph">●</span><span>${formatNumber(this.progress.coins)}</span></div>
          <button class="panel-close" data-close aria-label="Close">×</button>
        </div>
      </div>
      <div class="panel-body">${bodyHtml}</div>`;
  }

  onPanelClick(e) {
    const target = e.target.closest('[data-action], [data-select], [data-buy], [data-upgrade], [data-event], [data-claim], [data-claim-mission], [data-close], [data-setting], [data-quality], [data-toggle], [data-calibrate], [data-reset]');
    if (!target) return;
    this.game.audio?.ui?.();
    if (target.hasAttribute('data-close')) { this.closePanel(); return; }
    const action = target.getAttribute('data-action');
    if (action === 'open-career') return this.openCareer();
    if (action === 'open-garage') return this.openGarage();
    if (action === 'open-daily') return this.openDaily();
    if (action === 'claim-daily') {
      const r = this.progress.claimDaily();
      if (r) {
        this.game.audio.pickup('coin');
        this.toast(`Day ${r.day} gift claimed · +${r.amount} coins`);
        this.openDaily();
      }
      return;
    }
    if (target.hasAttribute('data-select')) {
      this.garagePreview = target.getAttribute('data-select');
      this.openGarage();
      return;
    }
    if (target.hasAttribute('data-buy')) {
      const id = target.getAttribute('data-buy');
      if (this.progress.buyJetSki(id)) {
        this.garagePreview = id;
        this.game.onJetSkiChanged();
        this.game.audio.pickup('nitro');
        this.toast(`${this.progress.jetSki(id).name} is yours`);
        this.openGarage();
      } else {
        this.toast('Not enough coins — win some races');
      }
      return;
    }
    if (target.hasAttribute('data-upgrade')) {
      const key = target.getAttribute('data-upgrade');
      if (this.progress.upgrade(this.garagePreview, key)) {
        this.game.onJetSkiChanged();
        this.game.audio.pickup('shield');
        this.openGarage();
      } else {
        this.toast('Not enough coins for that upgrade');
      }
      return;
    }
    if (target.hasAttribute('data-event')) {
      const id = target.getAttribute('data-event');
      const ev = CAREER_EVENTS.find((x) => x.id === id);
      if (ev && this.progress.isCareerUnlocked(ev)) {
        this.closePanel();
        this.game.startRace({ mode: 'career', event: ev });
      } else {
        this.toast('Finish the previous cup in the top 3 to unlock');
      }
      return;
    }
    if (target.hasAttribute('data-claim-mission')) {
      const id = target.getAttribute('data-claim-mission');
      const amount = this.progress.claimMission(id);
      if (amount) {
        this.game.audio.pickup('coin');
        this.toast(`Mission complete · +${amount} coins`);
        this.openDaily();
      }
      return;
    }
    if (target.hasAttribute('data-setting')) {
      const scheme = target.getAttribute('data-setting');
      this.game.setControlScheme(scheme).then((ok) => {
        if (!ok) this.toast('Tilt needs motion permission on this device');
        this.openSettings(this.activePanel === 'settings-pause');
      });
      return;
    }
    if (target.hasAttribute('data-quality')) {
      this.progress.updateSettings({ quality: target.getAttribute('data-quality') });
      this.game.setQuality(this.progress.settings.quality);
      this.openSettings(this.activePanel === 'settings-pause');
      return;
    }
    if (target.hasAttribute('data-toggle')) {
      const key = target.getAttribute('data-toggle');
      const val = !this.progress.settings[key];
      this.progress.updateSettings({ [key]: val });
      if (key === 'sound') this.game.audio.setMuted(!val);
      if (key === 'haptics' && val && navigator.vibrate) navigator.vibrate(30);
      this.openSettings(this.activePanel === 'settings-pause');
      return;
    }
    if (target.hasAttribute('data-calibrate')) {
      this.game.input.calibrateTilt();
      this.toast('Tilt centre calibrated — hold still');
      return;
    }
    if (target.hasAttribute('data-reset')) {
      if (window.confirm('Reset all coins, rides, upgrades and progress?')) {
        this.progress.reset();
        this.game.onJetSkiChanged();
        this.closePanel();
        this.refreshMenu();
        this.toast('Progress reset');
      }
      return;
    }
  }

  openCareer() {
    const events = CAREER_EVENTS.map((ev) => {
      const unlocked = this.progress.isCareerUnlocked(ev);
      const best = this.progress.save.career[ev.id];
      const p = PALETTES[ev.palette] || PALETTES.morning;
      const thumb = `linear-gradient(150deg, ${p.skyMid}, ${p.waterDeep} 70%, #082f28)`;
      return `
        <div class="career-row ${unlocked ? '' : 'locked'}">
          <div class="career-thumb" style="--thumb:${thumb}">
            <b>${ev.tag.split(' ')[1] || ev.tag}</b>
          </div>
          <div class="career-info">
            <h3>${ev.name}</h3>
            <p>${ev.desc}</p>
            <div class="career-tags">
              <span>${ev.laps} LAPS</span><span>${ev.rivals} RIVALS</span>
              <span class="gold">${formatNumber(ev.prize)} COINS</span>
              ${best ? `<span>BEST ${ordinal(best.place)}</span>` : ''}
            </div>
          </div>
          <div class="career-action">
            ${unlocked
              ? `<button class="btn btn-primary" data-event="${ev.id}">RACE</button><small>${ev.circuit}</small>`
              : `<span class="career-lock">🔒 TOP 3 PREVIOUS</span>`}
          </div>
        </div>`;
    }).join('');
    this.openPanel(this.panelShell('CAREER MODE', 'River Cups', `
      <p class="panel-copy">Four legs down the wild river. Finish in the top three to open the next cup. Faster rides and smarter lines will be rewarded.</p>
      <div class="career-list">${events}</div>
      <p class="garage-note">Career prizes are paid out on every finish. Your best placement is kept.</p>
    `), 'career');
  }

  openGarage() {
    const p = this.progress;
    if (!p.isOwned(this.garagePreview)) this.garagePreview = p.save.selected;
    const ski = p.jetSki(this.garagePreview);
    const owned = p.isOwned(ski.id);
    const selected = p.save.selected === ski.id;
    const stats = p.effectiveStats(ski.id);
    const ups = p.upgradesFor(ski.id);
    const list = JETSKIS.map((j) => {
      const isOwned = p.isOwned(j.id);
      const equip = p.save.selected === j.id;
      return `
        <button class="ski-item ${this.garagePreview === j.id ? 'active' : ''}" data-select="${j.id}" style="--c1:${j.c1};--c2:${j.c2}">
          <span class="ski-swatch" style="--c1:${j.c1};--c2:${j.c2}"></span>
          <span class="ski-item-text"><b>${j.name}</b><span>${j.tag}</span></span>
          ${!isOwned ? `<span class="lock-price">● ${formatNumber(j.price)}</span>` : equip ? '<span class="equipped">EQUIPPED</span>' : ''}
        </button>`;
    }).join('');
    const statRows = ['speed', 'handling', 'boost'].map((key) => `
      <div class="stat-line">
        <span>${key === 'boost' ? 'BOOST' : key.toUpperCase()}</span>
        <div class="stat-track"><i style="width:${Math.round(stats[key])}%"></i></div>
        <b>${Math.round(stats[key])}</b>
      </div>`).join('');
    const upgradeRows = ['speed', 'handling', 'boost'].map((key) => {
      const level = ups[key] || 0;
      const cost = p.upgradeCost(ski.id, key);
      const pips = Array.from({ length: 5 }, (_, i) => `<i class="${i < level ? 'on' : ''}"></i>`).join('');
      return `
        <div class="upgrade-row">
          <div class="upgrade-info">
            <b>${upgradeLabels[key]}</b>
            <div class="upgrade-pips">${pips}</div>
            <small>Level ${level}/5 · +2.3 stat</small>
          </div>
          ${owned
            ? cost == null
              ? '<button class="upgrade-btn maxed" disabled>MAXED</button>'
              : `<button class="upgrade-btn" data-upgrade="${key}" ${p.coins < cost ? 'disabled' : ''}>● ${formatNumber(cost)}</button>`
            : ''}
        </div>`;
    }).join('');
    const buyRow = !owned
      ? `<div class="buy-row">
           <button class="btn btn-primary" data-buy="${ski.id}" ${p.coins < ski.price ? 'disabled' : ''}><span>BUY · ${formatNumber(ski.price)} COINS</span></button>
         </div>`
      : selected
        ? `<div class="buy-row"><button class="btn btn-glass" disabled>EQUIPPED</button></div>`
        : `<div class="buy-row"><button class="btn btn-primary" data-select="${ski.id}" data-action="equip"><span>EQUIP THIS RIDE</span></button></div>`;

    this.openPanel(this.panelShell('GARAGE', 'Pick your ride', `
      <div class="garage-layout">
        <div>
          <p class="section-label">Jetski fleet</p>
          <div class="ski-list">${list}</div>
          <p class="garage-note">Every hull has its own soul. Upgrades are permanent and carry into every mode.</p>
        </div>
        <div class="garage-detail">
          <div class="ski-preview" style="--c1:${ski.c1};--c2:${ski.c2};--accent:${ski.accent};--trim:${ski.trim};--rider:${ski.c1}">
            ${jetskiSVG(ski)}
            <div class="preview-badge">${owned ? 'OWNED' : 'LOCKED'}</div>
            <div class="preview-name">${ski.name}</div>
          </div>
          <p class="panel-copy" style="margin-bottom:10px !important">${ski.copy}</p>
          <div class="stat-grid">${statRows}</div>
          <p class="section-label">Upgrades</p>
          ${upgradeRows}
          ${buyRow}
        </div>
      </div>
    `), 'garage');
  }

  openDaily() {
    const p = this.progress;
    const day = p.dailyDayIndex();
    const available = p.dailyAvailable();
    const streak = p.save.daily.streak || 0;
    const rewards = [100, 150, 200, 250, 300, 400, 600];
    const dayCards = rewards.map((amount, i) => {
      const claimed = available ? i + 1 < day : i + 1 <= streak;
      return `
        <div class="day-card ${i + 1 === day && available ? 'today' : ''} ${claimed ? 'claimed' : ''}">
          <span>DAY ${i + 1}</span>
          <span class="coin-glyph">●</span>
          <b>${amount}</b>
        </div>`;
    }).join('');
    const missions = p.missions.map((m) => {
      const done = m.progress >= m.target;
      const pct = Math.min(100, Math.round((m.progress / m.target) * 100));
      return `
        <div class="mission-item">
          <div class="mission-icon">${m.icon}</div>
          <div class="mission-text">
            <b>${m.name}</b>
            <div class="mission-progress"><i style="width:${pct}%"></i></div>
            <small>${m.desc.replace('{target}', m.target)} · ${Math.min(m.progress, m.target)}/${m.target}</small>
          </div>
          <div class="mission-reward">
            <span>+${m.reward}</span>
            ${m.claimed
              ? '<button disabled>CLAIMED</button>'
              : `<button data-claim-mission="${m.id}" ${done ? '' : 'disabled'}>${done ? 'CLAIM' : 'LOCKED'}</button>`}
          </div>
        </div>`;
    }).join('');
    this.openPanel(this.panelShell('DAILY CURRENT', 'River rewards', `
      <p class="panel-copy">The river pays its regulars. Claim your daily chest, then chase today’s three objectives in any race mode.</p>
      <div class="daily-rewards">${dayCards}</div>
      <div class="daily-cta">
        <div class="daily-cta-info">
          <b>${available ? `Day ${day} chest is ready` : 'Chest claimed today'}</b>
          <span>${available ? 'Come back tomorrow to keep the streak alive.' : `${streak}-day streak · resets only if you miss a day.`}</span>
        </div>
        ${available
          ? `<button class="btn btn-primary" data-action="claim-daily" style="min-height:42px;padding:0 16px;font-size:10px"><span>CLAIM +${rewards[day - 1]}</span></button>`
          : `<button class="btn btn-glass" disabled style="min-height:42px;padding:0 16px;font-size:10px">CLAIMED</button>`}
      </div>
      <p class="section-label">Today’s missions</p>
      <div class="mission-list">${missions}</div>
    `), 'daily');
  }

  openSettings(fromPause = false) {
    const s = this.progress.settings;
    const seg = (key, values) => values.map((v) => `<button data-${key}="${v.value}" class="${s[key === 'control' ? 'control' : 'quality'] === v.value ? 'active' : ''}">${v.label}</button>`).join('');
    this.openPanel(this.panelShell('SETTINGS', 'Tune the ride', `
      <div class="settings-grid">
        <div class="setting-row">
          <div class="setting-label"><b>Steering</b><span>Tilt uses your gyroscope. Joystick is thumb-first.</span></div>
          <div class="segmented">${seg('setting', [{ value: 'joystick', label: 'JOYSTICK' }, { value: 'tilt', label: 'TILT' }])}</div>
        </div>
        <div class="setting-row">
          <div class="setting-label"><b>Quality</b><span>Auto adapts resolution to hold 60 FPS.</span></div>
          <div class="segmented">${seg('quality', [{ value: 'auto', label: 'AUTO' }, { value: 'high', label: 'HIGH' }, { value: 'low', label: 'LOW' }])}</div>
        </div>
        <div class="setting-row">
          <div class="setting-label"><b>Sound</b><span>Engine, water and tropical ambience.</span></div>
          <button class="toggle ${s.sound ? 'on' : ''}" data-toggle="sound" aria-label="Toggle sound"></button>
        </div>
        <div class="setting-row">
          <div class="setting-label"><b>Haptics</b><span>Impact and boost vibration (supported devices).</span></div>
          <button class="toggle ${s.haptics ? 'on' : ''}" data-toggle="haptics" aria-label="Toggle haptics"></button>
        </div>
        <div class="setting-row">
          <div class="setting-label"><b>Tilt calibration</b><span>Hold your phone naturally, then tap.</span></div>
          <button class="upgrade-btn" data-calibrate style="min-height:34px">CALIBRATE</button>
        </div>
      </div>
      <p class="settings-note">Desktop: A / D or arrows to steer, Shift or N for nitro, Space to jump, S to brake. P or Esc pauses.</p>
      <button class="danger-link" data-reset>Reset all progress</button>
    `), fromPause ? 'settings-pause' : 'settings');
  }
}

import * as THREE from 'three';
import { Track, waveHeight } from '../world/Track.js';
import { Water } from '../world/Water.js';
import { Environment } from '../world/Environment.js';
import { RaceObjects } from '../world/RaceObjects.js';
import { JetSki } from './JetSki.js';
import { Player } from './Player.js';
import { Opponent, PROFILES } from './AI.js';
import { Effects } from './Effects.js';
import { AudioEngine } from './Audio.js';
import { Input } from './Input.js';
import { UI } from '../ui/UI.js';
import { Progress } from '../core/Progress.js';
import { PALETTES, clamp, damp, formatTime, lerp, ordinal } from '../core/utils.js';

const UP = new THREE.Vector3(0, 1, 0);
const TMP_A = new THREE.Vector3();
const TMP_B = new THREE.Vector3();
const TMP_C = new THREE.Vector3();

function wrappedCrossed(a, b, target) {
  const forward = ((b - a) % 1 + 1) % 1;
  const toTarget = ((target - a) % 1 + 1) % 1;
  return toTarget > 0 && toTarget <= forward + 0.00001;
}

export class Game {
  constructor() {
    this.canvas = document.getElementById('game-canvas');
    this.progress = new Progress();
    this.state = 'boot';
    this.mode = 'quick';
    this.careerEvent = null;
    this.laps = 3;
    this.rivals = 5;
    this.currentRace = null;
    this.controlScheme = this.progress.settings.control;
    this.quality = this.progress.settings.quality;
    this.worldTime = 0;
    this.menuTime = 0;
    this.raceTime = 0;
    this.lapStart = 0;
    this.lapTimes = [];
    this.timeScale = 1;
    this.slowmoTimer = 0;
    this.shake = 0;
    this.resultDelay = 0;
    this.pendingResult = null;
    this.playerPlace = 1;
    this.hudTimer = 0;
    this.menuLook = new THREE.Vector3();
    this.cameraLook = new THREE.Vector3();
    this.fpsAccum = 0;
    this.fpsFrames = 0;
    this.fps = 60;
    this.pixelRatio = 1;
    this.qualityScale = 1;
    this.startingRace = false;
    this.finishOrbit = 0;

    this.setupRenderer();
    this.setupWorld();
    this.setupRacers();
    this.setupServices();
    this.setupCamera();
    this.setupEvents();

    this.enterMenu(true);
    this.setQuality(this.quality);
    this.resize();
    window.addEventListener('resize', () => this.resize());
    window.addEventListener('orientationchange', () => setTimeout(() => this.resize(), 250));
    document.addEventListener('visibilitychange', () => {
      if (document.hidden && (this.state === 'racing' || this.state === 'countdown')) this.pause();
    });

    this.clock = new THREE.Clock();
    this.startLoop();

    const bar = document.getElementById('loadingBar');
    if (bar) bar.style.width = '100%';
    setTimeout(() => {
      document.getElementById('loading')?.classList.add('hidden');
      this.ui.showMenu();
      this.ui.hideResults();
    }, 550);

    window.__riverRush = this;
  }

  setupRenderer() {
    this.renderer = new THREE.WebGLRenderer({
      canvas: this.canvas,
      antialias: true,
      powerPreference: 'high-performance',
      stencil: false,
      alpha: false,
    });
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.04;
    this.renderer.setClearColor('#0a2c27');
    this.scene = new THREE.Scene();
    this.scene.fog = new THREE.FogExp2('#b9dfc6', 0.00165);
    this.camera = new THREE.PerspectiveCamera(62, 1, 0.1, 2400);
  }

  setupWorld() {
    this.track = new Track();
    this.effects = new Effects(this.scene);
    this.water = new Water(this.track);
    this.scene.add(this.water.group);
    this.environment = new Environment(this.scene, this.track);
    this.objects = new RaceObjects(this.scene, this.track);
    this.applyPalette('morning');
  }

  playerModel() {
    const ski = this.progress.selectedJetSki();
    return new JetSki({
      c1: ski.c1,
      c2: ski.c2,
      accent: ski.accent,
      trim: ski.trim,
      rider: true,
      riderColor: ski.c1,
      helmet: '#f8f5e6',
    });
  }

  setupRacers() {
    this.player = new Player(this.track, this.effects);
    this.player.applyPerformance(this.progress.performance());
    this.player.setModel(this.playerModel());
    this.player.model.addTo(this.scene);
    this.player.reset(this.laps);

    this.opponents = [];
    for (let i = 0; i < 5; i++) {
      const p = PROFILES[i];
      const model = new JetSki({
        c1: p.c1, c2: p.c2, accent: p.accent, trim: p.trim,
        rider: true, riderColor: p.riderColor, helmet: p.helmet,
      });
      model.addTo(this.scene);
      model.group.visible = false;
      model.shadow.visible = false;
      const ai = new Opponent(i, this.track, this.effects, model);
      ai.reset(this.laps, 1, i);
      this.opponents.push(ai);
    }
  }

  setupServices() {
    this.input = new Input({ onPause: () => this.pause() });
    this.audio = new AudioEngine(this.progress);
    this.ui = new UI(this);

    this.player.events = {
      onCheckpoint: (n, total) => {
        this.audio.ui();
        this.ui.checkpointToast(`CHECKPOINT ${n}/${total}`);
        this.haptic(10);
      },
      onLap: (lap, lapTime) => {
        if (lap >= this.laps) return;
        this.lapTimes.push(lapTime);
        this.audio.lap();
        this.ui.showRaceMessage(`LAP ${lap + 1}`, `LAP TIME ${formatTime(lapTime)}`, 1500);
      },
      onFinish: (time) => this.finishRace(time),
      onHit: () => {
        this.shake = Math.max(this.shake, 0.7);
        this.haptic([40, 30, 70]);
        this.audio.hit();
        this.ui.showRaceMessage('WIPEOUT', 'SHAKE IT OFF', 900);
      },
      onShieldBreak: () => {
        this.shake = Math.max(this.shake, 0.35);
        this.haptic([20, 25, 20]);
        this.audio.shieldBreak();
        this.ui.showRaceMessage('SHIELD SAVED', 'ONE HIT ABSORBED', 1000);
      },
      onBoost: () => {
        this.audio.boost();
        this.haptic(35);
      },
      onSuperBoost: () => {
        this.audio.boost();
        this.haptic([20, 20, 50]);
        this.ui.showRaceMessage('SUPER BOOST', 'FULL TANK UNLEASHED', 900, true);
      },
      onJump: (big) => {
        this.audio.jump();
        if (big) {
          this.shake = Math.max(this.shake, 0.3);
          this.ui.showRaceMessage('BIG AIR', 'SLOW MOTION', 1100, true);
        }
      },
      onLand: (impact) => {
        this.audio.land(clamp(impact / 8, 0.4, 1.4));
        this.haptic(20);
        this.shake = Math.max(this.shake, clamp(impact * 0.035, 0.1, 0.45));
      },
      onDriftStart: () => {
        this.ui.toast('DRIFT · NITRO CHARGING', 1100);
      },
      onEdge: () => {
        this.haptic(8);
      },
    };
  }

  setupCamera() {
    this.cameraLook.set(0, 0, 0);
    this.fovTarget = 62;
    this.camera.position.set(0, 8, 15);
  }

  setupEvents() {
    const onFirst = () => this.audio.unlock();
    window.addEventListener('pointerdown', onFirst, { once: true, capture: true });
  }

  // ------------------------------------------------------------------
  // State transitions
  // ------------------------------------------------------------------
  async startRace({ mode = 'quick', event = null } = {}) {
    if (this.startingRace) return;
    this.startingRace = true;
    this.audio.unlock();
    this.ui.closePanel();
    this.ui.hideResults();
    this.ui.hidePause();
    this.ui.hideRaceMessage();
    this.mode = mode;
    this.careerEvent = mode === 'career' ? event : null;
    this.currentRace = { mode, event: this.careerEvent };
    this.laps = 3;
    this.rivals = mode === 'time' ? 0 : 5;

    if (this.controlScheme === 'tilt') {
      const ok = await this.input.enableTilt();
      if (!ok) {
        this.controlScheme = 'joystick';
        this.progress.updateSettings({ control: 'joystick' });
        this.input.setControlScheme('joystick');
        this.ui.toast('Motion unavailable — joystick enabled');
      }
    }

    const palette = mode === 'career' && event ? event.palette : mode === 'time' ? 'sunset' : 'morning';
    this.applyPalette(palette);
    this.effects.clear?.();
    this.objects.reset();
    this.lapTimes = [];
    this.raceTime = 0;
    this.lapStart = 0;
    this.lapTimes = [];
    this.slowmoTimer = 0;
    this.timeScale = 1;
    this.shake = 0;
    this.pendingResult = null;
    this.finishOrbit = 0;

    this.player.applyPerformance(this.progress.performance());
    this.player.reset(this.laps);
    this.player.model.group.visible = true;
    this.player.model.shadow.visible = true;
    this.player.model.setTransform(this.player.position, this.player.yaw, waveHeight(this.player.position.x, this.player.position.z, this.worldTime), this.worldTime, { speed: 0, idle: true });

    const difficulty = mode === 'career' && event ? 1.35 + event.palette.length * 0.05 : 1;
    for (let i = 0; i < this.opponents.length; i++) {
      const ai = this.opponents[i];
      ai.reset(this.laps, difficulty, i);
      const show = i < this.rivals;
      ai.model.group.visible = show;
      ai.model.shadow.visible = show;
      if (show) {
        const f = this.track.getFrameAt(ai.startT);
        ai.model.setTransform(ai.position, ai.yaw, waveHeight(ai.position.x, ai.position.z, this.worldTime), this.worldTime, { speed: 0, idle: true });
      }
    }

    this.ui.showRaceHUD(mode, this.laps, this.rivals, this.controlScheme);
    this.ui.showCountdown();
    this.ui.updateHUD(this.buildHUDState());
    this.ui.updateCountdown(3, 'HOLD THE LINE');
    this.environment.setStartLights(3);
    this.input.setControlScheme(this.controlScheme);
    this.input.setEnabled(false);
    this.state = 'countdown';
    this.countdown = 3.55;
    this.countdownStage = 3;
    this.goShown = false;
    this.audio.setPaused(false);
    this.snapCountdownCamera();
    this.startingRace = false;
  }

  beginRace() {
    if (this.state !== 'countdown') return;
    this.state = 'racing';
    this.raceTime = 0;
    this.player.active = true;
    this.player.lapStartTime = 0;
    this.input.reset();
    this.input.setEnabled(true);
    this.environment.setStartLights(0);
    this.ui.updateCountdown('GO!', 'SEND IT');
    this.audio.countdown(0);
    this.haptic([18, 25, 45]);
    this.ui.showRaceMessage('GO!', '', 850, true);
    clearTimeout(this.goTimer);
    this.goTimer = setTimeout(() => this.ui.hideCountdown(), 820);
  }

  pause() {
    if (this.state !== 'racing' && this.state !== 'countdown') return;
    this.pausedFrom = this.state;
    this.state = 'paused';
    this.input.setEnabled(false);
    this.audio.setPaused(true);
    this.ui.showPause();
  }

  resume() {
    if (this.state !== 'paused') return;
    this.state = this.pausedFrom || 'racing';
    this.ui.hidePause();
    this.ui.closePanel();
    this.input.setEnabled(this.state === 'racing');
    this.audio.setPaused(false);
    this.clock.getDelta();
  }

  restartRace() {
    const race = this.currentRace;
    this.ui.hidePause();
    this.ui.hideResults();
    if (race) this.startRace(race);
  }

  quitToMenu() {
    clearTimeout(this.goTimer);
    this.state = 'menu';
    this.player.active = false;
    this.player.reset(this.laps);
    this.player.model.group.visible = true;
    this.player.model.shadow.visible = true;
    this.input.setEnabled(false);
    this.input.reset();
    this.ui.hidePause();
    this.ui.hideResults();
    this.ui.hideCountdown();
    this.ui.hideRaceMessage();
    this.ui.showMenu();
    this.ui.closePanel();
    this.ui.hideRaceMessage();
    this.audio.setPaused(false);
    for (const ai of this.opponents) {
      ai.model.group.visible = false;
      ai.model.shadow.visible = false;
    }
    this.environment.setStartLights(0);
    this.applyPalette('morning');
    this.ui.refreshMenu();
    this.menuTime = 0;
    this.scene.fog.density = 0.00165;
  }

  enterMenu(first = false) {
    this.state = 'menu';
    this.input?.setEnabled(false);
    this.player.active = false;
    this.player.reset(this.laps);
    this.player.model.group.visible = true;
    this.player.model.shadow.visible = true;
    for (const ai of this.opponents) {
      ai.model.group.visible = false;
      ai.model.shadow.visible = false;
    }
    this.ui?.showMenu();
    this.applyPalette('morning');
    if (first) {
      this.menuTime = 0;
      this.snapMenuCamera();
    }
  }

  async setControlScheme(scheme) {
    if (scheme === 'tilt') {
      const ok = await this.input.enableTilt();
      if (!ok) {
        this.progress.updateSettings({ control: 'joystick' });
        this.controlScheme = 'joystick';
        this.input.setControlScheme('joystick');
        this.ui.toast('Motion access was not granted — joystick stays on');
        return false;
      }
    }
    this.controlScheme = scheme;
    this.input.setControlScheme(scheme);
    this.progress.updateSettings({ control: scheme });
    this.ui.refreshMenu();
    return true;
  }

  setQuality(q) {
    this.quality = q;
    this.qualityScale = 1;
    this.applyQuality();
  }

  applyQuality() {
    let maxDpr = Math.min(window.devicePixelRatio || 1, 1.75);
    if (this.quality === 'high') maxDpr = Math.min(window.devicePixelRatio || 1, 2);
    if (this.quality === 'low') maxDpr = 1;
    this.maxDpr = maxDpr;
    this.pixelRatio = Math.max(0.85, maxDpr * this.qualityScale);
    this.renderer.setPixelRatio(this.pixelRatio);
    this.renderer.setSize(window.innerWidth, window.innerHeight, false);
    this.effects.setPixelScale(105 * Math.min(this.pixelRatio, 1.8));
    this.environment.cloudMesh.count = this.quality === 'low' ? 16 : 46;
    this.scene.fog.density = this.quality === 'low' ? 0.0022 : 0.00165;
    if (this.quality === 'high') this.scene.fog.density = 0.0015;
  }

  resize() {
    this.isPortrait = window.innerHeight > window.innerWidth * 1.02;
    this.camera.aspect = window.innerWidth / window.innerHeight;
    this.baseFov = this.isPortrait ? 70 : 62;
    this.camera.updateProjectionMatrix();
    this.applyQuality();
    this.ui?.cacheMinimap();
  }

  applyPalette(name) {
    const p = PALETTES[name] || PALETTES.morning;
    this.paletteName = name;
    this.palette = p;
    this.water.applyPalette(p);
    this.environment.applyPalette(name);
    this.scene.fog.color.set(p.fog);
    this.scene.fog.density = this.quality === 'low' ? 0.0022 : 0.00165;
    this.renderer.toneMappingExposure = name === 'sunset' ? 1.11 : name === 'storm' ? 0.94 : 1.04;
  }

  onJetSkiChanged() {
    if (this.player.model) {
      this.player.model.dispose(this.scene);
    }
    const model = this.playerModel();
    model.addTo(this.scene);
    model.group.visible = true;
    model.shadow.visible = true;
    this.player.setModel(model);
    this.player.applyPerformance(this.progress.performance());
    this.player.model.setTransform(this.player.position, this.player.yaw, this.player.waterY, this.worldTime, { speed: 0, idle: this.state === 'menu' });
    this.ui.refreshMenu();
  }

  // ------------------------------------------------------------------
  // HUD state helpers
  // ------------------------------------------------------------------
  getStandings() {
    const list = [this.player, ...this.opponents];
    list.sort((a, b) => {
      const af = a.finished;
      const bf = b.finished;
      if (af && bf) return a.finishTime - b.finishTime;
      if (af) return -1;
      if (bf) return 1;
      return b.raceDist - a.raceDist;
    });
    return list;
  }

  buildHUDState() {
    const standings = this.getStandings();
    this.playerPlace = standings.indexOf(this.player) + 1;
    return {
      player: this.player,
      position: this.playerPlace,
      racers: standings,
      time: this.raceTime,
      lapTime: Math.max(0, this.raceTime - this.player.lapStartTime),
      mode: this.mode,
      boost: this.player.boostVisual,
      slowmo: this.timeScale < 0.8,
    };
  }

  // ------------------------------------------------------------------
  // Game loop
  // ------------------------------------------------------------------
  startLoop() {
    const loop = () => {
      this.raf = requestAnimationFrame(loop);
      const raw = Math.min(this.clock.getDelta(), 0.05);
      this.tick(raw);
      this.renderer.render(this.scene, this.camera);
    };
    loop();
  }

  tick(rawDt) {
    this.menuTime += rawDt;
    this.fpsAccum += rawDt;
    this.fpsFrames++;
    if (this.fpsAccum > 2.4) {
      this.fps = this.fpsFrames / this.fpsAccum;
      this.fpsAccum = 0;
      this.fpsFrames = 0;
      if (this.quality === 'auto' && this.state === 'racing') {
        if (this.fps < 48 && this.qualityScale > 0.82) {
          this.qualityScale = Math.max(0.82, this.qualityScale - 0.06);
          this.applyQuality();
        } else if (this.fps > 57 && this.qualityScale < 1) {
          this.qualityScale = Math.min(1, this.qualityScale + 0.04);
          this.applyQuality();
        }
      }
    }

    this.timeScale = this.slowmoTimer > 0
      ? damp(this.timeScale, 0.42, 7, rawDt)
      : damp(this.timeScale, 1, 4, rawDt);
    this.slowmoTimer = Math.max(0, this.slowmoTimer - rawDt);
    const dt = rawDt * this.timeScale;
    this.worldTime += rawDt * (this.slowmoTimer > 0 ? 0.6 : 1);
    this.shake = Math.max(0, this.shake - rawDt * 1.8);

    this.input.update(rawDt);

    if (this.state === 'menu') {
      this.updateMenu(rawDt);
    } else if (this.state === 'countdown') {
      this.updateCountdown(rawDt);
      this.updateWorldIdle(rawDt);
      this.updateCamera(rawDt);
      this.ui.updateHUD(this.buildHUDState());
      this.hudTimer = 0;
      this.audio.update(rawDt, { speed: 0, maxSpeed: this.player.maxSpeed, active: false, opponents: this.opponents, player: this.player });
    } else if (this.state === 'racing') {
      this.updateRace(dt, rawDt);
    } else if (this.state === 'finished') {
      this.updateFinished(rawDt);
    } else if (this.state === 'results') {
      this.updateResults(rawDt);
    } else if (this.state === 'paused') {
      this.water.update(this.worldTime);
    }

    this.effects.update(this.state === 'paused' ? 0 : dt);
  }

  updateMenu(dt) {
    this.water.update(this.worldTime);
    this.environment.update(this.worldTime, dt);
    this.objects.update(dt, this.worldTime);

    const waterY = waveHeight(this.player.position.x, this.player.position.z, this.worldTime);
    this.player.waterY = waterY;
    this.player.model.setTransform(
      this.player.position, this.player.yaw, waterY, this.worldTime,
      { speed: 0, steer: 0, drift: 0, boost: 0, airborne: false, shield: false, stun: 0, idle: true },
    );
    this.updateMenuCamera(dt);
    this.audio.update(dt, { speed: 0, maxSpeed: this.player.maxSpeed, active: false, opponents: [], player: this.player });
  }

  updateCountdown(rawDt) {
    this.countdown -= rawDt;
    const remain = this.countdown;
    let stage = 3;
    if (remain <= 2.55) stage = 2;
    if (remain <= 1.55) stage = 1;
    if (remain <= 0.55) stage = 0;
    if (stage !== this.countdownStage) {
      this.countdownStage = stage;
      if (stage > 0) {
        this.ui.updateCountdown(stage, stage === 1 ? 'HOLD THE LINE' : 'READY');
        this.environment.setStartLights(stage);
        this.audio.countdown(stage);
        this.ui.haptic?.();
      } else {
        this.beginRace();
      }
    }
    if (stage > 0) {
      this.environment.setStartLights(stage);
    }
    this.water.update(this.worldTime);
    this.environment.update(this.worldTime, rawDt);
    this.objects.update(rawDt, this.worldTime);
    this.updateWorldIdle(rawDt);
    // Sparkle the grid with water bob.
    for (let i = 0; i < this.rivals; i++) {
      const ai = this.opponents[i];
      if (!ai.model.group.visible) continue;
      const wy = waveHeight(ai.position.x, ai.position.z, this.worldTime);
      ai.model.setTransform(ai.position, ai.yaw, wy, this.worldTime, { speed: 0, idle: true });
    }
  }

  updateWorldIdle(dt) {
    this.player.model.setTransform(
      this.player.position, this.player.yaw,
      waveHeight(this.player.position.x, this.player.position.z, this.worldTime),
      this.worldTime, { speed: 0, steer: 0, drift: 0, boost: 0, airborne: false, shield: false, stun: 0, idle: true },
    );
  }

  updateRace(dt, rawDt) {
    this.raceTime += rawDt;
    this.water.update(this.worldTime);
    this.environment.update(this.worldTime, rawDt);
    this.objects.update(dt, this.worldTime);

    // Player
    this.player.update(dt, this.input, this.worldTime, this.raceTime);

    // Ramp launches (crossing forward).
    if (this.player.speed > 10 && !this.player.airborne) {
      for (const ramp of this.objects.ramps) {
        if (wrappedCrossed(this.player.prevT, this.player.lastT, ramp.t) && Math.abs(this.player.lateral) < ramp.halfWidth) {
          if (this.player.jump(7.6, true)) {
            this.slowmoTimer = 0.8;
            this.shake = Math.max(this.shake, 0.25);
            this.audio.jump();
            this.haptic(30);
          }
          break;
        }
      }
    }

    // Swipe / space jump.
    if (this.input.consumeJump() && !this.player.airborne) {
      this.player.jump(6.2, false);
    }

    // Obstacle collisions.
    if (!this.player.airborne || this.player.elevation < 1.5) {
      const hit = this.objects.collide(this.player.position, this.player.airborne && this.player.elevation > 1.5);
      if (hit && this.player.invuln <= 0) {
        const result = this.player.hitObstacle(hit);
        if (hit.type === 'whirlpool') {
          this.player.stun = Math.min(this.player.stun, 0.4);
        }
      }
    }

    // Power-ups.
    const pickup = this.objects.collect(this.player.position, 2.6);
    if (pickup) {
      const type = this.player.givePickup(pickup.type);
      this.effects.pickupBurst(pickup.position.x, waveHeight(pickup.position.x, pickup.position.z, this.worldTime) + 1.1, pickup.position.z, pickup.type);
      this.audio.pickup(type);
      this.haptic(type === 'shield' ? [15, 20, 30] : 18);
      if (type === 'nitro') this.ui.toast('NITRO +32', 1000);
      else if (type === 'shield') {
        this.ui.toast('SHIELD · 8 SECONDS', 1200);
        this.haptic(20);
      }
    }

    // Rivals.
    for (let i = 0; i < this.rivals; i++) {
      this.opponents[i].update(dt, this.worldTime, this.player, { time: this.raceTime, objects: this.objects });
    }

    // Nitro-ready cue.
    const full = this.player.nitro >= 99;
    if (full && !this.nitroWasFull) {
      this.audio.tone?.(880, 0.2, 'sine', 0.05, 1200);
      this.ui.toast('NITRO READY · TAP TO UNLEASH', 1300);
    }
    this.nitroWasFull = full;

    this.updateCamera(rawDt);

    this.hudTimer -= rawDt;
    if (this.hudTimer <= 0) {
      this.hudTimer = 1 / 15;
      this.ui.updateHUD(this.buildHUDState());
    }

    this.audio.update(rawDt, {
      speed: this.player.speed,
      maxSpeed: this.player.maxSpeed,
      boosting: this.player.boosting,
      active: true,
      opponents: this.opponents,
      player: this.player,
    });

    if (this.player.finished && this.state === 'racing') this.finishRace(this.player.finishTime);
  }

  updateFinished(rawDt) {
    this.resultDelay -= rawDt;
    this.water.update(this.worldTime);
    this.environment.update(this.worldTime, rawDt);
    this.objects.update(rawDt, this.worldTime);
    this.finishOrbit += rawDt * 0.28;
    this.updateOrbitCamera(this.finishOrbit, false);
    this.audio.update(rawDt, {
      speed: 0, maxSpeed: this.player.maxSpeed, active: false,
      opponents: this.opponents, player: this.player,
    });
    if (this.resultDelay <= 0 && this.state === 'finished') {
      this.state = 'results';
      this.ui.showResults(this.pendingResult);
    }
  }

  updateResults(rawDt) {
    this.water.update(this.worldTime);
    this.environment.update(this.worldTime, rawDt);
    this.objects.update(rawDt, this.worldTime);
    this.finishOrbit += rawDt * 0.18;
    this.updateOrbitCamera(this.finishOrbit, true);
    this.audio.update(rawDt, {
      speed: 0, maxSpeed: this.player.maxSpeed, active: false,
      opponents: this.opponents, player: this.player,
    });
  }

  finishRace(time) {
    if (this.state === 'finished' || this.state === 'results') return;
    this.state = 'finished';
    this.player.active = false;
    this.input.setEnabled(false);
    this.ui.hideRaceMessage();
    this.ui.showRaceMessage('FINISH', '', 1200, true);
    this.resultDelay = 1.75;
    this.slowmoTimer = 0.5;
    this.finishOrbit = 0;

    const standings = this.getStandings();
    let place = standings.indexOf(this.player) + 1;
    if (this.mode === 'time') place = 1;

    const timeSec = time || this.raceTime;
    const bestLap = this.player.bestLap || 0;
    const topSpeed = this.player.topSpeedSeen || 0;
    const coinsCollected = this.player.coins;
    const drift = this.player.driftDistance;
    const boosts = Math.round(this.player.boostCount);
    const jumps = this.player.jumpCount;
    const checkpoints = this.player.checkpoints;

    let prize = 0;
    if (this.mode === 'career' && this.careerEvent) {
      const mult = [0, 1, 0.62, 0.42, 0.28, 0.18, 0.12][place] ?? 0.1;
      prize = Math.round(this.careerEvent.prize * mult);
    } else if (this.mode === 'time') {
      prize = 150;
    } else {
      prize = [0, 240, 170, 120, 90, 65, 45][place] ?? 40;
    }
    const total = prize + coinsCollected;

    const prevBest = this.mode === 'time'
      ? this.progress.save.bestTimes.timeTrial
      : this.mode === 'quick'
        ? this.progress.save.bestTimes.quick
        : this.progress.save.career[this.careerEvent?.id]?.time;
    const newBest = !prevBest || timeSec < prevBest;

    const beforeUnlocked = this.progress.careerUnlockedCount();
    const missionBefore = this.progress.missions.map((m) => m.progress);
    this.progress.recordRace({
      place, time: timeSec, bestLap, topSpeed,
      coinsCollected, drift, boosts, jumps, checkpoints,
      mode: this.mode, eventId: this.careerEvent?.id,
    });
    this.progress.addCoins(total);
    const afterUnlocked = this.progress.careerUnlockedCount();
    const missions = this.progress.missions;
    const changed = missions.filter((m, i) => m.progress > missionBefore[i]).length;
    const ready = missions.filter((m) => !m.claimed && m.progress >= m.target).length;

    let title = 'River champion';
    let sub = 'Untouchable. The current is yours.';
    if (place === 2) { title = 'So close'; sub = 'One better line. One more boost.'; }
    else if (place === 3) { title = 'On the podium'; sub = 'The pack sees your spray now.'; }
    else if (place > 3) { title = 'Keep carving'; sub = 'Study the current. Come back sharper.'; }
    if (this.mode === 'time') {
      title = newBest ? 'New river record' : 'Time logged';
      sub = newBest ? 'Your name is written in the current.' : 'Chase that ghost a little further.';
    }
    if (afterUnlocked > beforeUnlocked) sub += ' Next cup unlocked.';

    this.pendingResult = {
      kicker: this.mode === 'career' && this.careerEvent ? this.careerEvent.name.toUpperCase() : this.mode === 'time' ? 'TIME TRIAL' : 'QUICK RACE',
      place,
      title,
      sub,
      time: timeSec,
      bestLap,
      topSpeed,
      prize: total,
      coins: coinsCollected,
      missionProgress: ready > 0 ? `${ready} READY` : `${changed} TRACKED`,
      total,
      newBest,
    };
    this.ui.refreshMenu();
    this.audio.finish(place === 1);
    this.haptic(place === 1 ? [25, 40, 25, 40, 70] : 30);
    this.raceResult = this.pendingResult;
  }

  haptic(pattern) {
    if (!this.progress.settings.haptics) return;
    if (navigator.vibrate) navigator.vibrate(pattern);
  }

  // ------------------------------------------------------------------
  // Cameras
  // ------------------------------------------------------------------
  menuCameraPose() {
    const f = this.track.getFrameAt(0.985);
    const t = this.menuTime;
    const pos = f.pos.clone()
      .addScaledVector(f.tangent, -8.5 - Math.sin(t * 0.12) * 1.1)
      .addScaledVector(f.left, 8.6 + Math.sin(t * 0.09) * 1.3);
    pos.y = 4.15 + Math.sin(t * 0.16) * 0.25;
    const look = f.pos.clone()
      .addScaledVector(f.tangent, 16)
      .addScaledVector(f.left, this.isPortrait ? 8.5 : 5.0);
    look.y = 1.4;
    return { pos, look };
  }

  snapMenuCamera() {
    const pose = this.menuCameraPose();
    this.camera.position.copy(pose.pos);
    this.cameraLook.copy(pose.look);
    this.camera.lookAt(this.cameraLook);
    this.camera.fov = this.baseFov || 62;
    this.camera.updateProjectionMatrix();
  }

  updateMenuCamera(dt) {
    const pose = this.menuCameraPose();
    const k = 1 - Math.exp(-2.6 * dt);
    this.camera.position.lerp(pose.pos, k);
    this.cameraLook.lerp(pose.look, k);
    this.camera.lookAt(this.cameraLook);
    this.camera.fov = damp(this.camera.fov, (this.baseFov || 62) + 1.5, 2, dt);
    this.camera.updateProjectionMatrix();
  }

  countdownCameraPose() {
    const p = this.player;
    const forward = TMP_A.set(Math.sin(p.yaw), 0, Math.cos(p.yaw));
    const right = TMP_B.set(forward.z, 0, -forward.x);
    const angle = 0.75 + Math.sin(this.menuTime * 0.24) * 0.18;
    const pos = p.position.clone()
      .addScaledVector(right, Math.sin(angle) * 7.4)
      .addScaledVector(forward, -Math.cos(angle) * 7.0);
    pos.y = (p.waterY || 0) + 3.35;
    const look = p.position.clone().addScaledVector(forward, 5.5);
    look.y = (p.waterY || 0) + 1.05;
    return { pos, look };
  }

  snapCountdownCamera() {
    const pose = this.countdownCameraPose();
    this.camera.position.copy(pose.pos);
    this.cameraLook.copy(pose.look);
    this.camera.lookAt(this.cameraLook);
    this.camera.fov = (this.baseFov || 62) - 3;
    this.camera.updateProjectionMatrix();
  }

  updateCamera(dt) {
    if (this.state === 'countdown') {
      const pose = this.countdownCameraPose();
      const k = 1 - Math.exp(-3.2 * dt);
      this.camera.position.lerp(pose.pos, k);
      this.cameraLook.lerp(pose.look, k);
      this.camera.lookAt(this.cameraLook);
      this.camera.fov = damp(this.camera.fov, (this.baseFov || 62) - 2, 2, dt);
      this.camera.updateProjectionMatrix();
      return;
    }
    if (this.state !== 'racing') return;

    const p = this.player;
    const speedN = clamp(p.speed / 40, 0, 1.1);
    const forward = TMP_A.set(Math.sin(p.yaw), 0, Math.cos(p.yaw));
    const right = TMP_B.set(forward.z, 0, -forward.x);
    const portrait = this.isPortrait;
    const dist = (portrait ? 10.2 : 8.7) + speedN * 1.4;
    const height = (portrait ? 4.65 : 3.95) + speedN * 0.45;
    const airLift = p.airborne ? p.elevation * 0.55 : 0;
    const pos = p.position.clone()
      .addScaledVector(forward, -dist)
      .addScaledVector(right, -p.steerVisual * 0.55);
    pos.y = (p.waterY || 0) + height + airLift;
    const look = p.position.clone()
      .addScaledVector(forward, 10 + speedN * 7)
      .addScaledVector(right, p.steerVisual * 0.6);
    look.y = (p.waterY || 0) + 1.15 + (p.airborne ? p.elevation * 0.4 : 0);

    const k = 1 - Math.exp(-6.2 * dt);
    this.camera.position.lerp(pos, k);
    this.cameraLook.lerp(look, 1 - Math.exp(-7.5 * dt));
    if (this.shake > 0.001) {
      const s = this.shake * 0.55;
      this.camera.position.x += (Math.random() - 0.5) * s;
      this.camera.position.y += (Math.random() - 0.5) * s * 0.6;
      this.camera.position.z += (Math.random() - 0.5) * s;
      this.cameraLook.y += (Math.random() - 0.5) * s * 0.25;
    }
    this.camera.lookAt(this.cameraLook);
    const fov = (this.baseFov || 62) + speedN * 4 + p.boostVisual * 7;
    this.camera.fov = damp(this.camera.fov, fov, 4, dt);
    this.camera.updateProjectionMatrix();
  }

  updateOrbitCamera(angle, results) {
    const p = this.player;
    const pos = p.position.clone();
    pos.x += Math.sin(angle) * (results ? 8.2 : 9.4);
    pos.z += Math.cos(angle) * (results ? 8.2 : 9.4);
    pos.y = (p.waterY || 0) + (results ? 4.1 : 3.6);
    this.camera.position.lerp(pos, 0.06);
    const look = p.position.clone();
    look.y = (p.waterY || 0) + 1.0;
    this.cameraLook.lerp(look, 0.12);
    this.camera.lookAt(this.cameraLook);
    this.camera.fov = damp(this.camera.fov, (this.baseFov || 62) + 2, 2, 1 / 60);
    this.camera.updateProjectionMatrix();
  }
}

