507:   tick(rawDt) {
508:     this.menuTime += rawDt;
509:     this.fpsAccum += rawDt;
510:     this.fpsFrames++;
511:     if (this.fpsAccum > 2.4) {
512:       this.fps = this.fpsFrames / this.fpsAccum;
513:       this.fpsAccum = 0;
514:       this.fpsFrames = 0;
515:       if (this.quality === 'auto' && this.state === 'racing') {
516:         if (this.fps < 48 && this.qualityScale > 0.82) {
517:           this.qualityScale = Math.max(0.82, this.qualityScale - 0.06);
518:           this.applyQuality();
519:         } else if (this.fps > 57 && this.qualityScale < 1) {
520:           this.qualityScale = Math.min(1, this.qualityScale + 0.04);
521:           this.applyQuality();
522:         }
523:       }
524:     }
525: 
526:     this.timeScale = this.slowmoTimer > 0
527:       ? damp(this.timeScale, 0.42, 7, rawDt)
528:       : damp(this.timeScale, 1, 4, rawDt);
529:     this.slowmoTimer = Math.max(0, this.slowmoTimer - rawDt);
530:     const dt = rawDt * this.timeScale;
531:     this.worldTime += rawDt * (this.slowmoTimer > 0 ? 0.6 : 1);
532:     this.shake = Math.max(0, this.shake - rawDt * 1.8);
533: 
534:     this.input.update(rawDt);
535: 
536:     if (this.state === 'menu') {
537:       this.updateMenu(rawDt);
538:     } else if (this.state === 'countdown') {
539:       this.updateCountdown(rawDt);
540:       this.updateWorldIdle(rawDt);
541:       this.updateCamera(rawDt);
542:       this.ui.updateHUD(this.buildHUDState());
543:       this.hudTimer = 0;
544:       this.audio.update(rawDt, { speed: 0, maxSpeed: this.player.maxSpeed, active: false, opponents: this.opponents, player: this.player });
545:     } else if (this.state === 'racing') {
546:       this.updateRace(dt, rawDt);
547:     } else if (this.state === 'finished') {
548:       this.updateFinished(rawDt);
549:     } else if (this.state === 'results') {
550:       this.updateResults(rawDt);
551:     } else if (this.state === 'paused') {
552:       this.water.update(this.worldTime);
553:     }
554: 
555:     this.effects.update(this.state === 'paused' ? 0 : dt);
556:   }
