573:   updateCountdown(rawDt) {
574:     this.countdown -= rawDt;
575:     const remain = this.countdown;
576:     let stage = 3;
577:     if (remain <= 2.55) stage = 2;
578:     if (remain <= 1.55) stage = 1;
579:     if (remain <= 0.55) stage = 0;
580:     if (stage !== this.countdownStage) {
581:       this.countdownStage = stage;
582:       if (stage > 0) {
583:         this.ui.updateCountdown(stage, stage === 1 ? 'HOLD THE LINE' : 'READY');
584:         this.environment.setStartLights(stage);
585:         this.audio.countdown(stage);
