200:   cacheMinimap() {
201:     const track = this.game.track;
202:     if (!track) return;
203:     const pts = [];
204:     for (let i = 0; i <= 240; i++) {
205:       const f = track.getFrameAt(i / 240);
206:       pts.push({ x: f.pos.x, z: f.pos.z });
207:     }
208:     let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
209:     for (const p of pts) {
210:       minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x);
211:       minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z);
212:     }
213:     this.mapBounds = { minX, maxX, minZ, maxZ };
214:     this.mapPoints = pts;
215:   }
216: 
217:   mapXY(x, z) {
218:     const size = 220;
219:     const pad = 32;
220:     const b = this.mapBounds;
221:     const spanX = b.maxX - b.minX;
222:     const spanZ = b.maxZ - b.minZ;
223:     const scale = (size - pad * 2) / Math.max(spanX, spanZ);
224:     const cx = (b.minX + b.maxX) / 2;
225:     const cz = (b.minZ + b.maxZ) / 2;
226:     return {
227:       x: size / 2 + (x - cx) * scale,
228:       y: size / 2 + (z - cz) * scale,
229:     };
230:   }
231: 
232:   drawMinimap(racers, player, position) {
233:     const canvas = $('minimap');
234:     if (!canvas || !this.mapPoints) return;
235:     const ctx = canvas.getContext('2d');
236:     const size = 220;
237:     ctx.clearRect(0, 0, size, size);
238:     ctx.save();
239:     ctx.beginPath();
240:     ctx.arc(size / 2, size / 2, size / 2 - 1, 0, Math.PI * 2);
241:     ctx.clip();
242:     ctx.fillStyle = 'rgba(4,30,26,.42)';
243:     ctx.fillRect(0, 0, size, size);
244: 
245:     // Jungle haze
246:     const grad = ctx.createRadialGradient(size / 2, size / 2, 10, size / 2, size / 2, size / 2);
247:     grad.addColorStop(0, 'rgba(58,125,88,.18)');
248:     grad.addColorStop(1, 'rgba(10,48,38,.05)');
249:     ctx.fillStyle = grad;
250:     ctx.fillRect(0, 0, size, size);
251: 
252:     const drawPath = (width, color) => {
253:       ctx.beginPath();
254:       this.mapPoints.forEach((p, i) => {
255:         const q = this.mapXY(p.x, p.z);
256:         if (i === 0) ctx.moveTo(q.x, q.y);
257:         else ctx.lineTo(q.x, q.y);
258:       });
259:       ctx.closePath();
260:       ctx.lineWidth = width;
261:       ctx.lineJoin = 'round';
262:       ctx.lineCap = 'round';
263:       ctx.strokeStyle = color;
264:       ctx.stroke();
265:     };
266:     drawPath(17, 'rgba(2,22,18,.55)');
267:     drawPath(12, '#2f6b5b');
268:     drawPath(7, '#72bda5');
269:     drawPath(2.5, 'rgba(210,255,232,.5)');
270: 
271:     // Checkpoint pips
272:     const track = this.game.track;
273:     if (track) {
274:       ctx.fillStyle = 'rgba(216,255,93,.65)';
275:       track.gateFractions.forEach((f) => {
276:         const fr = track.getFrameAt(f);
277:         const q = this.mapXY(fr.pos.x, fr.pos.z);
278:         ctx.beginPath();
279:         ctx.arc(q.x, q.y, 2, 0, Math.PI * 2);
280:         ctx.fill();
281:       });
282:     }
283: 
284:     // Rival dots
285:     for (const r of racers) {
286:       if (r === player) continue;
287:       const q = this.mapXY(r.position.x, r.position.z);
288:       ctx.beginPath();
289:       ctx.arc(q.x, q.y, 3.6, 0, Math.PI * 2);
290:       ctx.fillStyle = r.profile?.c1 || '#ff8a3d';
291:       ctx.fill();
292:       ctx.strokeStyle = 'rgba(4,28,24,.8)';
293:       ctx.lineWidth = 1.5;
294:       ctx.stroke();
295:     }
296: 
297:     // Player arrow
298:     const q = this.mapXY(position.x, position.z);
299:     ctx.save();
300:     ctx.translate(q.x, q.y);
301:     const b = this.mapBounds;
302:     const spanX = b.maxX - b.minX;
303:     const spanZ = b.maxZ - b.minZ;
304:     const scale = (size - 64) / Math.max(spanX, spanZ);
305:     ctx.rotate(Math.atan2(Math.sin(player.yaw), Math.cos(player.yaw)));
306:     ctx.beginPath();
307:     ctx.moveTo(0, -7.5);
308:     ctx.lineTo(5, 5.5);
309:     ctx.lineTo(0, 2.6);
310:     ctx.lineTo(-5, 5.5);
311:     ctx.closePath();
312:     ctx.fillStyle = '#d8ff5d';
313:     ctx.shadowColor = 'rgba(216,255,93,.9)';
314:     ctx.shadowBlur = 8;
315:     ctx.fill();
316:     ctx.restore();
317:     ctx.restore();
318: 
319:     // Ring highlight
320:     ctx.beginPath();
321:     ctx.arc(size / 2, size / 2, size / 2 - 1, 0, Math.PI * 2);
322:     ctx.strokeStyle = 'rgba(216,255,93,.18)';
323:     ctx.lineWidth = 2;
324:     ctx.stroke();
325:   }
