393:   onPanelClick(e) {
394:     const target = e.target.closest('[data-action], [data-select], [data-buy], [data-upgrade], [data-event], [data-claim], [data-claim-mission], [data-close], [data-setting], [data-quality], [data-toggle], [data-calibrate], [data-reset]');
395:     if (!target) return;
396:     this.game.audio?.ui?.();
397:     if (target.hasAttribute('data-close')) { this.closePanel(); return; }
398:     const action = target.getAttribute('data-action');
399:     if (action === 'open-career') return this.openCareer();
400:     if (action === 'open-garage') return this.openGarage();
401:     if (action === 'open-daily') return this.openDaily();
402:     if (action === 'claim-daily') {
403:       const r = this.progress.claimDaily();
404:       if (r) {
405:         this.game.audio.pickup('coin');
406:         this.toast(`Day ${r.day} gift claimed · +${r.amount} coins`);
407:         this.openDaily();
408:       }
409:       return;
410:     }
411:     if (target.hasAttribute('data-select')) {
412:       this.garagePreview = target.getAttribute('data-select');
413:       this.openGarage();
414:       return;
415:     }
416:     if (target.hasAttribute('data-buy')) {
417:       const id = target.getAttribute('data-buy');
418:       if (this.progress.buyJetSki(id)) {
419:         this.garagePreview = id;
420:         this.game.onJetSkiChanged();
421:         this.game.audio.pickup('nitro');
422:         this.toast(`${this.progress.jetSki(id).name} is yours`);
423:         this.openGarage();
424:       } else {
425:         this.toast('Not enough coins — win some races');
426:       }
427:       return;
428:     }
429:     if (target.hasAttribute('data-upgrade')) {
430:       const key = target.getAttribute('data-upgrade');
431:       if (this.progress.upgrade(this.garagePreview, key)) {
432:         this.game.onJetSkiChanged();
433:         this.game.audio.pickup('shield');
434:         this.openGarage();
435:       } else {
436:         this.toast('Not enough coins for that upgrade');
437:       }
438:       return;
439:     }
440:     if (target.hasAttribute('data-event')) {
441:       const id = target.getAttribute('data-event');
442:       const ev = CAREER_EVENTS.find((x) => x.id === id);
443:       if (ev && this.progress.isCareerUnlocked(ev)) {
444:         this.closePanel();
445:         this.game.startRace({ mode: 'career', event: ev });
446:       } else {
447:         this.toast('Finish the previous cup in the top 3 to unlock');
448:       }
449:       return;
450:     }
451:     if (target.hasAttribute('data-claim-mission')) {
452:       const id = target.getAttribute('data-claim-mission');
453:       const amount = this.progress.claimMission(id);
454:       if (amount) {
455:         this.game.audio.pickup('coin');
456:         this.toast(`Mission complete · +${amount} coins`);
457:         this.openDaily();
458:       }
459:       return;
460:     }
461:     if (target.hasAttribute('data-setting')) {
462:       const scheme = target.getAttribute('data-setting');
463:       this.game.setControlScheme(scheme).then((ok) => {
464:         if (!ok) this.toast('Tilt needs motion permission on this device');
465:         this.openSettings(this.activePanel === 'settings-pause');
466:       });
467:       return;
468:     }
469:     if (target.hasAttribute('data-quality')) {
470:       this.progress.updateSettings({ quality: target.getAttribute('data-quality') });
471:       this.game.setQuality(this.progress.settings.quality);
472:       this.openSettings(this.activePanel === 'settings-pause');
473:       return;
474:     }
475:     if (target.hasAttribute('data-toggle')) {
476:       const key = target.getAttribute('data-toggle');
477:       const val = !this.progress.settings[key];
478:       this.progress.updateSettings({ [key]: val });
479:       if (key === 'sound') this.game.audio.setMuted(!val);
480:       if (key === 'haptics' && val && navigator.vibrate) navigator.vibrate(30);
481:       this.openSettings(this.activePanel === 'settings-pause');
482:       return;
483:     }
484:     if (target.hasAttribute('data-calibrate')) {
485:       this.game.input.calibrateTilt();
486:       this.toast('Tilt centre calibrated — hold still');
487:       return;
488:     }
489:     if (target.hasAttribute('data-reset')) {
490:       if (window.confirm('Reset all coins, rides, upgrades and progress?')) {
491:         this.progress.reset();
492:         this.game.onJetSkiChanged();
493:         this.closePanel();
494:         this.refreshMenu();
495:         this.toast('Progress reset');
496:       }
497:       return;
498:     }
499:   }
