608:   openDaily() {
609:     const p = this.progress;
610:     const day = p.dailyDayIndex();
611:     const available = p.dailyAvailable();
612:     const streak = p.save.daily.streak || 0;
613:     const rewards = [100, 150, 200, 250, 300, 400, 600];
614:     const dayCards = rewards.map((amount, i) => {
615:       const claimed = available ? i + 1 < day : i + 1 <= streak;
616:       return `
617:         <div class="day-card ${i + 1 === day && available ? 'today' : ''} ${claimed ? 'claimed' : ''}">
618:           <span>DAY ${i + 1}</span>
619:           <span class="coin-glyph">●</span>
620:           <b>${amount}</b>
621:         </div>`;
622:     }).join('');
