198:   buildTerrain() {
199:     const rows = 300;
200:     const sides = [-1, 1];
201:     const ringSpecs = [
202:       { add: 1.8, y: -0.7 },
203:       { add: 6, y: null },
204:       { add: 15, y: null },
205:       { add: 25, y: null },
206:       { add: 40, y: null },
207:       { add: 65, y: null },
208:       { add: 95, y: null },
209:     ];
210:     const colors = [new THREE.Color('#d8bd82'), new THREE.Color('#cab373'), new THREE.Color('#a3a463'), new THREE.Color('#69904b'), new THREE.Color('#427a3f'), new THREE.Color('#356d3b'), new THREE.Color('#2b5b35')];
211:     const pos = [];
212:     const col = [];
213:     const idx = [];
214:     for (const side of sides) {
215:       const base = pos.length / 3;
216:       for (let j = 0; j <= rows; j++) {
217:         const t = j / rows;
218:         const f = this.track.getFrameAt(t);
219:         const half = f.width / 2;
220:         for (let r = 0; r < ringSpecs.length; r++) {
221:           const spec = ringSpecs[r];
222:           const absLat = half + spec.add;
223:           const lateral = absLat * side;
224:           const y = spec.y ?? this.track.bankHeight(t, absLat);
225:           const wobble = this.noise(t * 35, r * 7.1) - 0.5;
226:           const x = f.pos.x + f.left.x * lateral;
227:           const z = f.pos.z + f.left.z * lateral;
228:           pos.push(x, y + (r > 1 ? wobble * (r - 1) * 0.42 : 0), z);
229:           const c = colors[r].clone();
230:           if (r >= 3) {
231:             const n = this.noise(x * 0.06, z * 0.06);
232:             c.offsetHSL((n - 0.5) * 0.025, (n - 0.5) * 0.08, (n - 0.5) * 0.1);
233:           }
234:           if (r === 1 && this.noise(t * 90, side) > 0.52) c.lerp(colors[2], 0.65);
235:           if (r === 0) c.set('#c8a96e');
236:           col.push(c.r, c.g, c.b);
237:         }
238:       }
239:       for (let j = 0; j < rows; j++) {
240:         for (let r = 0; r < ringSpecs.length - 1; r++) {
241:           const a = base + j * ringSpecs.length + r;
242:           const b = a + 1;
243:           const c = a + ringSpecs.length;
244:           const d = c + 1;
245:           if (side === 1) idx.push(a, c, b, b, c, d);
246:           else idx.push(a, b, c, b, d, c);
247:         }
248:       }
249:     }
250:     const geo = new THREE.BufferGeometry();
251:     geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
252:     geo.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
253:     geo.setIndex(idx);
254:     geo.computeVertexNormals();
255:     this.terrainMat = new THREE.MeshLambertMaterial({ vertexColors: true, flatShading: true });
256:     this.terrain = new THREE.Mesh(geo, this.terrainMat);
257:     this.terrain.receiveShadow = false;
258:     this.group.add(this.terrain);
259: 
260:     // A dark distant floor keeps gaps from showing at the horizon.
261:     const floor = new THREE.Mesh(
262:       new THREE.CircleGeometry(1400, 32),
263:       new THREE.MeshLambertMaterial({ color: '#244f36' }),
264:     );
265:     floor.rotation.x = -Math.PI / 2;
266:     floor.position.y = -28;
267:     this.group.add(floor);
268:   }
